INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-244','aishort-244','功能命名建议','office','适用于编程变量和概述描述命名。来自 @SuperMuscleMan 的投稿。','I am seeking suggestions for both English and Chinese names that are highly suitable for a description I provide. As a bilingual linguist, please help me generate appropriate names in both languages. The English name should be in camel case format.','我正在寻求高度适合我提供的描述的英文和中文名字的建议。作为一名双语语言学家，请帮助我生成合适的两种语言的名字。英文名称应采用骆驼字母的格式。','imported','aishort','244',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
