INSERT INTO skill_resources (id,metadata_json) VALUES ('systematic-debugging','{"id":"systematic-debugging","tasks":["debug"],"labels":{"zh":"系统排错","en":"Systematic debugging","ja":"体系的デバッグ"},"repository":"https://github.com/obra/superpowers","source":"https://github.com/obra/superpowers/tree/b36e0829c6d0140e93cfef2ca599b1b07d4a7797/skills/systematic-debugging","commit":"b36e0829c6d0140e93cfef2ca599b1b07d4a7797","license":"MIT","language":"en","edition":"upstream-documentation","review":"source-and-license-checked; not-runtime-tested","usage":{"zh":"这是上游英文 Skill 的文档包，使用说明提供中英日版本；不含模型、API Key、脚本或软件安装。解压后，将对应 Skill 文件夹导入支持 SKILL.md 的 AI 工具；具体位置以该工具说明为准。普通聊天工具可打开 SKILL.md，将适用的指令与网站生成的提示词一同粘贴。指定用中文回答。先让 AI 列明缺少的资料与能力；没有文件或媒体工具时仅输出内容与步骤，不声称已经生成文件。上游提及的其他 Skill、脚本、工具集成不包含在本包中；需要时另行核对并安装。模型、价格、功能与命令须核对目标工具的官方文档。不要复制示例中的统计数字作为事实；不要输出密钥或环境变量。由使用者确认工具调用与费用。","en":"This package contains the original English Skill documents, with instructions in Chinese, English and Japanese. It includes no model, API key, executable scripts or installer. Extract and import the Skill folder into a tool supporting SKILL.md, following that tool’s documented location. In a plain chat tool, paste the relevant instructions together with the generated prompt. Request an English answer. Ask the AI to identify missing inputs and capabilities first; without file/media tools, return content and steps without claiming files were generated. Referenced external skills, scripts and integrations are not bundled. Verify model capabilities, prices and commands against official documentation. Do not reuse example statistics as facts or print secrets/environment variables. Confirm tool actions and costs yourself.","ja":"上流の英語 Skill 文書と、中国語・英語・日本語の使用説明を収録。モデル、APIキー、実行スクリプト、インストーラーは含みません。展開後、SKILL.md 対応ツールの公式手順でフォルダーを取り込んでください。通常のチャットでは必要な指示と生成したプロンプトを貼り付け、日本語での回答を指定します。まず不足資料と機能を確認し、ファイル・媒体操作ができなければ本文と手順を出し、生成済みとしないこと。参照先の外部Skill、スクリプト、連携機能は別途必要です。モデル・料金・機能・コマンドは公式文書で確認。例示の統計値を事実として転用せず、秘密情報や環境変数を出力しないこと。操作と費用は利用者が確認します。"},"files":[{"path":"CREATION-LOG.md","sha256":"c24733a5b1821bd6bed1fc950261f0b9f4e90097e0bbb96459d8179713730789"},{"path":"SKILL.md","sha256":"808fc5717aa88ad65efff312b11c186294d3e6ee301afb584e2f86599b137787"},{"path":"condition-based-waiting.md","sha256":"e89fec8400d6cd50f43407cec9fab50976ba4d55d0ec2eb51c0bd68036b54c26"},{"path":"defense-in-depth.md","sha256":"1e175fb86fc357e58c6aebf5441e481e1b7868b4380c0456b63a17eefbd18ba7"},{"path":"root-cause-tracing.md","sha256":"6b0622269e098ca1399e123e553fd385f0b6412d88ef0e9c4f5a8ea9cf1cec7b"},{"path":"test-academic.md","sha256":"fe2ba480d78ac0d686dc025f41c2a32a43d642bf533f91b0c6053a04d35d6486"},{"path":"test-pressure-1.md","sha256":"0b6a915db0054577819834c79be9eb614e97bddba10d73768e1fbe91cfed048a"},{"path":"test-pressure-2.md","sha256":"b2030aeffba07050e8ad573ddf87486457c4a016a786bb326235bebd856f2016"},{"path":"test-pressure-3.md","sha256":"96b50a52e2c7989c9cf20fb752c47c1e9a3a70dc362f8f7989f8f5b64dac7708"}],"download":"/downloads/skills/systematic-debugging-b36e0829c6d0.zip","sha256":"4f653c2fce572f1bac97f11e791755dfdc2c4f1c55626e0df9da11d5a7f41417","bytes":22561,"fit":{"exclude":["从零开发","from scratch","ゼロから開発"],"scope":{"zh":"适合复现故障、定位根因和验证修复；不替代从零开发或全面代码审查。","en":"For reproduction, root-cause analysis and fix verification; not a substitute for new development or a full code review.","ja":"再現・原因究明・修正確認向け。新規開発や総合コードレビューの代替ではありません。"},"additionalTasks":["testing-focused-flaky"]}}') ON CONFLICT(id) DO UPDATE SET metadata_json=excluded.metadata_json;
INSERT INTO skill_resources (id,metadata_json) VALUES ('wps-formula','{"id":"wps-formula","tasks":["wps-sheet"],"labels":{"zh":"WPS 表格公式（适配版）","en":"WPS formulas (adapted)","ja":"WPS数式（調整版）"},"repository":"https://github.com/Bwkyd/wps-skills","source":"https://github.com/Bwkyd/wps-skills/tree/50b04859b7768ed23477d7d2af9b8fb83b27adf3/skills/wps-formula","commit":"50b04859b7768ed23477d7d2af9b8fb83b27adf3","license":"MIT","language":"en","edition":"adapted-documentation","review":"source-and-license-checked; not-runtime-tested","usage":{"zh":"这是根据上游中文内容整理的英文适配 Skill 文档包；已移除笼统的函数版本断言，使用说明提供中英日版本；不含模型、API Key、脚本或软件安装。解压后，将对应 Skill 文件夹导入支持 SKILL.md 的 AI 工具；具体位置以该工具说明为准。普通聊天工具可打开 SKILL.md，将适用的指令与网站生成的提示词一同粘贴。指定用中文回答。先让 AI 列明缺少的资料与能力；没有文件或媒体工具时仅输出内容与步骤，不声称已经生成文件。上游提及的其他 Skill、脚本、工具集成不包含在本包中；需要时另行核对并安装。模型、价格、功能与命令须核对目标工具的官方文档。不要复制示例中的统计数字作为事实；不要输出密钥或环境变量。由使用者确认工具调用与费用。","en":"This package contains an English adaptation of the Chinese upstream Skill, with blanket function-version claims removed, with instructions in Chinese, English and Japanese. It includes no model, API key, executable scripts or installer. Extract and import the Skill folder into a tool supporting SKILL.md, following that tool’s documented location. In a plain chat tool, paste the relevant instructions together with the generated prompt. Request an English answer. Ask the AI to identify missing inputs and capabilities first; without file/media tools, return content and steps without claiming files were generated. Referenced external skills, scripts and integrations are not bundled. Verify model capabilities, prices and commands against official documentation. Do not reuse example statistics as facts or print secrets/environment variables. Confirm tool actions and costs yourself.","ja":"上流の中国語Skillを英語に調整し、一律の関数バージョン断定を除いた文書と、中国語・英語・日本語の使用説明を収録。モデル、APIキー、実行スクリプト、インストーラーは含みません。展開後、SKILL.md 対応ツールの公式手順でフォルダーを取り込んでください。通常のチャットでは必要な指示と生成したプロンプトを貼り付け、日本語での回答を指定します。まず不足資料と機能を確認し、ファイル・媒体操作ができなければ本文と手順を出し、生成済みとしないこと。参照先の外部Skill、スクリプト、連携機能は別途必要です。モデル・料金・機能・コマンドは公式文書で確認。例示の統計値を事実として転用せず、秘密情報や環境変数を出力しないこと。操作と費用は利用者が確認します。"},"files":[{"path":"SKILL.md","sha256":"1d449291f665f230fe6638962d50ed565e3fbc328201c2ceb802d12d31ef301e"}],"download":"/downloads/skills/wps-formula-50b04859b776.zip","sha256":"5b10c6f8d44ca541cfb4d133ab6db4806f01b97f124451657529bcff34fcff95","bytes":7135,"fit":{"exclude":["透视表","数据清洗","去重","图表","宏","pivot table","data cleaning","deduplication","chart","macro","ピボット","データ整形","重複削除","グラフ","マクロ"],"scope":{"zh":"适合查找、条件汇总、文本日期公式和公式排错；不提供透视表、图表、数据清洗或宏自动化。需核对实际WPS版本。","en":"For lookups, conditional totals, text/date formulas and formula errors; not pivot tables, charts, data cleaning or macros. Verify the actual WPS version.","ja":"検索・条件集計・文字列/日付数式・数式エラー向け。ピボット・グラフ・データ整形・マクロは対象外。WPSの版を確認してください。"},"additionalTasks":["office-focused-formula-error"]}}') ON CONFLICT(id) DO UPDATE SET metadata_json=excluded.metadata_json;
INSERT INTO skill_resources (id,metadata_json) VALUES ('scientific-writing','{"id":"scientific-writing","tasks":["paper-outline","paper-draft","paper-format","paper-revise"],"labels":{"zh":"科学论文写作（无脚本适配版）","en":"Scientific writing (instruction-only)","ja":"科学論文執筆（スクリプト不要版）"},"repository":"https://github.com/K-Dense-AI/claude-scientific-skills","source":"https://github.com/K-Dense-AI/claude-scientific-skills/tree/330c8e764435a731eff571e3efdda70b363d0792/skills/scientific-writing","commit":"330c8e764435a731eff571e3efdda70b363d0792","license":"MIT","language":"en","edition":"adapted-documentation","review":"entrypoint-dependencies-and-package-checked; external-ai-runtime-not-tested","usage":{"zh":"本包为无脚本适配版：按用户资料整理结构、正文、图表说明和审稿回复。入口不依赖 Python 或其他 Skill；参考文档中的上游命令不适用于本包。证据核验需要原始资料或目标 AI 的检索能力，不能凭此保证论文事实或投稿合规。\n\n解压后导入支持 SKILL.md 的工具；普通聊天中粘贴 SKILL.md 和网站生成的提示词，并附可分享的研究资料。请指定回答语言。不包含模型或生成文件的工具。","en":"Instruction-only adaptation for outlines, drafts, captions and reviewer responses. The entrypoint needs no Python or external Skill. Upstream commands in reference documents are outside this edition. Evidence verification requires original sources or research tools; this does not certify factual accuracy or submission compliance.\n\nExtract into a tool supporting SKILL.md, or paste SKILL.md and your generated prompt into chat with shareable research material. Specify the response language. No model or file-generation tools are included.","ja":"構成・本文・図表説明・査読回答を扱うスクリプト不要の調整版です。入口はPythonや外部Skillに依存しません。参考文書の上流コマンドは本版の対象外です。証拠確認には原資料や検索機能が必要で、事実や投稿規則への適合を保証しません。\n\n展開してSKILL.md対応ツールに導入するか、文書と生成したプロンプトを共有可能な研究資料とともにチャットへ貼り付けてください。回答言語を指定してください。モデルやファイル生成機能は含みません。"},"files":[{"path":"assets/authorship_template.json","sha256":"04a590ac47ed61dcc7cd88a26d51243cf178fe6ada99d4000ca225e1b5f6f20a"},{"path":"assets/claim_evidence_template.csv","sha256":"cfb7a9f44cd1e5ef47ccdb3e32ac0a25b72d30e51343faace9bf07c00e3a0659"},{"path":"assets/consistency_manifest_template.json","sha256":"2ea6f468