INSERT INTO skill_resources (id,metadata_json) VALUES ('content-strategy','{"id":"content-strategy","tasks":["content-roadmap"],"labels":{"zh":"内容策略","en":"Content strategy","ja":"コンテンツ戦略"},"repository":"https://github.com/coreyhaines31/marketingskills","source":"https://github.com/coreyhaines31/marketingskills/tree/5b2c0007766c6a1cf1d53fd8fc73e979e0821022/skills/content-strategy","commit":"5b2c0007766c6a1cf1d53fd8fc73e979e0821022","license":"MIT","language":"en","edition":"upstream-documentation","review":"source-and-license-checked; not-runtime-tested","usage":{"zh":"这是上游英文 Skill 的文档包，使用说明提供中英日版本；不含模型、API Key、脚本或软件安装。解压后，将对应 Skill 文件夹导入支持 SKILL.md 的 AI 工具；具体位置以该工具说明为准。普通聊天工具可打开 SKILL.md，将适用的指令与网站生成的提示词一同粘贴。指定用中文回答。先让 AI 列明缺少的资料与能力；没有文件或媒体工具时仅输出内容与步骤，不声称已经生成文件。上游提及的其他 Skill、脚本、工具集成不包含在本包中；需要时另行核对并安装。模型、价格、功能与命令须核对目标工具的官方文档。不要复制示例中的统计数字作为事实；不要输出密钥或环境变量。由使用者确认工具调用与费用。","en":"This package contains the original English Skill documents, with instructions in Chinese, English and Japanese. It includes no model, API key, executable scripts or installer. Extract and import the Skill folder into a tool supporting SKILL.md, following that tool’s documented location. In a plain chat tool, paste the relevant instructions together with the generated prompt. Request an English answer. Ask the AI to identify missing inputs and capabilities first; without file/media tools, return content and steps without claiming files were generated. Referenced external skills, scripts and integrations are not bundled. Verify model capabilities, prices and commands against official documentation. Do not reuse example statistics as facts or print secrets/environment variables. Confirm tool actions and costs yourself.","ja":"上流の英語 Skill 文書と、中国語・英語・日本語の使用説明を収録。モデル、APIキー、実行スクリプト、インストーラーは含みません。展開後、SKILL.md 対応ツールの公式手順でフォルダーを取り込んでください。通常のチャットでは必要な指示と生成したプロンプトを貼り付け、日本語での回答を指定します。まず不足資料と機能を確認し、ファイル・媒体操作ができなければ本文と手順を出し、生成済みとしないこと。参照先の外部Skill、スクリプト、連携機能は別途必要です。モデル・料金・機能・コマンドは公式文書で確認。例示の統計値を事実として転用せず、秘密情報や環境変数を出力しないこと。操作と費用は利用者が確認します。"},"files":[{"path":"SKILL.md","sha256":"0ad572d607884c561668810f77cd21bbe3e0508c64090f2997661a728360f946"},{"path":"evals/evals.json","sha256":"10167e7125ee77cbabe4f03953750dd99ea147f7461027fdbb0cf8e089e5506d"},{"path":"references/content-distribution.md","sha256":"1861a1aab0627ab29c279000879a9889242da1ba85e677acdc759c66a6241778"},{"path":"references/headless-cms.md","sha256":"c0a7b87f47c8f7af907ce73facf1ed4721ade811e53f86ddf22f4bc0d7ca324e"}],"download":"/downloads/skills/content-strategy-5b2c0007766c.zip","sha256":"89533bec7f304acde593763968d12b87097d743de5a292217ab8cfd1ce6396cb","bytes":23806,"fit":{"exclude":["debug","报错","数式"],"scope":{"zh":"受众、内容主题与发布计划；具体单篇文案请使用文案模块。","en":"Audience, content themes and publishing plans; use copywriting for individual drafts.","ja":"読者、テーマ、公開計画の整理。個別原稿にはコピー作成を利用。"},"additionalTasks":[]}}') ON CONFLICT(id) DO UPDATE SET metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('build','published','{"id":"build","group":"programming","labels":{"zh":"新功能开发","en":"Feature implementation","ja":"新機能の実装"},"guidance":{"zh":"交付可运行实现：先用不超过5条列出需求与明确假设；给出文件目录及每个新增或修改文件的完整内容（按用户指定可改为差异补丁），不得用省略号代替核心代码；列出安装、配置、启动命令与环境变量名称，不填入真实密钥。说明接口输入输出、错误响应、空状态、加载状态和权限边界。提供最小样例及预期输出，并给出验收步骤；未执行测试须明确标记。非必要不引入新框架。","en":"Deliver a runnable implementation: begin with up to five requirements and explicit assumptions. Provide a file tree and complete contents of added or changed files, or a patch if requested; never replace core logic with ellipses. Include install, configuration and run commands and environment-variable names without real secrets. Define API inputs, outputs, errors, empty/loading states and permission boundaries. Supply a minimal example, expected output and acceptance steps. Label unexecuted tests. Avoid unnecessary framework changes.","ja":"実行可能な実装を納品してください。要件と仮定を5項目以内で示し、ファイル構成と追加・変更ファイルの全文（指定があれば差分）を出力します。核心となるコードを省略記号で置き換えず、導入・設定・起動コマンドと環境変数名を示してください。実際の秘密情報は記載しません。APIの入出力、エラー、空・読込状態、権限境界を定義し、最小の入力例、期待結果、受け入れ手順を付けます。未実行のテストは明記し、不要なフレームワーク変更を避けてください。"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('debug','published','{"id":"debug","group":"programming","labels":{"zh":"错误排查","en":"Debugging","ja":"不具合調査"},"guidance":{"zh":"交付故障修复报告与最小补丁：逐项对照预期行为、实际行为、复现步骤、完整报错和运行环境。把已证实原因与待验证假设分开；证据不足时先给最短诊断步骤，不假装已定位根因。指出具体文件或函数及修改理由，只改变与故障相关的逻辑。提供修复前失败用例、修复后预期结果、相邻功能回归检查和回退方法；不把清空数据或重装系统作为默认解决方案。","en":"Deliver a diagnosis and minimal patch. Compare expected and actual behavior, reproduction steps, full errors and environment. Separate confirmed causes from hypotheses; if evidence is missing, give the shortest diagnostic procedure instead of claiming a root cause. Identify the relevant files or functions and explain each change. Include a failing example, expected behavior after the fix, nearby regression checks and rollback steps. Do not default to wiping data or reinstalling the system.","ja":"原因調査と最小パッチを納品してください。期待動作、実際の動作、再現手順、エラー全文、実行環境を照合します。確認済み原因と仮説を分け、根拠不足なら最短の診断手順を示し、原因を断定しません。対象ファイル・関数と変更理由を明記し、関連ロジックだけを修正します。修正前の失敗例、修正後の期待結果、関連機能の回帰確認、戻し方を示します。データ削除やOS再導入を標準の解決策にしないでください。"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('review','published','{"id":"review","group":"programming","labels":{"zh":"代码审查","en":"Code review","ja":"コードレビュー"},"guidance":{"zh":"交付按影响排序的审查结果：每项包含位置、触发条件、具体后果、证据和最小修改建议；没有文件行号时引用函数名，勿编造行号。优先查正确性、数据与权限、错误处理、资源释放和性能瓶颈，格式偏好单独列为可选。给出关键问题的修复补丁和验证用例；未发现问题就如实说明，不凑数量，不将推测漏洞写成确定事实。","en":"Deliver findings ordered by impact, each with location, trigger, consequence, evidence and a minimal correction. Reference function names when line numbers are unavailable; never invent locations. Prioritize correctness, data handling, authorization, errors, resource cleanup and performance bottlenecks. Keep style preferences optional. Provide patches and verification cases for key findings. Report no findings when appropriate and distinguish suspected issues from confirmed defects.","ja":"影響順のレビュー結果を納品してください。各項目に場所、発生条件、具体的影響、根拠、最小修正案を記載します。行番号が不明なら関数名を使い、架空の行番号を付けません。正確性、データ処理、権限、エラー処理、リソース解放、性能を優先し、表記の好みは任意事項に分けます。重要な問題にはパッチと検証例を示し、問題がなければその旨を記載します。仮説を確定した不具合として扱わないでください。"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('image','published','{"id":"image","group":"visual","labels":{"zh":"AI 图片","en":"AI image","ja":"AI画像"},"guidance":{"zh":"只交付静态图片方案：明确用途（海报、产品图、角色设定等）、主体数量与外观、姿态、主体在画面中的位置、前中后景、光源方向与软硬、主辅色、材质、风格、画幅和文字区域。产品图突出材质及品牌识别，角色设定强调外观与服装一致，海报确认精确文案和留白。输出①简短画面说明②一段可直接粘贴的完整生图提示词③工具支持时的负面提示词④尺寸与参数建议⑤可检查的成图标准。图片中文字需逐字核对；不添加分镜时长或运镜指令。","en":"Deliver only a still-image brief. Specify use, subject count and appearance, pose, placement, foreground/background, light direction and softness, palette, materials, style, aspect ratio and text area. Emphasize material and identity for products, consistent appearance for character sheets, and exact copy and whitespace for posters. Output a short visual brief, a complete copyable image prompt, optional supported negative prompts, size/parameter suggestions and an inspection checklist. Verify rendered lettering. Do not add shot timing or camera movement.","ja":"静止画像の制作案だけを出力してください。用途、主体の数・外観・姿勢・配置、前中後景、光の方向と硬さ、配色、材質、スタイル、画面比率、文字領域を明確にします。商品画像は材質と識別性、設定画は外見と服装の一貫性、ポスターは正確な文言と余白を重視します。短い画面説明、コピー可能な完成プロンプト、対応時のみネガティブプロンプト、サイズ・設定案、検品項目を出力します。文字は一字ずつ確認し、カットの秒数やカメラ移動は追加しません。"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('clip','published','{"id":"clip","group":"visual","labels":{"zh":"图生视频 · 单镜头","en":"Image-to-video · single shot","ja":"画像から動画・単一カット"},"guidance":{"zh":"交付单镜头图生视频方案：将参考图中已存在的人物、服装、布景作为不变资产，缺少参考图时不要声称看过图片，先请求提供或明确这是待配图方案。明确起始状态、一个主要动作、动作速度与幅度、镜头移动方向、环境运动、结束状态和目标时长。输出①不可变化清单②时间顺序动作描述③完整可复制视频提示词④首尾衔接说明⑤稳定性检查。不要塞入多次切镜或同时要求互相冲突的运镜；工具能力未经确认时不保证时长、帧率或分辨率。","en":"Deliver a single-shot image-to-video plan. Treat the reference character, clothing and setting as fixed assets. If no image is available, request it or label this a plan awaiting a reference; do not claim to have inspected it. Specify the start state, one main action, speed and amplitude, camera direction, environmental motion, end state and target duration. Provide invariants, a chronological action description, one copyable video prompt, continuity notes and stability checks. Avoid multiple cuts or conflicting camera instructions. Do not guarantee unsupported duration, frame rate or resolution.","ja":"単一カットの画像から動画への制作案を出力してください。参考画像の人物、服装、背景を固定要素とします。画像がなければ提供を依頼するか参考画像待ちの案と明記し、見たことにしません。開始状態、主な動作1つ、速度と大きさ、カメラ方向、周囲の動き、終了状態、希望秒数を定義します。固定要素、時系列の動作、コピー可能な動画プロンプト、始終点のつながり、安定性の確認項目を示します。複数のカット切替や矛盾する運鏡を詰め込まず、未確認の秒数・フレームレート・解像度を保証しないでください。"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('storyboard','published','{"id":"storyboard","group":"visual","labels":{"zh":"多镜头动画","en":"Multi-shot animation","ja":"複数カットのアニメ"},"guidance":{"zh":"交付完整短片制作包：先明确主题、受众、叙事起承转合、角色动机、总时长、画幅和声音方案，再建立角色外观、服装、道具、场景与色彩的固定设定。分镜表必须逐镜包含镜号、起止时间、时长、景别、构图、动作、运镜、对白或旁白、音效、衔接方式。每镜分别给出静态关键帧提示词和动态视频提示词，不能只给概念大纲。核对各镜秒数之和等于总时长，检查动作方向、道具位置、角色服装与光源的连续性；最后附素材清单、制作顺序和剪辑检查表。\n\n景别规划：把每镜标为近景、中景或远景，并写明实际取景范围。远景交代空间与走位，中景承接动作与互动，近景呈现表情或细节；根据剧情需要分配，不机械循环。用户要求三种景别时，在总时长允许下分别给出对应镜头。改变景别时维持轴线、视线、动作和道具状态，分别输出三类可复制提示词，避免把剪辑切换写成一个连续单镜头。","en":"Deliver a complete short-film production pack. Define theme, audience, narrative arc, character motivation, total duration, aspect ratio and sound plan, then establish fixed character, costume, prop, setting and color references. For every shot list ID, start/end time, duration, framing, composition, action, camera motion, dialogue/narration, sound and transition. Supply separate still-keyframe and motion prompts for every shot, not just an outline. Check that shot durations add up to the requested total and that motion direction, props, costume and lighting remain continuous. Finish with an asset list, production order and editing checklist.\n\nShot-size planning: label each shot close, medium or wide and specify its actual crop. Wide establishes space, medium carries action/interaction, close reveals expression/detail; allocate by story needs rather than a fixed cycle. When all three are requested, include each within the available duration. Preserve axis, eyelines, action and prop states across changes. Provide separately copyable prompts and do not describe edited cuts as one continuous shot.","ja":"短編制作一式を出力してください。テーマ、対象視聴者、起承転結、人物の動機、総尺、画面比率、音の方針を定め、外見・衣装・小道具・舞台・色の固定設定を作ります。各カットに番号、開始・終了時刻、秒数、画角、構図、動作、運鏡、セリフやナレーション、効果音、つなぎ方を記載します。各カットの静止キーフレーム用と動画用のプロンプトを分け、概略だけで終わらせません。秒数の合計、動作方向、小道具、衣装、光源の連続性を確認し、素材一覧、制作順、編集チェック表を付けてください。\n\n景別設計：各カットを近景・中景・遠景とし、実際に写す範囲を明記する。遠景は場所、中景は動作や交流、近景は表情や細部を担う。物語に応じて配分し、機械的に循環させない。3種類が指定された場合は総尺内に各景別を設ける。切替時は軸線、視線、動作、小物をつなぎ、コピー可能なプロンプトを分ける。編集の切替を連続した単一カットとして記さない。"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('wps-writing','published','{"id":"wps-writing","group":"office","labels":{"zh":"WPS 文字","en":"WPS Writer","ja":"WPS 文書"},"terms":["通知","报告","排版","writer","document","文書"],"guidance":{"zh":"根据已有事实直接交付完整文稿，再列标题层级、段落、页码、目录与排版步骤。保留人名、金额和日期；未确认内容标注待补。按实际WPS版本说明操作，不虚构菜单；不默认付费功能可用。","en":"Deliver the complete document from supplied facts, followed by heading, paragraph, page-number, contents and layout steps. Preserve names, amounts and dates; mark unknowns. Match instructions to the actual WPS version without inventing menus or assuming paid features.","ja":"提供事実から文書全文を作り、見出し、段落、ページ番号、目次、レイアウト手順を示す。名前、金額、日付を保持し、不明は要確認とする。WPSの実際の版に合わせ、有料機能やメニューを決めつけない。"},"examples":{"zh":"在WPS文字制作会议通知，含时间、地点、议程和参会要求。","en":"Create a meeting notice in WPS Writer with time, place, agenda and attendance requirements.","ja":"WPSで日時、場所、議題、参加条件を含む会議案内を作る。"},"questions":{"zh":"文稿给谁看、用于什么场合？有哪些必须保留的事实？","en":"Who will read this document, for what purpose, and which facts must stay?","ja":"読者、用途、必ず保持する事実は何ですか？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('wps-sheet','published','{"id":"wps-sheet","group":"office","labels":{"zh":"WPS 表格","en":"WPS Spreadsheets","ja":"WPS 表計算"},"terms":["公式","汇总","透视表","spreadsheet","formula","集計","数式"],"guidance":{"zh":"先确认表头、样例数据和统计口径。输出可粘贴公式、目标单元格、填充方向、引用规则和预期值；区分空值、零值、重复与日期文本。根据WPS版本选择公式或透视表，提供不支持新函数时的替代。没有文件或计算工具时不得声称已算出真实结果。","en":"Establish headers, sample data and aggregation rules. Supply paste-ready formulas, destination cells, fill direction, references and expected values. Distinguish blanks, zero, duplicates and text dates. Choose formulas/pivots for the WPS version and offer compatible alternatives. Do not claim actual calculations without data and execution.","ja":"列名、サンプル、集計条件を確認し、貼付可能な数式、入力セル、コピー方向、参照規則、期待値を示す。空白、ゼロ、重複、文字列日付を分ける。WPS版に応じて数式やピボットを選び、非対応関数の代替を出す。未実行の実測値を捏造しない。"},"examples":{"zh":"按月份和地区汇总销售额，列为日期、地区、金额，并制作柱状图。","en":"Summarize sales by month and region from Date, Region, Amount and plan a bar chart.","ja":"日付・地域・金額の列から月別地域別に集計し、棒グラフを作る。"},"questions":{"zh":"请提供表头和两行脱敏示例，以及希望得到的结果。","en":"Provide column headers, two anonymized rows and the desired result.","ja":"列名、匿名化した2行、求める結果を教えてください。"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('wps-slides','published','{"id":"wps-slides","group":"office","labels":{"zh":"WPS 演示","en":"WPS Presentation","ja":"WPS プレゼン"},"terms":["ppt","演示","汇报","presentation","slide","スライド"],"guidance":{"zh":"先确定听众、目的、页数与演讲时长。逐页输出标题、核心结论、可用正文、图表需求、版式和讲稿；每页一个重点。用提供的数据支持结论，未知数字标待补。说明WPS内的制作与导出步骤，不声称已生成文件。","en":"Confirm audience, purpose, slide count and talk duration. Deliver each slide’s title, takeaway, usable copy, visual brief, layout and speaker notes, one point per slide. Use supplied evidence and mark missing numbers. Give WPS assembly/export steps without claiming a file was produced.","ja":"聴衆、目的、枚数、発表時間を定め、各ページの題、要点、本文、図表、配置、話す内容を出す。1枚1論点とし、提供データで支え、不明な数値は補足待ちにする。WPSでの制作・出力手順を示す。"},"examples":{"zh":"制作8页季度工作汇报，演讲10分钟，包含成果、问题和下季度计划。","en":"Draft an eight-slide quarterly review for a ten-minute talk.","ja":"10分発表用の四半期報告を8枚で作る。"},"questions":{"zh":"听众是谁？需要几页、讲多久？有哪些真实成果资料？","en":"Who is the audience, how many slides/minutes, and what evidence is available?","ja":"聴衆、枚数・時間、実績資料は何ですか？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('wps-pdf','published','{"id":"wps-pdf","group":"office","labels":{"zh":"WPS PDF","en":"WPS PDF","ja":"WPS PDF"},"terms":["pdf","扫描","ocr","扫描件","スキャン"],"guidance":{"zh":"先区分文字PDF和扫描PDF，明确提取、转换、批注或排版检查目标。只依据已提供内容处理，OCR不确定字符注明页码待核对。保护表格、单位、脚注和页序；转换后列出核对项目。操作和会员限制以当前版本为准，不绕过文件权限，不声称看过未提供的PDF。","en":"Distinguish text and scanned PDFs and clarify extraction, conversion, annotation or layout review. Use only supplied content; flag uncertain OCR with page references. Preserve tables, units, notes and order; list post-conversion checks. Respect version/features and document permissions; never claim to inspect missing files.","ja":"テキストPDFかスキャンかを分け、抽出・変換・注釈・配置確認の目的を定める。提供内容だけを扱い、OCR不確実箇所をページ付きで示す。表、単位、注、順序を保ち、変換後の確認事項を出す。版と権限を尊重する。"},"examples":{"zh":"把扫描PDF中的表格整理为可粘贴到WPS表格的内容，标出不确定字符。","en":"Extract a scanned PDF table into paste-ready spreadsheet content with uncertain characters flagged.","ja":"スキャンPDFの表をWPSに貼れる形で整理し、不確実な文字を示す。"},"questions":{"zh":"PDF是扫描件还是可选中文字？希望提取、转换还是检查？","en":"Is the PDF scanned or selectable text, and what operation is needed?","ja":"スキャンか選択可能な文字か、どの処理が必要ですか？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('wps-cloud','published','{"id":"wps-cloud","group":"office","labels":{"zh":"云文档协作","en":"Cloud document collaboration","ja":"クラウド文書の共同編集"},"terms":["协作","共享","权限","collaboration","share","共同編集"],"guidance":{"zh":"按参与者角色定义只读、评论、编辑权限及版本流程。给出共享、评论处理、冲突解决和恢复步骤，菜单按实际产品核对。默认最小权限，敏感内容不建议公开链接；仅提供操作方案，不声称已修改共享权限。","en":"Map participants to view/comment/edit roles and a version process. Provide sharing, comment resolution, conflict and recovery steps with product-specific menus to verify. Prefer least privilege and avoid public links for sensitive material. Provide guidance, not claims of changed permissions.","ja":"参加者を閲覧・コメント・編集に分け、版管理を定める。共有、コメント解決、競合、復元手順を示し、実製品でメニューを確認する。権限は最小にし、機密文書を公開リンクにしない。変更済みと装わない。"},"examples":{"zh":"设计三人共同编辑报告的流程，经理审核，外部人员只能查看。","en":"Plan a three-person report workflow with manager approval and view-only external access.","ja":"3人の報告書共同編集、上司承認、外部は閲覧のみの流れを作る。"},"questions":{"zh":"谁需要查看、评论或编辑？使用WPS云文档还是金山文档？","en":"Who needs view/comment/edit access, and which WPS cloud product is used?","ja":"誰が閲覧・コメント・編集し、どのクラウド製品を使いますか？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('copy-product','published','{"id":"copy-product","group":"copy","labels":{"zh":"产品与品牌文案","en":"Product and brand copy","ja":"商品・ブランドコピー"},"terms":["产品","卖点","品牌","product","brand","商品"],"guidance":{"zh":"依据受众、使用场合和经过确认的卖点生成可直接使用的文案，结构为标题、利益点、证据、异议回应、行动引导。给长短两个版本及替代标题；不编造销量、评价、认证或效果保证，未知信息单独标注。避免同一套夸张措辞用于所有产品。","en":"Write usable copy for the audience/channel using verified benefits: headline, value, evidence, objections and call to action. Give short/long versions and alternative headlines. Never invent sales, testimonials, certifications or guarantees. Flag missing facts and tailor tone to the product.","ja":"対象と媒体に合わせ、確認済みの価値から見出し、利点、根拠、疑問への回答、行動案内を作る。長短版と別見出しを出す。売上、評価、認証、効果を捏造せず、商品に合わせる。"},"examples":{"zh":"为轻便通勤背包写官网介绍，只使用我提供的容量、重量和材质。","en":"Write website copy for a commuter backpack using only supplied capacity, weight and material.","ja":"提供した容量・重量・素材だけで通勤リュックの紹介を書く。"},"questions":{"zh":"目标读者、发布渠道和已确认的卖点是什么？","en":"Who is the audience, where will this appear, and which benefits are verified?","ja":"対象読者、掲載先、確認済みの特徴は何ですか？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('copy-social','published','{"id":"copy-social","group":"copy","labels":{"zh":"社交媒体与活动文案","en":"Social and campaign copy","ja":"SNS・キャンペーン文章"},"terms":["小红书","公众号","社交","活动","social","campaign","SNS"],"guidance":{"zh":"按平台、受众和目标输出标题、开头、完整正文、配图需求、行动引导及话题建议。区分活动时间、规则、价格等事实与创意；提供不同语气的两个版本。适配字数，不伪装真实用户经历，不自动发布。","en":"Deliver platform-specific headlines, hook, full copy, visual brief, CTA and topic ideas. Separate facts such as dates/rules/prices from creative choices. Provide two tone variants within length limits, without fabricated user experiences or automatic publication.","ja":"媒体と読者に合わせ、見出し、導入、全文、画像案、行動案内、話題を出す。日時・条件・価格と創作を分け、字数内で語調2案を作る。体験談の捏造や自動投稿はしない。"},"examples":{"zh":"为书店周末读书活动写公众号推文，保留真实时间和报名规则。","en":"Write a social post for a bookstore weekend reading event with verified dates and signup rules.","ja":"書店の週末読書会のSNS文を、実際の日時と参加条件で作る。"},"questions":{"zh":"发布在哪个平台？面向谁？活动或内容的真实资料是什么？","en":"Which platform/audience, and what verified event or content details are available?","ja":"媒体・読者と実際のイベント資料は何ですか？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('copy-script','published','{"id":"copy-script","group":"copy","labels":{"zh":"广告与短视频脚本","en":"Ads and short-video scripts","ja":"広告・短尺動画の台本"},"terms":["广告","口播","脚本","ad script","voiceover","台本"],"guidance":{"zh":"按总时长逐段写画面、口播、字幕、音效与行动引导；核对口播长度是否可在时限内表达。明确前三秒吸引点与中段证据，提供替代开头。产品功效与价格只能引用确认资料，不把夸张视觉当实测效果。","en":"Write timed visuals, voiceover, captions, sound and CTA. Check spoken length against duration, define the opening hook and supporting evidence, and offer alternate openings. Use confirmed product claims/prices; distinguish creative visuals from measured results.","ja":"尺ごとに映像、口播、字幕、音、行動案内を書き、読み時間を確認する。冒頭の引きと根拠、別の導入案を出す。効果と価格は確認資料のみを使い、演出を実測と混同しない。"},"examples":{"zh":"写30秒咖啡馆介绍短视频脚本，突出安静环境和手冲服务。","en":"Write a 30-second café introduction highlighting a quiet setting and pour-over coffee.","ja":"静かな環境とハンドドリップを紹介する30秒のカフェ台本を書く。"},"questions":{"zh":"视频多长？面向谁？必须出现哪些真实信息？","en":"How long is the video, who is it for, and what facts must appear?","ja":"尺、対象、必須の事実は何ですか？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('paper-outline','published','{"id":"paper-outline","group":"paper","labels":{"zh":"论文提纲与写作计划","en":"Paper outline and writing plan","ja":"論文構成と執筆計画"},"terms":["提纲","结构","选题","outline","structure","構成"],"guidance":{"zh":"结合论文类型、学科、研究问题和已有资料，给出章节层级、每节论点、证据需求、预计字数和写作顺序。区分综述、实证与毕业论文，不强套同一结构。列出资料缺口，不编造文献、数据或已完成实验。","en":"Use paper type, discipline, question and available evidence to deliver sections, claims, evidence needs, word budgets and writing order. Distinguish reviews, empirical papers and theses. List evidence gaps without inventing citations, data or completed experiments.","ja":"論文種別、分野、問い、資料から章節、論点、根拠、字数配分、執筆順を出す。レビュー・実証・学位論文を分け、資料不足を示す。文献や実験を捏造しない。"},"examples":{"zh":"根据我提供的研究问题和资料，制作6000字毕业论文提纲。","en":"Create an outline for a 6,000-word thesis from my question and evidence.","ja":"研究の問いと資料から6000語の論文構成を作る。"},"questions":{"zh":"论文类型、专业、主题、字数与已有资料是什么？","en":"What are the paper type, discipline, topic, word limit and available materials?","ja":"種類、分野、主題、字数、資料は何ですか？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('paper-draft','published','{"id":"paper-draft","group":"paper","labels":{"zh":"章节成稿与摘要","en":"Sections and abstract drafting","ja":"章本文と要旨の作成"},"terms":["正文","摘要","结论","章节","abstract","draft","要旨","本文"],"guidance":{"zh":"仅用提供或核实的资料完成指定章节或摘要，区分资料中的结果、解释和写作建议。每个事实性主张对应资料编号，缺证据使用待补标记；方法不得写成未实施的实验，结论不得超过结果支持。输出可用初稿、引用位置与待确认清单，不用虚构引用补齐篇幅。","en":"Draft the requested section or abstract only from supplied/verified material. Separate results, interpretation and writing suggestions; map factual claims to source IDs and mark evidence gaps. Never describe unperformed experiments or overstate conclusions. Deliver a usable draft, citation locations and confirmation list without fabricated references.","ja":"提供・確認済み資料だけで指定章や要旨を書く。結果、解釈、提案を分け、事実主張に資料IDを付け、不足を示す。未実施実験や根拠を超える結論を作らず、初稿、引用箇所、確認一覧を出す。"},"examples":{"zh":"根据提供的研究方法和结果表，撰写摘要，不增加实验或数值。","en":"Draft an abstract from supplied methods/results without adding experiments or numbers.","ja":"方法と結果表から、実験や数値を足さず要旨を書く。"},"questions":{"zh":"要写哪一部分？请提供可引用的原始资料和真实结果。","en":"Which section is needed? Supply citable materials and actual findings.","ja":"どの部分を書くか、引用可能な資料と実際の結果を教えてください。"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('paper-format','published','{"id":"paper-format","group":"paper","labels":{"zh":"引用、图表与论文排版","en":"Citations, figures and formatting","ja":"引用・図表・論文書式"},"terms":["参考文献","排版","图表","citation","formatting","引用","書式"],"guidance":{"zh":"按学校或期刊模板检查标题层级、编号、页码、图表题注、交叉引用和参考文献。保留源文献元数据，缺作者、年份或DOI时标待核实，不生成看似真实的条目。给WPS或指定编辑器的操作步骤，字体、间距、引用样式以提供规范为准。","en":"Check headings, numbering, pages, captions, cross-references and bibliography against the institution/journal template. Preserve metadata and flag missing authors/year/DOI rather than inventing entries. Give WPS or requested-editor steps, following supplied typography and citation requirements.","ja":"提出先規定に従い見出し、番号、ページ、図表説明、相互参照、文献を確認する。著者・年・DOI不足は要確認とし、文献を作らない。WPS等の操作と提供された書式規定を使う。"},"examples":{"zh":"按学校模板整理WPS毕业论文目录、图表编号和参考文献。","en":"Format a thesis in WPS using the school template, including contents, figures and references.","ja":"学校指定書式でWPS論文の目次・図表番号・参考文献を整える。"},"questions":{"zh":"请提供学校或期刊格式要求，以及编辑器和现有文献列表。","en":"Provide formatting requirements, editor and existing bibliography.","ja":"提出先の規定、編集ソフト、既存文献一覧をください。"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('paper-revise','published','{"id":"paper-revise","group":"paper","labels":{"zh":"润色、翻译与修改回复","en":"Revision, translation and responses","ja":"推敲・翻訳・修正回答"},"terms":["润色","翻译","审稿","修改","revise","translate","reviewer","推敲"],"guidance":{"zh":"保留原文事实、术语和研究边界，优化表达与衔接；翻译遵循术语表。按导师或审稿意见逐条给修改、位置和回应，无法完成的要求说明缺少什么，不声称完成未做的实验。提供修订稿与实质修改表，不改变统计含义。","en":"Preserve facts, terms and study limits while improving language and flow; follow a glossary for translation. Address each comment with revision, location and response. Explain missing work instead of claiming unperformed experiments. Provide revised text and a substantive change table without changing statistical meaning.","ja":"事実、用語、研究限界を保ち表現と接続を改善し、翻訳は用語集に従う。各指摘に修正・位置・回答を示し、未実施実験を完了扱いしない。修正文と変更表を出し、統計の意味を変えない。"},"examples":{"zh":"依据导师的三条意见修改讨论部分，保留真实数据与引用。","en":"Revise the discussion against three supervisor comments, preserving data and citations.","ja":"指導教員の3点の指摘に沿って考察を直し、データと引用を保つ。"},"questions":{"zh":"请提供原文、修改意见和不可改变的术语或结论。","en":"Provide the original, comments and terms/conclusions that must remain.","ja":"原文、指摘、変更できない用語・結論をください。"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('article-structure','published','{"id":"article-structure","group":"writing","labels":{"zh":"文章结构与成稿","en":"Article structure and draft","ja":"記事構成と執筆"},"terms":["文章","长文","article","essay","記事","文章"],"guidance":{"zh":"明确读者、主题、立场和篇幅。先建立中心论点及段落的证据关系，再交付标题、导语、完整正文与结尾；每节解决一个读者问题。将资料中的事实与作者观点分开，不编造采访、数字或引用。没有资料时提供标注待核实处的初稿，避免以空泛框架代替正文。","en":"Define audience, topic, position and length. Connect the central claim to evidence in each section, then deliver a headline, opening, complete body and ending; answer one reader question per section. Separate facts from opinions. Do not invent interviews, numbers or quotes. Mark evidence gaps in the draft rather than supplying only an abstract outline.","ja":"読者・主題・立場・分量を定め、中心主張と各段落の根拠を結ぶ。見出し、導入、本文、結びまで作り、各節は一つの疑問に答える。事実と意見を区別し、取材・数字・引用を捏造しない。不足資料は確認箇所として本文に明記する。"},"examples":{"zh":"根据我的三条观察写一篇800字远程工作文章，读者是新入职员工。","en":"Write an 800-word remote-work article for new employees using my three observations.","ja":"私の3つの観察から、新入社員向けにリモートワークの記事を書く。"},"questions":{"zh":"读者、核心观点、篇幅和可使用的资料是什么？","en":"Who will read it, what is the main point, and what length and sources are available?","ja":"読者、主張、分量、使える資料は何ですか？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('document-proposal','published','{"id":"document-proposal","group":"writing","labels":{"zh":"说明文档与提案","en":"Documentation and proposals","ja":"説明文書・提案"},"terms":["文档","提案","说明","proposal","documentation","specification","提案書","仕様書"],"guidance":{"zh":"围绕文档要促成的决定组织背景、问题、目标、方案、取舍、执行步骤和验收条件。先提炼已提供信息，只追问决定结构的缺项。交付可阅读的完整草稿，标明假设、负责人待定项和待确认日期。最后从未参与讨论的读者角度列出歧义与补充建议，不声称已由他人审阅。","en":"Organize context, problem, goals, proposal, tradeoffs, execution and acceptance around the decision the document supports. Use existing inputs before asking about structural gaps. Deliver a readable draft with assumptions, unassigned owners and unconfirmed dates marked. Check ambiguity from a new reader’s perspective without claiming another person reviewed it.","ja":"促したい意思決定に沿って背景・課題・目標・案・比較・実行・完成条件を構成する。既存資料を先に利用し重要な不足だけ確認。仮定、担当未定、未確認日付を明記した草稿を出し、初見の読者に不明な点を点検する。第三者レビュー済みとしない。"},"examples":{"zh":"为团队写知识库改版提案，目标是让新人更容易找到操作说明。","en":"Draft a team knowledge-base redesign proposal to help new hires find instructions.","ja":"新人が手順を探しやすくなる社内ナレッジ改修提案を書く。"},"questions":{"zh":"文档的读者、要做出的决定和已有约束是什么？","en":"Who is the reader, what decision is needed, and what constraints exist?","ja":"読者、必要な判断、既存制約を教えてください。"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('lesson-plan','published','{"id":"lesson-plan","group":"learning","labels":{"zh":"课程与教案","en":"Lessons and teaching plans","ja":"授業・指導案"},"terms":["教案","课程","lesson","teaching","授業","指導案"],"guidance":{"zh":"依据学习者基础和课时设定可观察的学习目标。输出导入、讲解、示例、练习、检查和收尾的分段流程，每段标明时间、教师动作和学生产出。为不同基础提供支架与拓展题，给出参考答案及误区说明，不用难度标签代替真实题目。","en":"Set observable objectives from learner background and lesson length. Provide timed opening, explanation, examples, practice, assessment and closure with teacher actions and learner outputs. Include support and extension activities, actual questions, answers and common misconceptions.","ja":"前提知識と授業時間から観察可能な目標を立てる。導入・説明・例・練習・確認・まとめに時間、教員の動き、学習者の成果を添える。補助と発展課題、具体的な問題、解答、誤解しやすい点を出す。"},"examples":{"zh":"设计一节40分钟的初中一次函数入门课，含练习和答案。","en":"Design a 40-minute introductory lesson on linear functions with exercises and answers.","ja":"一次関数入門の40分授業を、練習と解答付きで設計する。"},"questions":{"zh":"学生年龄、基础、学习目标和可用课时是多少？","en":"What are the learner age, background, goals and available time?","ja":"年齢、前提知識、目標、授業時間は？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('study-practice','published','{"id":"study-practice","group":"learning","labels":{"zh":"学习计划与练习","en":"Study plans and practice","ja":"学習計画・演習"},"terms":["复习","练习","学习计划","study plan","practice","revision","復習","演習"],"guidance":{"zh":"把目标拆成先修知识和可完成的小任务，按可用时间安排复习与间隔练习。用诊断题确定起点，给出题目、解析和检查标准；不会的题先给逐级提示，再给答案。安排复盘与调整规则，不承诺固定时间一定达成成绩。","en":"Break the goal into prerequisites and manageable tasks, with revision and spaced practice within the time budget. Provide diagnostic questions, worked explanations and checking criteria. Offer progressive hints before answers, plus review and adjustment rules without guaranteed score claims.","ja":"目標を前提知識と小課題に分け、時間内に復習と間隔練習を配置する。診断問題、解説、確認基準を出し、解けない場合は段階的ヒントから解答へ進める。振り返りと調整方法を示し点数を保証しない。"},"examples":{"zh":"我每天有30分钟，帮我安排两周Python基础复习并给出每日练习。","en":"Plan two weeks of Python revision with daily exercises in 30 minutes a day.","ja":"1日30分で2週間のPython基礎復習と毎日の演習を作る。"},"questions":{"zh":"你的基础、目标、每天时间和最困难的部分是什么？","en":"What is your baseline, goal, daily time and hardest topic?","ja":"現在の理解、目標、毎日の時間、苦手分野は？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('translation-context','published','{"id":"translation-context","group":"language","labels":{"zh":"语境翻译","en":"Context-aware translation","ja":"文脈に沿う翻訳"},"terms":["翻译","translation","translate","翻訳"],"guidance":{"zh":"先确认源语言、目标语言、用途和读者，依据语境保留专有名词、数字、单位及原意。输出自然译文与必要的术语表，歧义处列出可选译法和原因。代码、变量、链接与占位符原样保留；不擅自增删承诺、义务或事实。","en":"Identify source/target language, purpose and audience. Preserve names, numbers, units and meaning in context. Deliver natural target-language text and a useful glossary; explain alternatives for ambiguity. Keep code, variables, links and placeholders unchanged and never add promises, obligations or facts.","ja":"原言語・訳先・用途・読者を確認し、固有名詞、数値、単位、意味を保つ。自然な訳と必要な用語集を出し、曖昧な箇所は選択肢と理由を示す。コード、変数、リンク、プレースホルダーは変えず、約束や事実を加えない。"},"examples":{"zh":"把产品说明翻译成自然日文，保留型号、尺寸和保修期限。","en":"Translate product instructions into natural Japanese, preserving model, dimensions and warranty.","ja":"商品説明を自然な英語に訳し、型番・寸法・保証期間を保つ。"},"questions":{"zh":"请提供原文、目标语言、用途和必须保持一致的术语。","en":"Provide source text, target language, purpose and required terms.","ja":"原文、訳先、用途、統一する用語をください。"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('language-dialogue','published','{"id":"language-dialogue","group":"language","labels":{"zh":"语言会话练习","en":"Conversation practice","ja":"会話練習"},"terms":["口语","会话","dialogue","conversation","speaking","会話","発音"],"guidance":{"zh":"按语言水平与真实场景设计可轮流进行的对话。每轮只推进一个交流目标，允许用户先回答；纠错时保留原意，给自然表达与简短原因。总结可复用句型和下一轮练习，不冒称能听到未提供的录音或评定真实发音。","en":"Create turn-by-turn practice at the learner’s level in a real scenario. Pursue one communication goal per turn and let the learner respond. Correct without changing intended meaning, explain briefly, and summarize reusable phrases. Do not claim to hear missing audio or assess actual pronunciation from text alone.","ja":"レベルと実場面に合う交互の会話練習を作る。各ターン一つの目的で学習者の返答を待つ。意図を保って自然な表現と短い理由を示し、使える型と次の練習をまとめる。未提供音声を聞いたり文字だけで発音を判定したりしない。"},"examples":{"zh":"陪我练习英文酒店入住，我是初学者，每轮只问一个问题。","en":"Practice hotel check-in English with me as a beginner, one question per turn.","ja":"初級者向けにホテルのチェックイン英会話を一問ずつ練習する。"},"questions":{"zh":"练习语言、水平和希望模拟的场景是什么？","en":"Which language, level and situation should we practice?","ja":"言語、レベル、練習する場面は？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('daily-plan','published','{"id":"daily-plan","group":"life","labels":{"zh":"日常安排","en":"Daily planning","ja":"日々の予定"},"terms":["日程","待办","daily plan","schedule","予定","タスク"],"guidance":{"zh":"结合固定事项、可用时间、精力和优先级排出可执行日程，留出通勤与缓冲。区分必须完成和可延期事项，遇到时间冲突提出替代方案。提供清单和简单复盘，不假设已经建立提醒或读取用户日历。","en":"Build a feasible schedule from fixed commitments, time, energy and priorities, allowing travel and buffers. Separate essentials from deferrable tasks and propose alternatives for conflicts. Supply a checklist and review method without claiming calendar access or created reminders.","ja":"固定予定、時間、体力、優先度から移動と余裕を含む実行可能な予定を作る。必須と延期可能を分け、重複に代案を出す。チェックリストと振り返りを添え、カレンダー取得や通知登録済みとしない。"},"examples":{"zh":"工作日晚上有两小时，安排学习、整理房间和休息，留出缓冲。","en":"Plan study, tidying and rest within two evening hours, including buffers.","ja":"平日夜の2時間に学習・片付け・休憩を余裕付きで配置する。"},"questions":{"zh":"固定安排、可用时间和今天最重要的事项是什么？","en":"What commitments, time budget and top priority should be used?","ja":"固定予定、使える時間、最優先事項は？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('travel-outline','published','{"id":"travel-outline","group":"life","labels":{"zh":"出行规划","en":"Trip planning","ja":"旅行の計画"},"terms":["旅行","出行","trip","travel","旅行","旅程"],"guidance":{"zh":"先确认目的地、日期、出发点、同行需求和预算范围，按区域串联路线而不是堆砌景点。列出交通方式、每日节奏、雨天替代及待核实事项；开放时间、票价、签证等变动信息要求查询官方来源并注明日期，没有查询能力时明确未核实，不做虚假预订。","en":"Confirm destination, dates, starting point, travelers and budget. Group routes geographically with transport, realistic pacing and bad-weather options. Verify changing hours, prices and entry rules using dated official sources; if browsing is unavailable, mark them unverified. Never claim bookings were made.","ja":"行先、日程、出発地、同行者、予算を確認し、地域ごとに無理のない経路を組む。交通、日々の余裕、雨天代案を添える。営業時間・料金・入国条件は日付付き公式情報で確認し、検索不可なら未確認と明示。予約済みとしない。"},"examples":{"zh":"安排三天京都慢节奏旅行，少换酒店，交通和开放时间列为待核实。","en":"Outline three relaxed Kyoto days, minimizing hotel changes and flagging transport/hours to verify.","ja":"京都3日間をゆっくり回り、移動と営業時間の確認事項を示す。"},"questions":{"zh":"目的地、日期、预算和同行者的需求是什么？","en":"What destination, dates, budget and traveler needs apply?","ja":"行先、日程、予算、同行者の要望は？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('story-concept','published','{"id":"story-concept","group":"creative","labels":{"zh":"故事与人物","en":"Stories and characters","ja":"物語・登場人物"},"terms":["故事","人物","story","character","物語","登場人物"],"guidance":{"zh":"围绕人物目标、阻力、选择与代价设计原创故事，明确视角、时代和类型。给出人物动机、情节转折和具体场景草稿，让事件具有因果关系。区分世界观设定与已发生剧情，检查时间线和人物行为是否一致，避免用抽象主题代替情节。","en":"Build an original story around goals, obstacles, choices and consequences, with viewpoint, period and genre established. Deliver character motivations, turning points and a concrete scene draft linked causally. Separate world rules from events and check timeline and character consistency.","ja":"人物の目的、障害、選択、代償から独自の物語を作り、視点・時代・ジャンルを定める。動機、転換点、具体的な場面草稿を因果で結び、設定と既成事実を区別し時間軸と行動を点検する。"},"examples":{"zh":"设计一个修钟师寻找失踪师傅的短篇故事，给人物动机和开场场景。","en":"Develop a short story about a clockmaker searching for a missing mentor, with motivations and an opening scene.","ja":"行方不明の師匠を探す時計職人の短編を、動機と冒頭場面付きで作る。"},"questions":{"zh":"故事类型、读者、人物和必须保留的设定是什么？","en":"What genre, audience, characters and fixed world details apply?","ja":"ジャンル、読者、人物、保つ設定は？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('creative-brief','published','{"id":"creative-brief","group":"creative","labels":{"zh":"创意方向与设计简报","en":"Creative directions and briefs","ja":"創作方針・デザインブリーフ"},"terms":["创意","设计简报","creative brief","concept","ブリーフ","コンセプト"],"guidance":{"zh":"将目标、受众、使用场合和限制整理成设计简报，提出三个差异明确的创意方向。每个方向写视觉语言、文字语气、关键元素、交付物和适用理由，再比较成本与风险。选择方向后给可执行步骤，不以堆砌风格词代替实际设计要求。","en":"Translate goals, audience, placement and constraints into a brief with three distinct directions. Specify visual language, voice, key elements, deliverables and rationale, then compare effort and risks. Turn the chosen direction into executable steps rather than a list of style adjectives.","ja":"目的、対象、用途、制約から違いの明確な3方向を提案する。各方向に視覚言語、文章の声、要素、成果物、理由を添え、工数とリスクを比較。選んだ方向を実行手順にし、形容詞の羅列にしない。"},"examples":{"zh":"为社区读书会设计三个不同的活动视觉方向，预算低，适合印刷。","en":"Propose three low-budget, print-friendly visual directions for a community book club.","ja":"地域読書会に低予算で印刷しやすい3つの視覚方針を提案する。"},"questions":{"zh":"目标受众、发布位置、品牌资料和交付规格是什么？","en":"Who is it for, where will it appear, and what brand assets and output specifications exist?","ja":"対象、掲載場所、ブランド資料、納品仕様は？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('business-compare','published','{"id":"business-compare","group":"business","labels":{"zh":"竞品与商业分析","en":"Competitive and business analysis","ja":"競合・事業分析"},"terms":["竞品","商业分析","competitor","business analysis","競合","事業分析"],"guidance":{"zh":"先定义比较对象、用户需求、时间范围和决策问题，按同一维度整理功能、价格、渠道和差异。给证据表、来源日期、假设和资料缺口；无依据的市场份额或营收不填假数。区分观察与推断，交付可验证的建议和下一步调研问题，不提供收益保证。","en":"Define alternatives, customer needs, period and decision. Compare features, prices, channels and differences consistently. Provide evidence, source dates, assumptions and gaps; never invent revenue or market share. Separate observation from inference and offer testable recommendations and research questions, not return guarantees.","ja":"対象、顧客ニーズ、期間、判断事項を定め、機能・価格・経路・差異を同じ軸で比較する。根拠、日付、仮定、不足を示し、売上やシェアを捏造しない。観察と推論を分け、検証可能な提案と調査事項を出す。"},"examples":{"zh":"用我提供的三家产品资料做竞品对比，未知价格留空并标注来源。","en":"Compare three products using supplied materials, leaving unknown prices unfilled and citing sources.","ja":"提供した3製品の資料で比較し、不明価格は空欄にして出典を示す。"},"questions":{"zh":"比较哪些对象、为谁决策、使用哪些已确认资料？","en":"Which alternatives, decision-maker and verified sources should be used?","ja":"対象、判断する人、確認済み資料は？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('content-roadmap','published','{"id":"content-roadmap","group":"business","labels":{"zh":"内容策略与选题","en":"Content strategy and topics","ja":"コンテンツ戦略・企画"},"terms":["内容策略","选题","content strategy","editorial calendar","コンテンツ戦略","編集計画"],"guidance":{"zh":"从业务目标、客户问题、已有内容和制作能力建立主题支柱。按搜索意图或分享价值给选题、目标读者、内容形式、证据需求、优先级和复用方法，安排可执行周期。设定验证指标而不承诺流量，避免同义选题重复；发布和外部推广留给用户确认。","en":"Build content pillars from business goals, customer questions, existing assets and capacity. For each topic, specify search intent or sharing value, audience, format, evidence needs, priority and reuse. Plan a feasible cadence with validation metrics rather than traffic guarantees; avoid duplicate topics and leave publishing to user approval.","ja":"事業目標、顧客の疑問、既存資産、制作力から柱を作る。企画ごとに検索意図や共有価値、読者、形式、根拠、優先度、再利用を示す。実行可能な周期と検証指標を定め、流入を保証せず公開は利用者の判断に委ねる。"},"examples":{"zh":"为小型摄影工作室安排四周内容选题，每周两篇，复用现有案例。","en":"Plan four weeks of content for a small photo studio, two pieces weekly using existing cases.","ja":"小さな写真スタジオに既存事例を使う週2本、4週間の企画を作る。"},"questions":{"zh":"业务目标、客户问题、已有内容和每周制作能力是什么？","en":"What business goals, customer questions, existing content and weekly capacity apply?","ja":"事業目標、顧客の疑問、既存内容、週の制作能力は？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('decision-options','published','{"id":"decision-options","group":"thinking","labels":{"zh":"决策比较","en":"Decision comparison","ja":"意思決定の比較"},"terms":["决策","利弊","decision","tradeoff","判断","比較"],"guidance":{"zh":"明确要决定的问题、可行选项和不可妥协的条件，先定义比较标准再评估。给出证据、权重可调整的比较表、机会成本和不确定性；信息不足时展示条件性结论及最值得补充的信息，不用虚构精确分数制造确定感。","en":"Define the decision, viable options and non-negotiables before selecting criteria. Provide evidence, adjustable weights, opportunity costs and uncertainty. With incomplete inputs, give conditional conclusions and the most valuable missing information rather than fabricated precise scores.","ja":"判断事項、選択肢、譲れない条件を定めてから比較軸を作る。根拠、調整可能な重み、機会費用、不確実性を示す。不足時は条件付き結論と価値の高い追加情報を出し、精密な点数を捏造しない。"},"examples":{"zh":"比较自学和报名课程两种学习方式，以时间、预算和反馈速度为标准。","en":"Compare self-study and a course by time, budget and feedback speed.","ja":"独学と講座を時間・予算・フィードバック速度で比較する。"},"questions":{"zh":"有哪些选项、硬性约束和最重要的评价标准？","en":"What options, hard constraints and key criteria should be compared?","ja":"選択肢、必須条件、主要な評価軸は？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('argument-check','published','{"id":"argument-check","group":"thinking","labels":{"zh":"论证与表达检查","en":"Argument and expression review","ja":"論証・表現の点検"},"terms":["论证","逻辑","argument","logic","論証","論理"],"guidance":{"zh":"提取主张、前提、证据和结论，检查概念是否一致、证据是否支持结论以及是否遗漏反例。用原文定位问题，区分事实错误、推理跳跃与措辞不清；给出保持原意的修订版和需要验证的问题，不把不同意见直接判为逻辑错误。","en":"Extract claims, premises, evidence and conclusions. Check consistent definitions, evidential support and counterexamples. Locate issues in the source, distinguish factual errors, inference gaps and unclear wording, and provide a meaning-preserving revision with verification questions. Disagreement alone is not a fallacy.","ja":"主張・前提・根拠・結論を抽出し、定義の一貫性、支持関係、反例を点検する。原文箇所を示し、事実誤り・推論の飛躍・曖昧さを区別。意図を保つ修正文と検証事項を出し、異論を誤謬扱いしない。"},"examples":{"zh":"检查我这段关于远程办公的论证，指出证据不足处并保留原意改写。","en":"Review my remote-work argument for evidence gaps and revise without changing the intended claim.","ja":"リモートワークの論証で根拠不足を指摘し、主張を保って直す。"},"questions":{"zh":"请提供原文、表达目的和必须保留的观点。","en":"Provide the text, communication goal and points that must remain.","ja":"原文、表現の目的、残す主張をください。"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('frontend-ui','published','{"id":"frontend-ui","group":"programming","labels":{"zh":"网页与界面设计","en":"Frontend and UI design","ja":"フロントエンド・UI設計"},"terms":["网页","界面","UI","frontend","website","landing page","web page","画面","ウェブ"],"guidance":{"zh":"根据真实用户任务、内容、品牌与技术栈设计界面，先明确颜色、字体、间距和布局原则，再给可运行代码。确保搜索、表单、加载、空态、错误与键盘操作完整；考虑手机、长文本、三语长度及减少动效偏好。用少量有目的的视觉元素建立风格，不以装饰替代内容，附实际完成的验证与剩余限制。","en":"Design around real user tasks, content, brand and stack. Define color, type, spacing and layout before delivering runnable code. Cover search, forms, loading, empty/error states and keyboard use; test mobile widths, long content, language expansion and reduced motion. Use a few purposeful visual choices, with actual verification and remaining limits reported.","ja":"実利用者のタスク、内容、ブランド、技術構成に基づき色・書体・余白・配置を定め、動くコードを出す。検索、入力、読込、空・失敗状態、キーボードを整え、スマホ、長文、多言語、動き低減を確認。装飾で内容を隠さず実施済み検証と限界を示す。"},"examples":{"zh":"为三语提示词网站设计简洁有艺术感的界面，保留搜索、收藏和Skill下载。","en":"Design a restrained, artistic UI for a trilingual prompt library with search, favorites and Skill downloads.","ja":"3言語プロンプト集を、検索・お気に入り・Skill保存を保って簡潔で個性的にする。"},"questions":{"zh":"目标用户、主要操作、品牌参考和现有技术栈是什么？","en":"Who are the users, main actions, brand references and existing stack?","ja":"利用者、主操作、ブランド参考、既存技術は？"},"status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('backend-api','published','{"id":"backend-api","group":"backend","labels":{"zh":"API 接口实现","en":"API implementation","ja":"API実装"},"terms":["API","接口","endpoint","エンドポイント"],"guidance":{"zh":"先列出路径、方法、鉴权、请求与响应字段、状态码及错误格式，再按用户技术栈交付路由、校验和服务层代码。明确分页、排序稳定性、重复请求和资源不存在时的行为，给出正常与失败请求样例及测试命令。没有仓库访问时标明文件路径和集成步骤，不虚构运行结果。","en":"Specify routes, methods, authentication, request/response fields, status codes and error shapes before implementing handlers, validation and service logic in the chosen stack. Define stable pagination, duplicate requests and missing resources. Include success/failure examples and test commands; without repository access, provide file paths and integration steps without claiming execution.","ja":"経路、メソッド、認証、入出力項目、状態コード、エラー形式を定め、指定構成でハンドラー・検証・サービスを実装する。安定したページ分割、重複要求、対象なしを定義。成功・失敗例とテスト手順を示し、未実行の結果を作らない。"},"examples":{"zh":"针对支持分页和权限的团队任务API，完成“API 接口实现”，给出可以直接使用的内容。","en":"Create api implementation for a team task API with pagination and permissions. Provide a usable deliverable.","ja":"ページ分割と権限を持つチームタスクAPIについて「API実装」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：语言版本、接口需求、数据结构及权限规则。已写在需求中的信息不必重复。","en":"Provide language/version, API requirements, data model and access rules. Do not repeat details already in the brief.","ja":"言語・版、API要件、データ構造、権限を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-95","aishort-191","pc-search"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('backend-schema','published','{"id":"backend-schema","group":"backend","labels":{"zh":"数据库建模与迁移","en":"Schema and migrations","ja":"DB設計・移行"},"terms":["建表","迁移","schema","migration","スキーマ","移行"],"guidance":{"zh":"从实体与查询需求推导主外键、唯一约束、空值和索引，提供字段字典、关系说明、目标数据库方言的建表和迁移脚本。分开结构迁移与数据回填，说明备份、回滚局限和上线顺序。用样例数据验证约束与核心查询，禁止把删除表作为默认迁移方法。","en":"Derive keys, uniqueness, nullability and indexes from entities and queries. Deliver a field dictionary, relationships and migrations in the target database dialect. Separate schema changes from backfills; explain backups, rollback limitations and rollout order. Demonstrate constraints and core queries with sample data; never default to destructive table replacement.","ja":"実体と検索要件から主外部キー、一意性、NULL、索引を設計し、項目辞書と対象DB方言の移行SQLを出す。構造変更と埋め戻しを分離し、バックアップ、ロールバックの限界、適用順を説明。例データで制約と検索を確認し、既定で表を削除しない。"},"examples":{"zh":"针对支持分页和权限的团队任务API，完成“数据库建模与迁移”，给出可以直接使用的内容。","en":"Create schema and migrations for a team task API with pagination and permissions. Provide a usable deliverable.","ja":"ページ分割と権限を持つチームタスクAPIについて「DB設計・移行」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：语言版本、接口需求、数据结构及权限规则。已写在需求中的信息不必重复。","en":"Provide language/version, API requirements, data model and access rules. Do not repeat details already in the brief.","ja":"言語・版、API要件、データ構造、権限を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-95","aishort-191","pc-search"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('backend-import','published','{"id":"backend-import","group":"backend","labels":{"zh":"批量导入与幂等处理","en":"Batch imports and idempotency","ja":"一括取込・冪等性"},"terms":["导入","幂等","import","idempotency","取込","冪等"],"guidance":{"zh":"明确输入格式、字段映射、唯一键和冲突策略，给出逐行校验、事务边界、分批处理与失败重试实现。输出成功、跳过、失败数量和带行号的错误报告；区分重试与重复创建。包含缺列、重复键、空文件、中断恢复的测试，不默认覆盖已有数据。","en":"Define input format, field mapping, unique keys and conflict policy. Implement row validation, transaction boundaries, batching and retries. Report accepted, skipped and failed counts with row-level errors. Distinguish safe retries from duplicate creation; test missing columns, duplicate keys, empty files and recovery without silently overwriting existing records.","ja":"形式、項目対応、一意キー、競合方針を定め、行検証、トランザクション、分割処理、再試行を実装する。成功・スキップ・失敗件数と行番号付きエラーを出し、再試行と二重登録を区別。欠列、重複、空ファイル、中断復旧を確認し、既存データを無断上書きしない。"},"examples":{"zh":"针对支持分页和权限的团队任务API，完成“批量导入与幂等处理”，给出可以直接使用的内容。","en":"Create batch imports and idempotency for a team task API with pagination and permissions. Provide a usable deliverable.","ja":"ページ分割と権限を持つチームタスクAPIについて「一括取込・冪等性」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：语言版本、接口需求、数据结构及权限规则。已写在需求中的信息不必重复。","en":"Provide language/version, API requirements, data model and access rules. Do not repeat details already in the brief.","ja":"言語・版、API要件、データ構造、権限を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-95","aishort-191","pc-search"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('testing-unit','published','{"id":"testing-unit","group":"testing","labels":{"zh":"单元测试用例","en":"Unit test cases","ja":"単体テスト"},"terms":["单元","unit test","単体"],"guidance":{"zh":"根据函数契约列出输入分区、边界、异常及状态变化，使用项目已有框架编写测试。只替换外部依赖，避免模拟被测逻辑；每项断言对应可观察行为。给出最小夹具、运行方式及仍缺覆盖的分支，不通过复制实现计算期望值。","en":"Derive input partitions, boundaries, exceptions and state changes from the function contract. Write tests in the existing framework, mocking external dependencies rather than the behavior under test. Use observable assertions, minimal fixtures and explicit expected values; include execution instructions and uncovered branches without duplicating implementation logic.","ja":"関数契約から入力区分、境界、例外、状態変化を整理し既存フレームワークでテストする。外部依存のみ置換し、観察可能な動作を検証。最小データ、明示的な期待値、実行手順、未確認分岐を示し、実装の複製で期待値を計算しない。"},"examples":{"zh":"针对带登录与购物车的示例网站，完成“单元测试用例”，给出可以直接使用的内容。","en":"Create unit test cases for a sample website with login and a cart. Provide a usable deliverable.","ja":"ログインとカートのあるサンプルサイトについて「単体テスト」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：被测代码、预期行为、测试框架和已知问题。已写在需求中的信息不必重复。","en":"Provide code, expected behavior, test framework and known failures. Do not repeat details already in the brief.","ja":"対象コード、期待動作、テスト構成、既知の問題を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-97"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('testing-journey','published','{"id":"testing-journey","group":"testing","labels":{"zh":"端到端用户流程测试","en":"End-to-end user journeys","ja":"E2Eユーザーフロー"},"terms":["端到端","E2E","journey","一連の操作"],"guidance":{"zh":"将关键用户流程拆成前置状态、操作、可见结果和清理步骤，使用语义定位器与状态等待。覆盖成功、失败、刷新恢复和权限隔离；测试数据使用独立账号或本地夹具。交付可执行脚本与失败证据采集方法，不使用固定长等待掩盖不稳定性。","en":"Turn critical journeys into setup, actions, visible assertions and cleanup. Use semantic locators and state-based waits. Cover success, failure, reload recovery and access isolation with isolated test accounts or local fixtures. Deliver runnable scripts and failure evidence capture; avoid long fixed sleeps that mask flakiness.","ja":"主要フローを前提状態、操作、可視結果、後片付けに分ける。意味的な要素指定と状態待機を使い、成功・失敗・再読込・権限分離を独立テストデータで確認。実行可能スクリプトと失敗証拠の収集方法を出し、固定長待機で不安定さを隠さない。"},"examples":{"zh":"针对带登录与购物车的示例网站，完成“端到端用户流程测试”，给出可以直接使用的内容。","en":"Create end-to-end user journeys for a sample website with login and a cart. Provide a usable deliverable.","ja":"ログインとカートのあるサンプルサイトについて「E2Eユーザーフロー」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：被测代码、预期行为、测试框架和已知问题。已写在需求中的信息不必重复。","en":"Provide code, expected behavior, test framework and known failures. Do not repeat details already in the brief.","ja":"対象コード、期待動作、テスト構成、既知の問題を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-97"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('testing-report','published','{"id":"testing-report","group":"testing","labels":{"zh":"缺陷报告与复现","en":"Bug reports and reproduction","ja":"不具合報告・再現"},"terms":["缺陷报告","复现报告","bug report","再現手順"],"guidance":{"zh":"把零散报错整理为标题、环境、最小复现步骤、实际与预期结果、频率及影响范围。区分观察证据与根因猜测，为每个猜测安排验证步骤。给出最小复现代码或待补资料清单，以及修复后的回归检查，不将未复现的问题标记为已解决。","en":"Convert scattered errors into a title, environment, minimal steps, expected/actual behavior, frequency and impact. Separate observed evidence from root-cause hypotheses and give a check for each hypothesis. Supply a minimal reproduction or missing-input list and post-fix regression checks; never label an unreproduced issue resolved.","ja":"断片的なエラーを題名、環境、最小手順、期待・実結果、頻度、影響に整理。観測事実と原因仮説を分け、仮説ごとの検証を示す。最小再現コードまたは不足資料、修正後の回帰項目を出し、未再現を解決済みにしない。"},"examples":{"zh":"针对带登录与购物车的示例网站，完成“缺陷报告与复现”，给出可以直接使用的内容。","en":"Create bug reports and reproduction for a sample website with login and a cart. Provide a usable deliverable.","ja":"ログインとカートのあるサンプルサイトについて「不具合報告・再現」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：被测代码、预期行为、测试框架和已知问题。已写在需求中的信息不必重复。","en":"Provide code, expected behavior, test framework and known failures. Do not repeat details already in the brief.","ja":"対象コード、期待動作、テスト構成、既知の問題を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-97"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('devops-pipeline','published','{"id":"devops-pipeline","group":"devops","labels":{"zh":"CI/CD 流水线","en":"CI/CD pipeline","ja":"CI/CDパイプライン"},"terms":["CI/CD","流水线","pipeline","パイプライン"],"guidance":{"zh":"按触发条件、依赖安装、静态检查、测试、构建、制品和部署阶段交付配置。区分拉取请求验证与正式发布，给出最小权限、并发取消、缓存键及失败通知设计；密钥只引用变量名。说明回滚与环境审批点，不添加用户未指定的付费服务。","en":"Deliver pipeline configuration for triggers, installation, checks, tests, build, artifacts and deployment. Separate pull-request validation from releases. Define least privilege, cancellation, cache keys and failure notifications, referencing secrets only by variable name. Explain rollback and environment gates without adding unrequested paid services.","ja":"起動条件、依存導入、検査、テスト、ビルド、成果物、配備の設定を出す。PR検証と公開を分け、最小権限、並行取消、キャッシュキー、失敗通知を設計。秘密は変数名のみ参照し、復旧と環境承認箇所を説明。未指定の有料サービスを追加しない。"},"examples":{"zh":"针对需要测试环境和生产环境的Node应用，完成“CI/CD 流水线”，给出可以直接使用的内容。","en":"Create ci/cd pipeline for a Node app with staging and production. Provide a usable deliverable.","ja":"検証・本番環境を持つNodeアプリについて「CI/CDパイプライン」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：运行环境、部署平台、构建命令、服务依赖和恢复目标。已写在需求中的信息不必重复。","en":"Provide runtime, hosting platform, build commands, dependencies and recovery goals. Do not repeat details already in the brief.","ja":"環境、配備先、ビルド手順、依存、復旧目標を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-95","aishort-201","pc-devops"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('devops-container','published','{"id":"devops-container","group":"devops","labels":{"zh":"容器化与本地运行","en":"Containerization and local setup","ja":"コンテナ化・ローカル起動"},"terms":["Docker","容器","container","コンテナ"],"guidance":{"zh":"根据实际项目提供Dockerfile、忽略规则和必要的Compose配置，说明构建阶段、启动用户、端口、健康检查、持久化与环境变量。交付构建启动命令和日志排错步骤，区分开发与生产依赖。镜像版本需要核对，禁止把密钥复制进镜像或默认挂载宿主根目录。","en":"Provide a project-specific Dockerfile, ignore rules and necessary Compose configuration. Explain build stages, runtime user, ports, health checks, persistence and environment variables. Include build/start commands and log-based debugging, separating development and production dependencies. Verify image versions; never bake secrets into images or mount the host root by default.","ja":"対象プロジェクト用Dockerfile、除外規則、必要なComposeを作る。ビルド段階、実行ユーザー、ポート、健全性、永続化、変数を説明し、起動・ログ調査手順を添える。開発と本番依存を区別。版を確認し、秘密の埋込やホストルートの既定マウントをしない。"},"examples":{"zh":"针对需要测试环境和生产环境的Node应用，完成“容器化与本地运行”，给出可以直接使用的内容。","en":"Create containerization and local setup for a Node app with staging and production. Provide a usable deliverable.","ja":"検証・本番環境を持つNodeアプリについて「コンテナ化・ローカル起動」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：运行环境、部署平台、构建命令、服务依赖和恢复目标。已写在需求中的信息不必重复。","en":"Provide runtime, hosting platform, build commands, dependencies and recovery goals. Do not repeat details already in the brief.","ja":"環境、配備先、ビルド手順、依存、復旧目標を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-95","aishort-201","pc-devops"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('devops-incident','published','{"id":"devops-incident","group":"devops","labels":{"zh":"故障排查运行手册","en":"Incident runbook","ja":"障害対応手順書"},"terms":["故障手册","runbook","incident","障害対応"],"guidance":{"zh":"围绕具体告警写触发条件、影响确认、只读诊断、分支判断、缓解、恢复验证和升级联系人。命令标明目标环境、预期输出及风险，先保存证据再提出变更；将重启、删除和回滚操作单独列出。最后给事件时间线与复盘模板，不假设故障已恢复。","en":"Write a runbook for a specific alert: trigger, impact, read-only diagnosis, decision branches, mitigation, recovery checks and escalation. Annotate commands with target environment, expected signals and risk. Preserve evidence before changes; separate restarts, deletions and rollbacks. Include an incident timeline and review template without claiming recovery.","ja":"具体的な警報に対し発火条件、影響、読取診断、分岐、緩和、復旧確認、連絡先を記述。コマンドに対象環境、期待兆候、リスクを添え、変更前に証拠保存。再起動・削除・巻戻しを分離し、時系列と振り返り様式を出す。復旧済みと決めつけない。"},"examples":{"zh":"针对需要测试环境和生产环境的Node应用，完成“故障排查运行手册”，给出可以直接使用的内容。","en":"Create incident runbook for a Node app with staging and production. Provide a usable deliverable.","ja":"検証・本番環境を持つNodeアプリについて「障害対応手順書」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：运行环境、部署平台、构建命令、服务依赖和恢复目标。已写在需求中的信息不必重复。","en":"Provide runtime, hosting platform, build commands, dependencies and recovery goals. Do not repeat details already in the brief.","ja":"環境、配備先、ビルド手順、依存、復旧目標を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-95","aishort-201","pc-devops"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('analytics-clean','published','{"id":"analytics-clean","group":"analytics","labels":{"zh":"数据清洗规则","en":"Data cleaning rules","ja":"データ整形規則"},"terms":["清洗","缺失值","cleaning","欠損","整形"],"guidance":{"zh":"先检查字段类型、单位、编码、重复、缺失与异常值，给出问题清单和逐列处理规则。保留原始数据，提供可复现脚本或表格步骤、修改日志与前后行数核对。对无法推断的值保留未知，不为图表好看而删除异常点。","en":"Audit types, units, encoding, duplicates, missing values and outliers. Deliver a problem inventory and column-specific rules. Preserve raw data and provide reproducible code or spreadsheet steps, a change log and row-count reconciliation. Keep unknowable values unknown; do not delete inconvenient outliers just to improve a chart.","ja":"型、単位、文字コード、重複、欠損、外れ値を調べ、問題一覧と列別規則を出す。原本を保ち、再現可能コードまたは表操作、変更記録、前後件数照合を添える。不明値は不明のままにし、見栄えのために外れ値を消さない。"},"examples":{"zh":"针对含日期、渠道、金额和缺失值的销售表，完成“数据清洗规则”，给出可以直接使用的内容。","en":"Create data cleaning rules for sales data with dates, channels, amounts and missing values. Provide a usable deliverable.","ja":"日付・チャネル・金額・欠損を含む売上表について「データ整形規則」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：样例数据、字段含义、分析问题和使用软件。已写在需求中的信息不必重复。","en":"Provide sample data, field definitions, analysis questions and software. Do not repeat details already in the brief.","ja":"例データ、項目定義、分析課題、利用ソフトを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-85","aishort-134","pc-data"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('analytics-explore','published','{"id":"analytics-explore","group":"analytics","labels":{"zh":"探索分析与结论","en":"Exploratory analysis","ja":"探索的分析"},"terms":["探索分析","EDA","exploratory","探索的"],"guidance":{"zh":"将业务问题映射到指标口径、分组、时间范围和计算方法，先做描述统计再讨论差异。输出分析表、必要图形、可复现计算和有依据的结论，说明样本偏差、缺失和相关不等于因果。没有数据时提供查询与分析方案，不生成看似真实的结果数字。","en":"Map questions to metric definitions, groups, date ranges and calculations. Start with descriptive statistics before interpreting differences. Deliver tables, necessary charts, reproducible calculations and supported findings. Explain sampling bias, missingness and correlation versus causation. Without data, give queries and an analysis plan rather than fabricated results.","ja":"課題を指標定義、集計区分、期間、計算に対応させ、記述統計の後に差を解釈する。表、必要な図、再現計算、根拠ある結論を出す。標本偏り、欠損、相関と因果の違いを説明。データなしなら計画やクエリを示し数値結果を作らない。"},"examples":{"zh":"针对含日期、渠道、金额和缺失值的销售表，完成“探索分析与结论”，给出可以直接使用的内容。","en":"Create exploratory analysis for sales data with dates, channels, amounts and missing values. Provide a usable deliverable.","ja":"日付・チャネル・金額・欠損を含む売上表について「探索的分析」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：样例数据、字段含义、分析问题和使用软件。已写在需求中的信息不必重复。","en":"Provide sample data, field definitions, analysis questions and software. Do not repeat details already in the brief.","ja":"例データ、項目定義、分析課題、利用ソフトを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-85","aishort-134","pc-data"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('analytics-dashboard','published','{"id":"analytics-dashboard","group":"analytics","labels":{"zh":"仪表盘与图表选型","en":"Dashboard and chart design","ja":"ダッシュボード設計"},"terms":["仪表盘","dashboard","图表选型","ダッシュボード"],"guidance":{"zh":"根据使用者要做的决策选择核心指标和图表类型，说明坐标、单位、时间粒度、筛选和刷新频率。给出布局、字段到图形的映射、空数据与错误状态，避免误导坐标和装饰性3D。交付目标工具可实现的配置或代码，并列出数据校验方法。","en":"Choose metrics and chart types around the user’s decisions. Define axes, units, time grain, filters and refresh frequency. Supply layout, field-to-chart mapping, empty/error states and tool-specific configuration or code. Avoid misleading scales and decorative 3D; include checks that reconcile displayed values to source data.","ja":"利用者の判断から指標と図を選び、軸、単位、時間粒度、絞込、更新頻度を定義。配置、項目対応、空・失敗状態、対象ツールの設定かコードを出す。誤解を招く軸や装飾3Dを避け、表示値と原データの照合方法を添える。"},"examples":{"zh":"针对含日期、渠道、金额和缺失值的销售表，完成“仪表盘与图表选型”，给出可以直接使用的内容。","en":"Create dashboard and chart design for sales data with dates, channels, amounts and missing values. Provide a usable deliverable.","ja":"日付・チャネル・金額・欠損を含む売上表について「ダッシュボード設計」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：样例数据、字段含义、分析问题和使用软件。已写在需求中的信息不必重复。","en":"Provide sample data, field definitions, analysis questions and software. Do not repeat details already in the brief.","ja":"例データ、項目定義、分析課題、利用ソフトを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-85","aishort-134","pc-data"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('product-prd','published','{"id":"product-prd","group":"product","labels":{"zh":"产品需求文档","en":"Product requirements document","ja":"製品要件書"},"terms":["PRD","产品需求","requirements document","要件書"],"guidance":{"zh":"从真实用户问题组织背景、目标、非目标、用户流程、功能规则、数据需求和验收标准。逐项说明成功、空态、错误、权限和边界行为，标出假设及待决策事项。输出可交给设计与开发的完整PRD；指标包含定义和采集方式，不虚构用户调研结论。","en":"Build a complete PRD around evidenced user problems: context, goals, non-goals, journeys, rules, data and acceptance. Specify success, empty, error, permission and boundary behavior. Mark assumptions and open decisions. Define metrics and collection methods so designers and engineers can use the document; never invent research findings.","ja":"根拠ある利用課題から背景、目標、非目標、導線、規則、データ、受入条件をまとめる。成功・空・失敗・権限・境界を具体化し、仮定と未決事項を明示。設計開発へ渡せる要件書と指標定義・収集方法を出し、調査結果を捏造しない。"},"examples":{"zh":"针对帮助新用户完成首次配置的功能，完成“产品需求文档”，给出可以直接使用的内容。","en":"Create product requirements document for a feature helping new users complete onboarding. Provide a usable deliverable.","ja":"新規利用者の初期設定を助ける機能について「製品要件書」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：目标用户、问题证据、功能边界、约束和成功指标。已写在需求中的信息不必重复。","en":"Provide target users, problem evidence, scope, constraints and success measures. Do not repeat details already in the brief.","ja":"対象者、課題の根拠、範囲、制約、成功指標を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-139","aishort-92"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('product-stories','published','{"id":"product-stories","group":"product","labels":{"zh":"用户故事与验收","en":"User stories and acceptance","ja":"ユーザーストーリー・受入条件"},"terms":["用户故事","user story","acceptance","受入条件"],"guidance":{"zh":"把需求拆成能独立验证的小故事，每项说明角色、目标、价值、前提及Given/When/Then验收例。包含失败和权限场景，标记依赖与范围外内容。按用户价值与实施约束解释优先级，不用故事点冒充确定工期。","en":"Split requirements into independently verifiable stories with actor, goal, value, preconditions and Given/When/Then examples. Include failure and permission cases, dependencies and exclusions. Explain priority through user value and implementation constraints; do not present story points as guaranteed calendar estimates.","ja":"要件を独立検証できる話に分け、役割、目的、価値、前提、Given/When/Then例を示す。失敗と権限、依存、対象外を含める。価値と制約で優先度を説明し、ポイントを確定工期として扱わない。"},"examples":{"zh":"针对帮助新用户完成首次配置的功能，完成“用户故事与验收”，给出可以直接使用的内容。","en":"Create user stories and acceptance for a feature helping new users complete onboarding. Provide a usable deliverable.","ja":"新規利用者の初期設定を助ける機能について「ユーザーストーリー・受入条件」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：目标用户、问题证据、功能边界、约束和成功指标。已写在需求中的信息不必重复。","en":"Provide target users, problem evidence, scope, constraints and success measures. Do not repeat details already in the brief.","ja":"対象者、課題の根拠、範囲、制約、成功指標を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-139","aishort-92"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('product-usability','published','{"id":"product-usability","group":"product","labels":{"zh":"可用性测试计划","en":"Usability study plan","ja":"ユーザビリティ調査計画"},"terms":["可用性","usability","用户访谈","利用者調査"],"guidance":{"zh":"围绕需要验证的假设设计参与者条件、任务脚本、主持提示、观察表和成功标准。问题保持中性，任务描述不给操作答案，区分行为证据与主观偏好。输出记录模板、问题严重度规则与改进排序，不编造受访者发言或研究结论。","en":"Translate hypotheses into participant criteria, neutral task scripts, facilitator prompts, observation sheets and success criteria. Avoid leading questions or revealing task solutions. Separate observed behavior from preferences. Deliver recording templates, severity rules and prioritization without inventing participants’ statements or findings.","ja":"仮説から参加条件、中立なタスク台本、進行の問い、観察表、成功条件を設計する。誘導質問や正解操作を避け、行動事実と好みを区別。記録様式、重大度基準、改善順を示し、参加者の発言や結果を作らない。"},"examples":{"zh":"针对帮助新用户完成首次配置的功能，完成“可用性测试计划”，给出可以直接使用的内容。","en":"Create usability study plan for a feature helping new users complete onboarding. Provide a usable deliverable.","ja":"新規利用者の初期設定を助ける機能について「ユーザビリティ調査計画」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：目标用户、问题证据、功能边界、约束和成功指标。已写在需求中的信息不必重复。","en":"Provide target users, problem evidence, scope, constraints and success measures. Do not repeat details already in the brief.","ja":"対象者、課題の根拠、範囲、制約、成功指標を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-139","aishort-92"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('project-plan','published','{"id":"project-plan","group":"project","labels":{"zh":"任务拆解与里程碑","en":"Work breakdown and milestones","ja":"作業分解・節目"},"terms":["WBS","里程碑","milestone","work breakdown","工程"],"guidance":{"zh":"按可验收成果拆分任务，标明负责人角色、输入、输出、前置依赖、估算依据和完成条件。给出里程碑、关键路径假设、缓冲和每周检查点，区分日历工期与工作量。团队或时间不足时提出删减范围方案，不用假定人数制造可行性。","en":"Break work into verifiable deliverables with owner role, inputs, outputs, dependencies, estimation basis and completion criteria. Include milestones, critical-path assumptions, buffers and weekly checkpoints. Distinguish elapsed time from effort; propose scope reductions when resources are insufficient instead of inventing team capacity.","ja":"受入可能な成果物に分解し、担当役割、入出力、依存、見積根拠、完了条件を付ける。節目、重要経路の仮定、余裕、週次確認を示す。期間と工数を区別し、資源不足なら架空の人員でなく範囲削減を提案する。"},"examples":{"zh":"针对四周内上线一个小型知识库，完成“任务拆解与里程碑”，给出可以直接使用的内容。","en":"Create work breakdown and milestones for a four-week launch of a small knowledge base. Provide a usable deliverable.","ja":"4週間での小規模ナレッジ公開について「作業分解・節目」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：交付目标、团队角色、时间、依赖和资源限制。已写在需求中的信息不必重复。","en":"Provide deliverables, team roles, dates, dependencies and resource limits. Do not repeat details already in the brief.","ja":"成果物、役割、期間、依存、資源制約を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-201","aishort-279"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('project-risk','published','{"id":"project-risk","group":"project","labels":{"zh":"风险登记与应对","en":"Risk register","ja":"リスク一覧・対応"},"terms":["风险登记","risk register","リスク登録"],"guidance":{"zh":"用原因—事件—影响描述项目风险，区分已发生问题与未来风险。逐项给概率依据、影响、负责人角色、预警信号、预防、应急和复查日期。明确评分只是排序工具，并附升级阈值；不凭空填写精确损失或发生概率。","en":"Describe risks as cause, event and impact, separating future risks from existing issues. Include likelihood basis, impact, owner role, warning signals, prevention, contingency and review date. Explain scores as prioritization aids with escalation thresholds; do not invent precise loss amounts or probabilities.","ja":"原因・事象・影響でリスクを記述し、既発生問題と区別。可能性の根拠、影響、担当役割、予兆、予防、緊急策、再確認日を示す。点数は優先付け用と説明し、架空の精密な確率や損失を出さない。"},"examples":{"zh":"针对四周内上线一个小型知识库，完成“风险登记与应对”，给出可以直接使用的内容。","en":"Create risk register for a four-week launch of a small knowledge base. Provide a usable deliverable.","ja":"4週間での小規模ナレッジ公開について「リスク一覧・対応」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：交付目标、团队角色、时间、依赖和资源限制。已写在需求中的信息不必重复。","en":"Provide deliverables, team roles, dates, dependencies and resource limits. Do not repeat details already in the brief.","ja":"成果物、役割、期間、依存、資源制約を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-201","aishort-279"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('project-retro','published','{"id":"project-retro","group":"project","labels":{"zh":"复盘与行动计划","en":"Retrospective and actions","ja":"振り返り・改善行動"},"terms":["复盘","retrospective","振り返り"],"guidance":{"zh":"从时间线与证据重建目标、结果和偏差，分别列出有效做法、障碍及可控原因。避免把推测写成人员责任，给每项改进设置负责人角色、截止日期、成功信号和复查方式。交付复盘正文与行动表，限制同时推进事项以便落实。","en":"Reconstruct goals, outcomes and gaps from a timeline and evidence. Separate effective practices, obstacles and controllable causes without assigning personal blame from speculation. Give improvements owner roles, deadlines, success signals and review methods. Deliver a retrospective and a small actionable follow-up list.","ja":"時系列と証拠から目標、結果、差を整理し、有効な方法、障害、制御可能な原因を分ける。憶測で個人責任を決めず、改善ごとに役割、期限、成功兆候、確認方法を付ける。本文と実行可能な少数の行動表を出す。"},"examples":{"zh":"针对四周内上线一个小型知识库，完成“复盘与行动计划”，给出可以直接使用的内容。","en":"Create retrospective and actions for a four-week launch of a small knowledge base. Provide a usable deliverable.","ja":"4週間での小規模ナレッジ公開について「振り返り・改善行動」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：交付目标、团队角色、时间、依赖和资源限制。已写在需求中的信息不必重复。","en":"Provide deliverables, team roles, dates, dependencies and resource limits. Do not repeat details already in the brief.","ja":"成果物、役割、期間、依存、資源制約を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-201","aishort-279"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('career-resume','published','{"id":"career-resume","group":"career","labels":{"zh":"简历与求职信","en":"Resume and cover letter","ja":"履歴書・応募文"},"terms":["简历","求职信","resume","cover letter","履歴書"],"guidance":{"zh":"先将岗位要求对应到用户真实经历，标出有证据、待补证据和缺口，再改写摘要、项目要点与求职信。要点呈现行动、方法和实际结果，没有量化数据时不编数字。保留任职时间与技能边界，输出可复制版本及修改理由，不承诺通过ATS或录用。","en":"Map job requirements to real experience, marking supported claims, evidence gaps and missing qualifications. Rewrite the summary, project bullets and cover letter around actions, methods and actual outcomes. Preserve dates and skill boundaries; never invent metrics. Deliver copyable drafts and rationale without promising ATS success or hiring.","ja":"募集要件と実経験を対応させ、証拠あり・不足・未経験を明示。行動、方法、実結果で要約、実績、応募文を改稿し、期間や技能範囲を保つ。数字を作らず、貼付用文と変更理由を示す。選考通過を保証しない。"},"examples":{"zh":"针对有两个真实项目经历的初级开发者，完成“简历与求职信”，给出可以直接使用的内容。","en":"Create resume and cover letter for a junior developer with two real project experiences. Provide a usable deliverable.","ja":"実在する2件のプロジェクト経験を持つ初級開発者について「履歴書・応募文」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：目标职位、岗位描述、真实经历及可公开成果。已写在需求中的信息不必重复。","en":"Provide target role, job description, real experience and shareable outcomes. Do not repeat details already in the brief.","ja":"志望職、募集要件、実経験、公開可能な成果を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-22","aishort-46","aishort-145","aishort-253","pc-resume"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('career-interview','published','{"id":"career-interview","group":"career","labels":{"zh":"岗位模拟面试","en":"Role-specific interview practice","ja":"職種別模擬面接"},"terms":["面试","interview","面接"],"guidance":{"zh":"根据岗位要求与候选人背景设计问题顺序，先问一题并等待回答，再追问证据与取舍。每轮反馈内容完整性、技术准确性和表达结构，给更好的回答框架但不替用户编经历。结束时总结优势、薄弱点和练习建议，模拟反馈不代表招聘判断。","en":"Sequence questions around the role and candidate background. Ask one question, wait, then probe evidence and tradeoffs. Give feedback on completeness, technical accuracy and structure, offering a better response framework without inventing experience. Finish with strengths, gaps and practice steps; simulated feedback is not a hiring judgment.","ja":"職務と背景に合う質問を順序化し、一問ずつ回答を待って根拠や判断を掘り下げる。完全性、技術の正確さ、構成を評価し、架空経験でなく回答の組立てを示す。強み、課題、練習で締め、採用判断と混同しない。"},"examples":{"zh":"针对有两个真实项目经历的初级开发者，完成“岗位模拟面试”，给出可以直接使用的内容。","en":"Create role-specific interview practice for a junior developer with two real project experiences. Provide a usable deliverable.","ja":"実在する2件のプロジェクト経験を持つ初級開発者について「職種別模擬面接」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：目标职位、岗位描述、真实经历及可公开成果。已写在需求中的信息不必重复。","en":"Provide target role, job description, real experience and shareable outcomes. Do not repeat details already in the brief.","ja":"志望職、募集要件、実経験、公開可能な成果を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-22","aishort-46","aishort-145","aishort-253","pc-resume"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('career-gap','published','{"id":"career-gap","group":"career","labels":{"zh":"技能差距与成长路线","en":"Skills gap and growth plan","ja":"スキル差・成長計画"},"terms":["技能差距","career plan","skills gap","スキル差"],"guidance":{"zh":"把目标岗位拆成必备能力和加分项，根据用户证据确定当前水平与待验证项。为每项差距安排练习项目、产出、验收和学习顺序，适配可用时间与预算。引用当前岗位信息时标明来源日期，不以热门标签代替真实技能路径。","en":"Separate required and optional role skills, using evidence to assess current ability and unknowns. Assign each gap a practice project, deliverable, acceptance check and learning sequence within available time and budget. Date any current job-market sources; replace trend labels with demonstrable skills and realistic milestones.","ja":"必須能力と加点要素を分け、証拠から現状と未確認を評価。差ごとに練習課題、成果物、受入確認、学習順を時間・予算内で設計する。求人情報には確認日と出典を付け、流行語でなく実証可能な技能を示す。"},"examples":{"zh":"针对有两个真实项目经历的初级开发者，完成“技能差距与成长路线”，给出可以直接使用的内容。","en":"Create skills gap and growth plan for a junior developer with two real project experiences. Provide a usable deliverable.","ja":"実在する2件のプロジェクト経験を持つ初級開発者について「スキル差・成長計画」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：目标职位、岗位描述、真实经历及可公开成果。已写在需求中的信息不必重复。","en":"Provide target role, job description, real experience and shareable outcomes. Do not repeat details already in the brief.","ja":"志望職、募集要件、実経験、公開可能な成果を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-22","aishort-46","aishort-145","aishort-253","pc-resume"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('communication-email','published','{"id":"communication-email","group":"communication","labels":{"zh":"商务邮件与跟进","en":"Business email and follow-up","ja":"業務メール・フォロー"},"terms":["邮件","email","follow-up","メール"],"guidance":{"zh":"围绕收件人需要知道和采取的行动写主题、开场、事实、请求与期限。按关系与场景控制正式程度，给初次邮件和未回复跟进版本。保留用户承诺边界，不添加不存在的附件、会议约定或付款承诺；长信息用清晰段落压缩。","en":"Write subject, opening, facts, requested action and deadline around the recipient’s needs. Match formality to the relationship and provide initial and follow-up versions. Preserve commitment boundaries: invent no attachments, meeting agreements or payment promises. Condense long context into clear paragraphs.","ja":"相手が知り実行すべき点を軸に件名、導入、事実、依頼、期限を書く。関係に合わせた丁寧さで初回と催促の文を出す。存在しない添付、会議合意、支払約束を加えず、長い背景を明快な段落にする。"},"examples":{"zh":"针对跨团队协调一次版本延期，完成“商务邮件与跟进”，给出可以直接使用的内容。","en":"Create business email and follow-up for coordinating a release delay across teams. Provide a usable deliverable.","ja":"部門間での公開延期の調整について「業務メール・フォロー」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：收件人、背景事实、希望达成的决定和期限。已写在需求中的信息不必重复。","en":"Provide recipient, background facts, desired decision and deadline. Do not repeat details already in the brief.","ja":"相手、背景事実、必要な判断、期限を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-201","aishort-241"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('communication-minutes','published','{"id":"communication-minutes","group":"communication","labels":{"zh":"会议纪要与待办","en":"Meeting notes and actions","ja":"議事録・アクション"},"terms":["会议纪要","minutes","meeting notes","議事録"],"guidance":{"zh":"从提供的记录提取议题、事实、决定、异议、待定问题和行动项。行动项逐条标明负责人、期限与完成标准；未明确的内容标注待确认。保留关键数字和原话出处，不把讨论建议当成已批准决定，输出简版纪要与可追踪待办表。","en":"Extract agenda, facts, decisions, dissent, open questions and actions from supplied notes. Assign each action an owner, deadline and completion test, marking unspecified values unconfirmed. Preserve key numbers and quote locations. Distinguish suggestions from approved decisions; provide concise minutes and a trackable action table.","ja":"記録から議題、事実、決定、異論、未決、行動を抽出。行動に担当、期限、完了基準を付け、不明は要確認とする。数値と発言箇所を保ち、提案を承認済みとしない。簡潔な議事録と追跡表を出す。"},"examples":{"zh":"针对跨团队协调一次版本延期，完成“会议纪要与待办”，给出可以直接使用的内容。","en":"Create meeting notes and actions for coordinating a release delay across teams. Provide a usable deliverable.","ja":"部門間での公開延期の調整について「議事録・アクション」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：收件人、背景事实、希望达成的决定和期限。已写在需求中的信息不必重复。","en":"Provide recipient, background facts, desired decision and deadline. Do not repeat details already in the brief.","ja":"相手、背景事実、必要な判断、期限を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-201","aishort-241"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('communication-alignment','published','{"id":"communication-alignment","group":"communication","labels":{"zh":"分歧沟通与协调","en":"Disagreement and alignment","ja":"意見相違の調整"},"terms":["分歧","协调","alignment","disagreement","意見相違"],"guidance":{"zh":"分开各方事实、诉求、约束和误解，先找共同目标，再提出可协商选项及其代价。给开场、澄清问题、回应异议和结束确认的具体话术，避免指责、威胁或虚假共识。最终列出已同意、未同意与下一次确认事项。","en":"Separate facts, interests, constraints and misunderstandings for each party. Identify a shared goal and negotiable options with costs. Provide concrete openings, clarifying questions, objection responses and closing confirmations without blame, threats or invented agreement. Record agreed, unresolved and next-confirmation items.","ja":"双方の事実、目的、制約、誤解を分け、共通目標と代価付きの選択肢を出す。導入、確認質問、異論への返答、終了確認の具体文を示し、非難・脅し・架空合意を避ける。合意、未合意、次回確認を整理する。"},"examples":{"zh":"针对跨团队协调一次版本延期，完成“分歧沟通与协调”，给出可以直接使用的内容。","en":"Create disagreement and alignment for coordinating a release delay across teams. Provide a usable deliverable.","ja":"部門間での公開延期の調整について「意見相違の調整」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：收件人、背景事实、希望达成的决定和期限。已写在需求中的信息不必重复。","en":"Provide recipient, background facts, desired decision and deadline. Do not repeat details already in the brief.","ja":"相手、背景事実、必要な判断、期限を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-201","aishort-241"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('support-reply','published','{"id":"support-reply","group":"support","labels":{"zh":"工单回复与升级","en":"Ticket response and escalation","ja":"問い合わせ回答・引継ぎ"},"terms":["工单","ticket","客服回复","問い合わせ回答"],"guidance":{"zh":"识别问题类型与客户诉求，用简短确认、已知事实、具体步骤和下一步组成回复。引用提供的政策，超出权限时写清升级原因及需补资料。不得承诺不存在的退款、补偿或解决时间；内部排查备注与发给客户的正文分开。","en":"Identify issue type and customer need, then write acknowledgement, verified facts, steps and next action. Apply supplied policy and explain escalation with only necessary missing information. Promise no unsupported refunds, compensation or resolution times. Separate internal troubleshooting notes from the customer-facing response.","ja":"問題と要望を特定し、受止め、確認事実、手順、次の対応で回答する。提供方針を用い、権限外なら引継理由と必要情報を示す。根拠のない返金・補償・解決期限を約束せず、内部メモと顧客文を分ける。"},"examples":{"zh":"针对提供退款政策与使用说明的在线服务，完成“工单回复与升级”，给出可以直接使用的内容。","en":"Create ticket response and escalation for an online service with refund policies and user guides. Provide a usable deliverable.","ja":"返金方針と利用手順のあるオンラインサービスについて「問い合わせ回答・引継ぎ」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：客户问题、已确认政策、产品版本和可采取操作。已写在需求中的信息不必重复。","en":"Provide customer issue, verified policy, product version and permitted actions. Do not repeat details already in the brief.","ja":"問い合わせ、確認済み方針、製品版、対応可能な操作を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-39","aishort-241","pc-support"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('support-faq','published','{"id":"support-faq","group":"support","labels":{"zh":"常见问题与答案","en":"Frequently asked questions","ja":"よくある質問と回答"},"terms":["FAQ","常见问题","よくある質問"],"guidance":{"zh":"按用户任务归类真实高频问题，合并同义问法，给每题直接答案、适用条件、操作步骤和例外。答案只依据提供的政策或文档，未知处标记待核实，附来源位置与维护负责人字段。避免把营销口号写成答案。","en":"Group genuine recurring questions by user task and merge equivalent wording. Give direct answers, conditions, steps and exceptions from supplied policies or documents. Mark unknowns for verification and include source locations and maintenance-owner fields. Do not substitute marketing slogans for useful answers.","ja":"実際の頻出質問を利用目的別に分類し同義を統合。提供方針・文書から直接回答、条件、手順、例外を作る。不明は要確認とし、出典箇所と保守担当欄を付け、広告文句を答えにしない。"},"examples":{"zh":"针对提供退款政策与使用说明的在线服务，完成“常见问题与答案”，给出可以直接使用的内容。","en":"Create frequently asked questions for an online service with refund policies and user guides. Provide a usable deliverable.","ja":"返金方針と利用手順のあるオンラインサービスについて「よくある質問と回答」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：客户问题、已确认政策、产品版本和可采取操作。已写在需求中的信息不必重复。","en":"Provide customer issue, verified policy, product version and permitted actions. Do not repeat details already in the brief.","ja":"問い合わせ、確認済み方針、製品版、対応可能な操作を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-39","aishort-241","pc-support"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('support-guide','published','{"id":"support-guide","group":"support","labels":{"zh":"帮助中心操作指南","en":"Help-center how-to","ja":"ヘルプ操作ガイド"},"terms":["帮助中心","操作指南","how-to","help center","操作ガイド"],"guidance":{"zh":"给出适用人群、前提条件和完成目标，再将操作拆为编号步骤，每步说明位置、动作与可见结果。补充常见失败、撤销方式和版本差异，优先使用用户提供的界面名称。没有截图时只列截图需求，不编造按钮或不存在的功能。","en":"State audience, prerequisites and completion goal, then write numbered steps with location, action and visible outcome. Include common failures, undo options and version differences, using supplied UI names. Without screenshots, list needed captures instead of inventing buttons or unsupported features.","ja":"対象者、前提、完成状態を示し、場所・操作・見える結果を番号順に書く。失敗例、取消、版差を補足し、提供された画面名を優先。画面資料がなければ撮影要件を列挙し、架空のボタンや機能を作らない。"},"examples":{"zh":"针对提供退款政策与使用说明的在线服务，完成“帮助中心操作指南”，给出可以直接使用的内容。","en":"Create help-center how-to for an online service with refund policies and user guides. Provide a usable deliverable.","ja":"返金方針と利用手順のあるオンラインサービスについて「ヘルプ操作ガイド」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：客户问题、已确认政策、产品版本和可采取操作。已写在需求中的信息不必重复。","en":"Provide customer issue, verified policy, product version and permitted actions. Do not repeat details already in the brief.","ja":"問い合わせ、確認済み方針、製品版、対応可能な操作を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-39","aishort-241","pc-support"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('social-posts','published','{"id":"social-posts","group":"social","labels":{"zh":"平台图文帖","en":"Platform-specific posts","ja":"媒体別投稿文"},"terms":["图文帖","post","小红书","投稿文"],"guidance":{"zh":"按平台阅读方式给标题、开头、主体、结尾与必要标签，保留真实体验和信息密度。提供三个不同切入角度，并为其中最合适的一个写完整正文。避免假装亲测、编造用户评论、夸大效果或机械堆表情，说明需要配图的位置与内容。","en":"Write titles, opening, body, ending and relevant tags for the platform’s reading style. Offer three distinct angles and fully draft the best fit using real experience and dense information. Invent no first-hand use, reviews or outcomes. Avoid emoji clutter and describe purposeful image placements.","ja":"媒体の読み方に合わせ題名、導入、本文、結び、必要タグを作る。異なる3つの切口を示し最適案を実体験の範囲で完成。架空体験・口コミ・効果誇張や絵文字過多を避け、画像位置と内容を説明する。"},"examples":{"zh":"针对介绍一款有真实使用记录的效率工具，完成“平台图文帖”，给出可以直接使用的内容。","en":"Create platform-specific posts for introducing a productivity tool with real usage notes. Provide a usable deliverable.","ja":"実際の利用記録がある効率化ツールの紹介について「媒体別投稿文」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：平台、读者、素材事实、篇幅和行动目标。已写在需求中的信息不必重复。","en":"Provide platform, audience, factual material, length and desired action. Do not repeat details already in the brief.","ja":"媒体、読者、事実素材、長さ、行動目標を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-143","aishort-204","aishort-209"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('social-short-video','published','{"id":"social-short-video","group":"social","labels":{"zh":"短视频口播脚本","en":"Short-video spoken script","ja":"短尺動画の話し言葉台本"},"terms":["口播","short video","spoken script","短尺動画"],"guidance":{"zh":"按目标时长编排开场、问题、演示、证据和结尾行动，逐段标注秒数、口播、画面、字幕及音效。用适合朗读的短句并核对总时长，给可删除的压缩段落。没有实测数据时不写效果承诺，不把脚本交付说成视频已经生成。","en":"Fit a hook, problem, demonstration, evidence and closing action to the duration. Mark seconds, speech, visuals, captions and sound per segment. Use speakable sentences, check total timing and identify optional cuts. Avoid unsupported performance claims and never describe a script as an already generated video.","ja":"尺に合わせ導入、課題、実演、証拠、結びを配置し、秒数、発話、画、字幕、音を段別に示す。話しやすい短文で全体時間を確認し削れる部分を示す。未検証効果を保証せず、台本を動画生成済みとしない。"},"examples":{"zh":"针对介绍一款有真实使用记录的效率工具，完成“短视频口播脚本”，给出可以直接使用的内容。","en":"Create short-video spoken script for introducing a productivity tool with real usage notes. Provide a usable deliverable.","ja":"実際の利用記録がある効率化ツールの紹介について「短尺動画の話し言葉台本」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：平台、读者、素材事实、篇幅和行动目标。已写在需求中的信息不必重复。","en":"Provide platform, audience, factual material, length and desired action. Do not repeat details already in the brief.","ja":"媒体、読者、事実素材、長さ、行動目標を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-143","aishort-204","aishort-209"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('social-repurpose','published','{"id":"social-repurpose","group":"social","labels":{"zh":"长内容拆分复用","en":"Repurpose long-form content","ja":"長文の再構成・再利用"},"terms":["拆分复用","repurpose","再利用"],"guidance":{"zh":"从原文提取可独立成立的观点与证据，分别改成短帖、邮件摘要和口播版本，保留原意与来源。每份内容独立可读，标出被省略的限定条件，避免断章取义。提供渠道、角度、素材需求和发布先后建议，但不代替用户发布。","en":"Extract self-contained claims and evidence from the source, then adapt them into short posts, an email summary and a spoken version. Preserve meaning and attribution, marking omitted qualifications so excerpts do not mislead. Provide channels, angles, asset needs and sequence suggestions without publishing on the user’s behalf.","ja":"原文の独立した主張と根拠を抽出し、短文投稿、メール要約、口播にする。意味と出典を保ち、省略条件を明記して切取誤解を避ける。媒体、切口、素材、順序を提案するが、利用者に代わって投稿しない。"},"examples":{"zh":"针对介绍一款有真实使用记录的效率工具，完成“长内容拆分复用”，给出可以直接使用的内容。","en":"Create repurpose long-form content for introducing a productivity tool with real usage notes. Provide a usable deliverable.","ja":"実際の利用記録がある効率化ツールの紹介について「長文の再構成・再利用」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：平台、读者、素材事实、篇幅和行动目标。已写在需求中的信息不必重复。","en":"Provide platform, audience, factual material, length and desired action. Do not repeat details already in the brief.","ja":"媒体、読者、事実素材、長さ、行動目標を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-143","aishort-204","aishort-209"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('commerce-listing','published','{"id":"commerce-listing","group":"commerce","labels":{"zh":"商品详情与卖点","en":"Product listing and benefits","ja":"商品詳細・訴求点"},"terms":["商品详情","listing","卖点","商品詳細"],"guidance":{"zh":"把参数转成有依据的使用利益，输出标题、要点、完整描述、规格表、适用与不适用人群。区分已证实特点和待确认信息，单位与型号保持一致；不写虚假销量、限时稀缺或认证。补充主图和细节图的信息需求，适配指定平台篇幅。","en":"Translate specifications into evidenced benefits and deliver title, bullets, description, spec table and suitable/unsuitable users. Separate verified features from unknowns, preserving units and model names. Invent no sales numbers, scarcity or certifications. Include information needs for hero/detail images within platform length limits.","ja":"仕様を根拠ある利点に変え、題名、要点、説明、仕様表、適合・不適合利用者を出す。確認済みと不明を区別し単位・型番を保つ。売上、希少性、認証を捏造せず、媒体長に合わせ主画像・詳細画像の情報要件を添える。"},"examples":{"zh":"针对一款规格和售后政策已确认的桌面收纳盒，完成“商品详情与卖点”，给出可以直接使用的内容。","en":"Create product listing and benefits for a desk organizer with verified specifications and after-sales policy. Provide a usable deliverable.","ja":"仕様とサポート方針が確認済みの卓上収納箱について「商品詳細・訴求点」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：商品参数、目标买家、平台规则、卖点证据和售后政策。已写在需求中的信息不必重复。","en":"Provide product specs, buyers, platform rules, claim evidence and support policy. Do not repeat details already in the brief.","ja":"仕様、購入者、媒体規則、訴求根拠、サポート方針を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-45","aishort-140","aishort-141","aishort-39"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('commerce-compare','published','{"id":"commerce-compare","group":"commerce","labels":{"zh":"商品对比选购","en":"Product comparison guide","ja":"商品比較ガイド"},"terms":["商品对比","comparison guide","商品比較"],"guidance":{"zh":"按买家的用途与限制建立比较维度，对每款商品列相同口径的参数、优点、限制和适合场景。价格、库存和兼容性标注核实日期，资料缺失时不推测。给条件式建议而非绝对最好，说明结论依赖哪些输入。","en":"Build comparison criteria from buyer needs and constraints. Compare products on consistent specifications, advantages, limits and suitable situations. Date price, availability and compatibility checks; do not infer missing data. Give conditional recommendations instead of an absolute winner and state which inputs drive the conclusion.","ja":"用途と制約から比較軸を作り、同じ定義の仕様、長所、制限、適用場面で比べる。価格、在庫、互換性に確認日を付け、不明は推測しない。絶対的な最良でなく条件別提案と判断に使った情報を示す。"},"examples":{"zh":"针对一款规格和售后政策已确认的桌面收纳盒，完成“商品对比选购”，给出可以直接使用的内容。","en":"Create product comparison guide for a desk organizer with verified specifications and after-sales policy. Provide a usable deliverable.","ja":"仕様とサポート方針が確認済みの卓上収納箱について「商品比較ガイド」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：商品参数、目标买家、平台规则、卖点证据和售后政策。已写在需求中的信息不必重复。","en":"Provide product specs, buyers, platform rules, claim evidence and support policy. Do not repeat details already in the brief.","ja":"仕様、購入者、媒体規則、訴求根拠、サポート方針を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-45","aishort-140","aishort-141","aishort-39"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('commerce-questions','published','{"id":"commerce-questions","group":"commerce","labels":{"zh":"售前问答与异议","en":"Pre-sales questions","ja":"購入前FAQ・懸念対応"},"terms":["售前","pre-sales","购买疑问","購入前"],"guidance":{"zh":"收集尺寸、兼容、使用、配送、退换等购买疑问，逐题用已确认参数或政策给直接答案。对无法保证的效果写清边界，提供核实步骤或转人工条件。给简短版和详细版回复，不诱导隐瞒限制或虚构购买紧迫性。","en":"Address size, compatibility, use, shipping and returns using verified specs or policies. State limits on unguaranteed outcomes and provide checks or escalation conditions. Deliver concise and detailed answers without concealing limitations or manufacturing urgency.","ja":"寸法、互換、使用、配送、返品の疑問に確認済み仕様・方針で答える。保証不能な効果の境界、確認手順、引継条件を示す。短文・詳細版を出し、制限を隠したり緊急性を作ったりしない。"},"examples":{"zh":"针对一款规格和售后政策已确认的桌面收纳盒，完成“售前问答与异议”，给出可以直接使用的内容。","en":"Create pre-sales questions for a desk organizer with verified specifications and after-sales policy. Provide a usable deliverable.","ja":"仕様とサポート方針が確認済みの卓上収納箱について「購入前FAQ・懸念対応」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：商品参数、目标买家、平台规则、卖点证据和售后政策。已写在需求中的信息不必重复。","en":"Provide product specs, buyers, platform rules, claim evidence and support policy. Do not repeat details already in the brief.","ja":"仕様、購入者、媒体規則、訴求根拠、サポート方針を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-45","aishort-140","aishort-141","aishort-39"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('seo-keywords','published','{"id":"seo-keywords","group":"seo","labels":{"zh":"搜索意图与选题","en":"Search intent and topics","ja":"検索意図・テーマ設計"},"terms":["搜索意图","keyword","search intent","検索意図"],"guidance":{"zh":"按用户问题、搜索意图和主题关系组织关键词，合并近义词但保留不同意图。输出主题簇、对应页面、优先级理由和内容缺口。搜索量与难度必须来自给定工具数据，缺失时标为未知；不以关键词数量或堆砌保证排名。","en":"Group keywords by user question, intent and topic relationships, merging synonyms without collapsing distinct intents. Deliver clusters, target pages, priority rationale and content gaps. Use supplied tool data for volume/difficulty or mark them unknown; neither keyword count nor stuffing guarantees rankings.","ja":"質問、意図、テーマ関係で語を分類し、同義をまとめつつ異なる意図は残す。クラスタ、対応ページ、優先理由、内容不足を示す。検索量・難度は提供データに限り、不明を明記。語数や詰込で順位を保証しない。"},"examples":{"zh":"针对一个提供三语使用教程的小型网站，完成“搜索意图与选题”，给出可以直接使用的内容。","en":"Create search intent and topics for a small site offering trilingual tutorials. Provide a usable deliverable.","ja":"3言語の使い方記事を提供する小規模サイトについて「検索意図・テーマ設計」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：页面内容、目标读者、关键词资料及可用搜索数据。已写在需求中的信息不必重复。","en":"Provide page content, audience, keyword material and available search data. Do not repeat details already in the brief.","ja":"ページ内容、読者、キーワード資料、検索データを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-38","aishort-40","pc-seo","pc-links"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('seo-brief','published','{"id":"seo-brief","group":"seo","labels":{"zh":"搜索页面内容简报","en":"Search page content brief","ja":"検索ページ制作要項"},"terms":["内容简报","content brief","制作要項"],"guidance":{"zh":"明确页面服务的读者问题与核心答案，给标题、段落任务、需补证据、图表和相关内链。按阅读顺序组织内容，而不是机械重复关键词；为作者写出具体交付要求和事实核对清单。没有实际检索时不编造竞品排名或搜索结果特征。","en":"Define the reader’s question and core answer, then specify title, section purposes, required evidence, visuals and relevant internal links. Organize for reading rather than repetition. Give writers concrete deliverables and fact checks; without actual search, invent no competitor rankings or result-page features.","ja":"読者の疑問と中核回答を定め、題名、各節の役割、根拠、図、関連内リンクを指定。語の反復でなく読む順に構成し、執筆者に具体成果と事実確認を示す。検索未実施なら競合順位や結果画面の特徴を作らない。"},"examples":{"zh":"针对一个提供三语使用教程的小型网站，完成“搜索页面内容简报”，给出可以直接使用的内容。","en":"Create search page content brief for a small site offering trilingual tutorials. Provide a usable deliverable.","ja":"3言語の使い方記事を提供する小規模サイトについて「検索ページ制作要項」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：页面内容、目标读者、关键词资料及可用搜索数据。已写在需求中的信息不必重复。","en":"Provide page content, audience, keyword material and available search data. Do not repeat details already in the brief.","ja":"ページ内容、読者、キーワード資料、検索データを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-38","aishort-40","pc-seo","pc-links"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('seo-metadata','published','{"id":"seo-metadata","group":"seo","labels":{"zh":"标题描述与内链","en":"Metadata and internal links","ja":"タイトル・説明・内部リンク"},"terms":["meta","内链","internal link","メタ","内部リンク"],"guidance":{"zh":"依据页面真实内容提供多组准确的标题和描述，给出字符长度并保留品牌与语言习惯。仅从提供且相关的页面建议内链与自然锚文本，检查重复、空链接和意图偏差。说明描述可能被搜索引擎改写，不保证收录或排名。","en":"Create accurate title/description variants from actual content, with character counts and natural brand/language usage. Recommend relevant internal links only from supplied pages, using descriptive anchors and checking duplicates, missing destinations and intent mismatch. Note that search engines may rewrite snippets; guarantee no indexing or ranking.","ja":"実内容に沿う題名・説明案と文字数を示し、ブランドと自然な言葉を保つ。提供された関連ページだけへ説明的な内部リンクを提案し、重複、宛先欠落、意図ずれを点検。説明文の書換可能性を述べ、登録や順位を保証しない。"},"examples":{"zh":"针对一个提供三语使用教程的小型网站，完成“标题描述与内链”，给出可以直接使用的内容。","en":"Create metadata and internal links for a small site offering trilingual tutorials. Provide a usable deliverable.","ja":"3言語の使い方記事を提供する小規模サイトについて「タイトル・説明・内部リンク」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：页面内容、目标读者、关键词资料及可用搜索数据。已写在需求中的信息不必重复。","en":"Provide page content, audience, keyword material and available search data. Do not repeat details already in the brief.","ja":"ページ内容、読者、キーワード資料、検索データを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-38","aishort-40","pc-seo","pc-links"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('slides-proposal','published','{"id":"slides-proposal","group":"slides","labels":{"zh":"方案汇报PPT","en":"Proposal presentation","ja":"提案プレゼン"},"terms":["方案汇报","pitch deck","proposal slides","提案発表"],"guidance":{"zh":"按需要促成的决定构建问题、证据、方案、取舍、计划和请求，逐页给结论式标题、正文、图形建议及讲者备注。核对页数与时长，每页只推进一个主要观点；不虚构业绩和预测。输出可粘贴到WPS演示或PowerPoint的完整内容。","en":"Build problem, evidence, proposal, tradeoffs, plan and requested decision. For each slide, supply a claim-led title, complete copy, visual suggestion and speaker notes. Fit slide count to duration with one main idea per slide. Invent no performance results or forecasts; deliver content ready for WPS Presentation or PowerPoint.","ja":"必要な判断へ向け課題、根拠、提案、比較、計画、依頼を構成。各頁に結論型見出し、本文、図案、話者メモを付け、枚数と時間を合わせ一頁一論点にする。実績・予測を作らず、WPSやPowerPointに使える内容を出す。"},"examples":{"zh":"针对向团队介绍知识库改版方案的十分钟汇报，完成“方案汇报PPT”，给出可以直接使用的内容。","en":"Create proposal presentation for a ten-minute team presentation on a knowledge-base redesign. Provide a usable deliverable.","ja":"ナレッジ改修を紹介する10分のチーム発表について「提案プレゼン」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：听众、时长、核心结论、资料和目标软件。已写在需求中的信息不必重复。","en":"Provide audience, duration, key conclusion, material and target software. Do not repeat details already in the brief.","ja":"聴衆、時間、結論、素材、対象ソフトを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-187","aishort-195"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('slides-training','published','{"id":"slides-training","group":"slides","labels":{"zh":"培训课件","en":"Training slide content","ja":"研修スライド"},"terms":["培训课件","training deck","研修資料"],"guidance":{"zh":"以学习者能完成的操作为目标安排概念、演示、练习、反馈和总结。逐页写正文、案例、互动问题和参考答案，给练习时间与主持提示。对新手提供解释，对熟练者提供延伸，不只交付目录或把整篇讲义塞入一页。","en":"Organize concepts, demonstration, practice, feedback and recap around observable learner actions. Supply slide copy, examples, interactive questions, answer keys, practice timing and facilitator prompts. Include beginner support and extensions without delivering only an outline or cramming an entire handout onto one slide.","ja":"習得後の操作を目標に概念、実演、練習、返答、まとめを配置。各頁の本文、例、問い、解答、時間、進行メモを作る。初心者補助と発展を用意し、目次だけや一頁への全文詰込を避ける。"},"examples":{"zh":"针对向团队介绍知识库改版方案的十分钟汇报，完成“培训课件”，给出可以直接使用的内容。","en":"Create training slide content for a ten-minute team presentation on a knowledge-base redesign. Provide a usable deliverable.","ja":"ナレッジ改修を紹介する10分のチーム発表について「研修スライド」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：听众、时长、核心结论、资料和目标软件。已写在需求中的信息不必重复。","en":"Provide audience, duration, key conclusion, material and target software. Do not repeat details already in the brief.","ja":"聴衆、時間、結論、素材、対象ソフトを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-187","aishort-195"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('slides-speech','published','{"id":"slides-speech","group":"slides","labels":{"zh":"逐页讲稿与问答","en":"Speaker notes and Q&A","ja":"発表原稿・質疑応答"},"terms":["讲稿","speaker notes","Q&A","発表原稿"],"guidance":{"zh":"根据现有幻灯片写逐页自然口语讲稿，包含开场、转场、强调与结束，并分配时间。预测听众可能追问的事实和取舍，给基于已有资料的回答及未知时的回应。不要新增幻灯片里没有依据的数字，提供超时可删版本。","en":"Turn existing slides into natural spoken notes with opening, transitions, emphasis, close and timing. Anticipate questions on facts and tradeoffs, answering from supplied material and acknowledging unknowns. Add no unsupported numbers; provide optional cuts for a shorter delivery.","ja":"既存スライドから導入、つなぎ、強調、締め、時間を含む自然な原稿を作る。事実や取捨への質問を予想し、提供資料で回答、不明時の返しも示す。根拠なしの数値を加えず短縮版を用意する。"},"examples":{"zh":"针对向团队介绍知识库改版方案的十分钟汇报，完成“逐页讲稿与问答”，给出可以直接使用的内容。","en":"Create speaker notes and q&a for a ten-minute team presentation on a knowledge-base redesign. Provide a usable deliverable.","ja":"ナレッジ改修を紹介する10分のチーム発表について「発表原稿・質疑応答」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：听众、时长、核心结论、资料和目标软件。已写在需求中的信息不必重复。","en":"Provide audience, duration, key conclusion, material and target software. Do not repeat details already in the brief.","ja":"聴衆、時間、結論、素材、対象ソフトを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-187","aishort-195"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('reading-notes','published','{"id":"reading-notes","group":"reading","labels":{"zh":"阅读笔记与行动","en":"Reading notes and application","ja":"読書ノート・応用"},"terms":["读书笔记","reading notes","読書ノート"],"guidance":{"zh":"提取中心问题、关键观点、论证链、例子和适用边界，区分作者主张与自己的解释。用原文位置支撑摘要，给概念关系和可尝试的小行动。不因只有书名而假装读过全文；资料不全时只处理提供部分。","en":"Extract the core question, claims, reasoning, examples and applicability limits, separating author claims from interpretation. Ground notes in source locations and include concept relationships and small practical experiments. A title alone is not evidence of reading the book; process only supplied material when sources are incomplete.","ja":"中心疑問、主張、論証、例、適用範囲を抽出し、著者の意見と解釈を分ける。原文位置を根拠に概念関係と小さな応用行動を示す。書名だけで通読済みとせず、資料不足なら提供範囲のみ扱う。"},"examples":{"zh":"针对三篇关于远程协作的已提供文章，完成“阅读笔记与行动”，给出可以直接使用的内容。","en":"Create reading notes and application for three supplied articles about remote collaboration. Provide a usable deliverable.","ja":"提供済みの遠隔協働に関する3記事について「読書ノート・応用」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：原文或摘录、阅读目的、引用方式和输出篇幅。已写在需求中的信息不必重复。","en":"Provide source text/excerpts, reading goal, citation format and length. Do not repeat details already in the brief.","ja":"原文・抜粋、読書目的、引用方式、分量を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-47","aishort-215","aishort-240"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('reading-synthesis','published','{"id":"reading-synthesis","group":"reading","labels":{"zh":"多来源对照综述","en":"Compare and synthesize sources","ja":"複数資料の比較統合"},"terms":["多来源","synthesis","source comparison","資料比較"],"guidance":{"zh":"建立来源、日期、研究或观点类型、主张、证据和限制对照表，识别一致、冲突与信息缺口。围绕主题综合而非逐篇拼接，并为结论标明具体出处。无法消解的冲突保留，不能把来源数量当成正确性证明。","en":"Compare source, date, type, claims, evidence and limitations. Identify agreement, conflict and gaps, synthesizing by theme rather than concatenating summaries. Attribute each conclusion to specific sources. Preserve unresolved disagreements and do not treat source count as proof of correctness.","ja":"出典、日付、種別、主張、証拠、制限を対照し、一致、対立、不足を見つける。記事順の連結でなく主題別に統合し、結論に出典を付ける。未解消の対立を残し、資料数を正しさの証明にしない。"},"examples":{"zh":"针对三篇关于远程协作的已提供文章，完成“多来源对照综述”，给出可以直接使用的内容。","en":"Create compare and synthesize sources for three supplied articles about remote collaboration. Provide a usable deliverable.","ja":"提供済みの遠隔協働に関する3記事について「複数資料の比較統合」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：原文或摘录、阅读目的、引用方式和输出篇幅。已写在需求中的信息不必重复。","en":"Provide source text/excerpts, reading goal, citation format and length. Do not repeat details already in the brief.","ja":"原文・抜粋、読書目的、引用方式、分量を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-47","aishort-215","aishort-240"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('reading-summary','published','{"id":"reading-summary","group":"reading","labels":{"zh":"长文分层摘要","en":"Layered long-document summary","ja":"長文の階層要約"},"terms":["长文摘要","executive summary","long summary","長文要約"],"guidance":{"zh":"先给一句话主旨和短摘要，再给按原文结构的详细摘要、关键数字、条件和待办。保留否定、概率和限制条件，逐项核对不得改变结论强度。标明覆盖的章节与省略范围，超长材料分批建立可合并摘要，不声称读取未提供部分。","en":"Provide a one-sentence thesis, short summary, structural detailed summary, key figures, conditions and actions. Preserve negation, uncertainty and qualifications without strengthening claims. State covered sections and omissions. For long inputs, create mergeable chunk summaries without claiming access to unsupplied text.","ja":"一文主旨、短要約、構造別詳細、数値、条件、行動の順に出す。否定、不確実性、限定を保ち主張を強めない。対象章と省略範囲を明示し、長大なら統合可能な部分要約に分け、未提供箇所を読んだとしない。"},"examples":{"zh":"针对三篇关于远程协作的已提供文章，完成“长文分层摘要”，给出可以直接使用的内容。","en":"Create layered long-document summary for three supplied articles about remote collaboration. Provide a usable deliverable.","ja":"提供済みの遠隔協働に関する3記事について「長文の階層要約」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：原文或摘录、阅读目的、引用方式和输出篇幅。已写在需求中的信息不必重复。","en":"Provide source text/excerpts, reading goal, citation format and length. Do not repeat details already in the brief.","ja":"原文・抜粋、読書目的、引用方式、分量を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-47","aishort-215","aishort-240"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('assessment-bank','published','{"id":"assessment-bank","group":"assessment","labels":{"zh":"分层题库与解析","en":"Question bank with explanations","ja":"段階別問題・解説"},"terms":["题库","question bank","問題集"],"guidance":{"zh":"按知识点和认知难度设计题目分布，输出完整题干、选项、答案、解析和考查点。选择题确保唯一最优答案，干扰项对应常见误解；主观题给示例而非唯一表述。检查题目重复、泄露答案线索及超出教学范围的问题。","en":"Distribute questions by topic and cognitive demand, providing full stems, options, answers, explanations and assessed skills. Multiple-choice items need one best answer and misconception-based distractors; open responses need examples rather than a single wording. Check duplication, answer cues and scope violations.","ja":"知識点と認知難度で配分し、問題、選択肢、解答、解説、評価項目を出す。選択式は最良解一つと誤解に基づく誤答、記述式は唯一表現でなく例を用意。重複、答えの手掛り、範囲外を点検する。"},"examples":{"zh":"针对初学者的Python循环与列表练习，完成“分层题库与解析”，给出可以直接使用的内容。","en":"Create question bank with explanations for Python loop and list practice for beginners. Provide a usable deliverable.","ja":"初心者向けPythonのループとリスト演習について「段階別問題・解説」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：学习目标、年龄或水平、知识范围、题型和评分要求。已写在需求中的信息不必重复。","en":"Provide learning goals, age/level, scope, question types and grading criteria. Do not repeat details already in the brief.","ja":"学習目標、年齢・水準、範囲、問題形式、採点条件を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-131","aishort-263"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('assessment-rubric','published','{"id":"assessment-rubric","group":"assessment","labels":{"zh":"评分量规与反馈","en":"Rubric and feedback","ja":"採点基準・フィードバック"},"terms":["量规","rubric","grading","採点基準"],"guidance":{"zh":"从任务目标推导评分维度、权重和各水平可观察的表现，给示例锚点与扣分边界。对提供的作答逐项引用证据，说明得分和改进动作；不凭文字推断学生人格或潜力。标明这是辅助反馈，保留教师最终判断。","en":"Derive dimensions, weights and observable performance levels from the task goal, including examples and deduction boundaries. For supplied work, cite evidence per criterion and explain scores with actionable improvements. Infer no personality or potential from text; label feedback as assistance with final judgment left to the teacher.","ja":"目標から観点、配点、観察可能な水準、例、減点境界を設計。答案の証拠を観点別に引用し、点数と改善行動を説明する。文章から人格や将来性を推断せず、教師の最終判断を残す補助評価とする。"},"examples":{"zh":"针对初学者的Python循环与列表练习，完成“评分量规与反馈”，给出可以直接使用的内容。","en":"Create rubric and feedback for Python loop and list practice for beginners. Provide a usable deliverable.","ja":"初心者向けPythonのループとリスト演習について「採点基準・フィードバック」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：学习目标、年龄或水平、知识范围、题型和评分要求。已写在需求中的信息不必重复。","en":"Provide learning goals, age/level, scope, question types and grading criteria. Do not repeat details already in the brief.","ja":"学習目標、年齢・水準、範囲、問題形式、採点条件を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-131","aishort-263"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('assessment-misconceptions','published','{"id":"assessment-misconceptions","group":"assessment","labels":{"zh":"错题诊断与补练","en":"Error diagnosis and practice","ja":"誤答分析・補充演習"},"terms":["错题","misconception","error diagnosis","誤答分析"],"guidance":{"zh":"比较学生步骤与正确思路，定位最早偏离的知识点，区分概念误解、计算疏漏与题意误读。先用提示引导订正，再给同知识点的变式题和答案解析。证据不足时列出可能原因与诊断问题，不仅复述标准答案。","en":"Compare the learner’s steps with valid reasoning to locate the earliest divergence. Distinguish conceptual errors, slips and misread questions. Use hints before correction, then give varied practice and worked answers. When evidence is insufficient, offer hypotheses and diagnostic questions instead of merely repeating the answer key.","ja":"解答過程と正しい筋道を比べ最初のずれを特定し、概念誤解、計算ミス、読違いを分ける。ヒントから訂正へ導き、変形問題と解説を出す。根拠不足なら仮説と診断質問を示し、模範解答の反復だけにしない。"},"examples":{"zh":"针对初学者的Python循环与列表练习，完成“错题诊断与补练”，给出可以直接使用的内容。","en":"Create error diagnosis and practice for Python loop and list practice for beginners. Provide a usable deliverable.","ja":"初心者向けPythonのループとリスト演習について「誤答分析・補充演習」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：学习目标、年龄或水平、知识范围、题型和评分要求。已写在需求中的信息不必重复。","en":"Provide learning goals, age/level, scope, question types and grading criteria. Do not repeat details already in the brief.","ja":"学習目標、年齢・水準、範囲、問題形式、採点条件を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-131","aishort-263"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('localization-ui','published','{"id":"localization-ui","group":"localization","labels":{"zh":"界面文案本地化","en":"UI string localization","ja":"UI文言翻訳"},"terms":["界面翻译","UI strings","JSON","UI翻訳"],"guidance":{"zh":"只翻译显示给用户的字符串，保持JSON键、变量、占位符、转义、链接和结构不变。按按钮、错误、帮助等语境选择自然短句，处理复数、单位和日期格式。输出可解析文件及术语检查报告，列出缺少语境的条目，不擅自改业务含义。","en":"Translate user-visible strings only, preserving JSON keys, variables, placeholders, escapes, links and structure. Use natural concise wording for buttons, errors and help, handling plurals, units and dates. Deliver parseable content and a terminology report, flagging missing context without changing business meaning.","ja":"表示文字列のみ訳し、JSONキー、変数、プレースホルダー、エスケープ、リンク、構造を保つ。ボタン・エラー・ヘルプの文脈で簡潔にし、複数形、単位、日付に配慮。解析可能な内容と用語点検を出し、文脈不足を明記する。"},"examples":{"zh":"针对一个含按钮、报错和帮助文字的三语应用，完成“界面文案本地化”，给出可以直接使用的内容。","en":"Create ui string localization for a trilingual app with buttons, errors and help text. Provide a usable deliverable.","ja":"ボタン・エラー・ヘルプ文を含む3言語アプリについて「UI文言翻訳」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：原文文件、目标地区、术语表、变量与长度限制。已写在需求中的信息不必重复。","en":"Provide source files, target region, glossary, variables and length limits. Do not repeat details already in the brief.","ja":"原文ファイル、対象地域、用語、変数、文字数制限を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-1","aishort-246"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('localization-subtitles','published','{"id":"localization-subtitles","group":"localization","labels":{"zh":"字幕翻译与断句","en":"Subtitle translation and segmentation","ja":"字幕翻訳・改行"},"terms":["字幕","subtitle","SRT","字幕翻訳"],"guidance":{"zh":"保留字幕编号、时间码和说话人信息，按目标语言阅读速度与每行限制翻译断句。不跨段挪动事实，标记无法在时长内自然表达的条目并给短版。输出原格式字幕与待检查清单，没有音视频时不声称验证了口型或听感。","en":"Preserve subtitle indices, timecodes and speaker information while translating for target-language reading speed and line limits. Do not move facts across segments. Flag overcrowded cues and suggest shorter versions. Return the original subtitle format plus checks; without media, claim no lip-sync or audio verification.","ja":"番号、時間コード、話者を保ち、読速と一行制限に合わせ翻訳・改行する。事実を別区間へ移さず、収まらない字幕に短縮案を付ける。元形式と確認一覧を出し、映像音声なしで口形や聴感を確認済みにしない。"},"examples":{"zh":"针对一个含按钮、报错和帮助文字的三语应用，完成“字幕翻译与断句”，给出可以直接使用的内容。","en":"Create subtitle translation and segmentation for a trilingual app with buttons, errors and help text. Provide a usable deliverable.","ja":"ボタン・エラー・ヘルプ文を含む3言語アプリについて「字幕翻訳・改行」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：原文文件、目标地区、术语表、变量与长度限制。已写在需求中的信息不必重复。","en":"Provide source files, target region, glossary, variables and length limits. Do not repeat details already in the brief.","ja":"原文ファイル、対象地域、用語、変数、文字数制限を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-1","aishort-246"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('localization-glossary','published','{"id":"localization-glossary","group":"localization","labels":{"zh":"术语表与一致性检查","en":"Glossary and consistency audit","ja":"用語集・一貫性確認"},"terms":["术语表","glossary","terminology","用語集"],"guidance":{"zh":"从源文抽取专有名词、产品词和高频概念，建立原词、推荐译法、禁用变体、定义和语境例句表。对已有译文查找不一致并给逐项修改理由。保留客户确定的术语，对无法判断的词给候选及确认问题，不用机械同词同译忽略语境。","en":"Extract names, product terms and recurring concepts into a table of source term, preferred translation, disallowed variants, definition and contextual examples. Audit existing translations with specific corrections and rationale. Preserve approved terminology; offer alternatives and questions for ambiguity rather than enforcing context-blind word substitution.","ja":"固有名詞、製品語、頻出概念を原語、推奨訳、避ける形、定義、例文で整理。既訳の不一致に修正理由を付ける。承認済み用語を保ち、曖昧語は候補と質問を示す。文脈を無視した一律置換をしない。"},"examples":{"zh":"针对一个含按钮、报错和帮助文字的三语应用，完成“术语表与一致性检查”，给出可以直接使用的内容。","en":"Create glossary and consistency audit for a trilingual app with buttons, errors and help text. Provide a usable deliverable.","ja":"ボタン・エラー・ヘルプ文を含む3言語アプリについて「用語集・一貫性確認」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：原文文件、目标地区、术语表、变量与长度限制。已写在需求中的信息不必重复。","en":"Provide source files, target region, glossary, variables and length limits. Do not repeat details already in the brief.","ja":"原文ファイル、対象地域、用語、変数、文字数制限を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-1","aishort-246"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('audio-podcast','published','{"id":"audio-podcast","group":"audio","labels":{"zh":"播客单集脚本","en":"Podcast episode script","ja":"ポッドキャスト台本"},"terms":["播客","podcast","ポッドキャスト"],"guidance":{"zh":"设计开场、叙事推进、访谈问题或独白、转场与结尾，标注时间、主持词、资料依据和必要声音提示。问题应针对嘉宾已知经历，不能预先编造其回答。提供节目简介与标题方案，控制总时长并标记需要授权的素材。","en":"Structure an opening, narrative progression, interview questions or monologue, transitions and close with timing, host copy, source basis and sound cues. Tailor questions to known guest experience without inventing answers. Include show notes and titles, check duration and identify material requiring permission.","ja":"導入、展開、質問または独白、つなぎ、締めに時間、進行文、根拠、音の指示を付ける。既知の経験に質問を合わせ、ゲストの答えを作らない。概要と題名を出し、尺と利用許諾が必要な素材を確認する。"},"examples":{"zh":"针对讲解一个真实城市故事的三分钟音频，完成“播客单集脚本”，给出可以直接使用的内容。","en":"Create podcast episode script for a three-minute audio story about a real city. Provide a usable deliverable.","ja":"実在する街の話を伝える3分音声について「ポッドキャスト台本」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：受众、时长、已核实素材、发音要求和目标工具。已写在需求中的信息不必重复。","en":"Provide audience, duration, verified material, pronunciation needs and target tool. Do not repeat details already in the brief.","ja":"聴衆、尺、確認素材、発音条件、対象ツールを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-160","aishort-204","pc-podcast"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('audio-voice','published','{"id":"audio-voice","group":"audio","labels":{"zh":"配音稿与语气标注","en":"Voice-over script and direction","ja":"ナレーション原稿・演出"},"terms":["配音","voice-over","narration","ナレーション"],"guidance":{"zh":"把原文调整为易朗读的句子，明确数字、缩写、多音字和专名读法，并标注停顿、重音、语速与情绪转折。给纯文本版和工具支持时的标记版，保留事实含义。不要冒用真实人物声线，未生成音频时仅交付脚本与参数建议。","en":"Make the text speakable, clarifying numbers, abbreviations and names, with pauses, emphasis, pace and emotional changes. Provide plain text and a markup version only when supported, preserving meaning. Do not impersonate a real person’s voice; if no audio is generated, deliver a script and parameter suggestions only.","ja":"数字、略語、固有名詞の読みを明確にし、間、強調、速度、感情変化付きの話しやすい原稿にする。本文と対応時のみマークアップを出し意味を保つ。実在人物の声をなりすまさず、音声未生成なら原稿と設定案と明記。"},"examples":{"zh":"针对讲解一个真实城市故事的三分钟音频，完成“配音稿与语气标注”，给出可以直接使用的内容。","en":"Create voice-over script and direction for a three-minute audio story about a real city. Provide a usable deliverable.","ja":"実在する街の話を伝える3分音声について「ナレーション原稿・演出」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：受众、时长、已核实素材、发音要求和目标工具。已写在需求中的信息不必重复。","en":"Provide audience, duration, verified material, pronunciation needs and target tool. Do not repeat details already in the brief.","ja":"聴衆、尺、確認素材、発音条件、対象ツールを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-160","aishort-204","pc-podcast"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('audio-sound','published','{"id":"audio-sound","group":"audio","labels":{"zh":"音效与配乐提示词","en":"Sound effects and music briefs","ja":"効果音・音楽プロンプト"},"terms":["音效","sound design","music brief","効果音"],"guidance":{"zh":"按场景建立声音层次：主体声、环境、过渡和音乐，说明时长、节奏、音色、强弱、空间感与循环需求。逐条给可复制的生成提示词和禁用元素，标出对白需留出的空间。避免引用特定受保护旋律，不声称已经完成混音或版权清理。","en":"Define foreground, ambience, transitions and music per scene, specifying duration, rhythm, timbre, dynamics, space and looping. Give copyable generation prompts and exclusions while preserving room for dialogue. Avoid requesting a specific protected melody; do not claim completed mixing or rights clearance.","ja":"主音、環境、移行、音楽の層を場面ごとに設計し、長さ、リズム、音色、強弱、空間、ループを指定。生成用文と除外要素、台詞の余地を示す。特定の保護旋律を求めず、ミックスや権利確認済みとしない。"},"examples":{"zh":"针对讲解一个真实城市故事的三分钟音频，完成“音效与配乐提示词”，给出可以直接使用的内容。","en":"Create sound effects and music briefs for a three-minute audio story about a real city. Provide a usable deliverable.","ja":"実在する街の話を伝える3分音声について「効果音・音楽プロンプト」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：受众、时长、已核实素材、发音要求和目标工具。已写在需求中的信息不必重复。","en":"Provide audience, duration, verified material, pronunciation needs and target tool. Do not repeat details already in the brief.","ja":"聴衆、尺、確認素材、発音条件、対象ツールを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-160","aishort-204","pc-podcast"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('brand-mood','published','{"id":"brand-mood","group":"brand","labels":{"zh":"情绪板与视觉方向","en":"Moodboard and visual direction","ja":"ムードボード・視覚方針"},"terms":["情绪板","moodboard","ムードボード"],"guidance":{"zh":"从品牌目标提炼三种有区别的视觉方向，分别说明颜色、字体性格、构图、材质与参考类型。给每个方向可复制的图片提示词、适用场景和取舍，不用形容词堆砌代替画面描述。无法查看参考图时明确依据的是文字描述。","en":"Develop three distinct visual directions from brand goals, explaining palette, typographic character, composition, materials and reference types. Provide image-generation prompts, use cases and tradeoffs for each. Describe concrete imagery rather than adjective piles; when references are unseen, state that interpretation is based on text.","ja":"目標から異なる3方向を作り、配色、書体の性格、構図、質感、参考種を説明。各方向に画像生成文、用途、取捨を付け、形容詞の羅列でなく具体画面を記述。画像未確認なら文章からの解釈と明示する。"},"examples":{"zh":"针对面向年轻创作者的原创文具品牌，完成“情绪板与视觉方向”，给出可以直接使用的内容。","en":"Create moodboard and visual direction for an original stationery brand for young creators. Provide a usable deliverable.","ja":"若い制作者向けのオリジナル文具ブランドについて「ムードボード・視覚方針」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：品牌定位、使用场景、现有素材、目标受众及限制。已写在需求中的信息不必重复。","en":"Provide positioning, use cases, existing assets, audience and constraints. Do not repeat details already in the brief.","ja":"位置付け、利用場面、既存素材、読者、制約を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-54","aishort-245","aishort-254"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('brand-logo','published','{"id":"brand-logo","group":"brand","labels":{"zh":"标志与图标设计简报","en":"Logo and icon brief","ja":"ロゴ・アイコン制作要項"},"terms":["标志","logo","icon brief","ロゴ"],"guidance":{"zh":"明确标志表达的概念与应用尺寸，给符号结构、字标关系、单色版、深浅背景和小尺寸可辨识性要求。提出不同概念方案及生成提示词，避免模仿现有品牌。区分草案与可交付矢量文件，并列商标检索和人工修整待办。","en":"Define concept and application sizes, then specify symbol structure, wordmark relationship, monochrome use, light/dark backgrounds and small-size legibility. Offer distinct concepts and generation prompts without imitating existing brands. Separate drafts from deliverable vector files and list trademark checks and manual refinement needs.","ja":"概念と利用寸法から記号構造、文字との関係、単色、明暗背景、小サイズ判読性を定める。既存ブランドを模倣しない複数案と生成文を出す。草案と納品ベクターを区別し、商標調査と手修正を待作業として示す。"},"examples":{"zh":"针对面向年轻创作者的原创文具品牌，完成“标志与图标设计简报”，给出可以直接使用的内容。","en":"Create logo and icon brief for an original stationery brand for young creators. Provide a usable deliverable.","ja":"若い制作者向けのオリジナル文具ブランドについて「ロゴ・アイコン制作要項」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：品牌定位、使用场景、现有素材、目标受众及限制。已写在需求中的信息不必重复。","en":"Provide positioning, use cases, existing assets, audience and constraints. Do not repeat details already in the brief.","ja":"位置付け、利用場面、既存素材、読者、制約を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-54","aishort-245","aishort-254"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('brand-guide','published','{"id":"brand-guide","group":"brand","labels":{"zh":"轻量品牌规范","en":"Compact brand guide","ja":"小規模ブランドガイド"},"terms":["品牌规范","brand guide","ブランド規則"],"guidance":{"zh":"将已选方向整理成颜色值、字体替代、间距、图像风格、图标和语气规则，配正确与错误使用例。说明网页、社交图片和演示页的应用差异，给可复用设计变量。缺少正式素材时标明临时建议，不把生成图当作最终品牌资产。","en":"Turn the chosen direction into color values, font fallbacks, spacing, imagery, icons and voice rules with do/don’t examples. Explain web, social-image and slide applications and provide reusable design tokens. Label provisional choices when approved assets are missing; generated images are not automatically final brand assets.","ja":"選定方向を色値、代替書体、余白、画像、アイコン、語調の規則と良否例にまとめる。Web・SNS画像・スライドの差と再利用変数を示す。正式素材なしなら暫定案と明記し、生成画像を最終資産と決めない。"},"examples":{"zh":"针对面向年轻创作者的原创文具品牌，完成“轻量品牌规范”，给出可以直接使用的内容。","en":"Create compact brand guide for an original stationery brand for young creators. Provide a usable deliverable.","ja":"若い制作者向けのオリジナル文具ブランドについて「小規模ブランドガイド」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：品牌定位、使用场景、现有素材、目标受众及限制。已写在需求中的信息不必重复。","en":"Provide positioning, use cases, existing assets, audience and constraints. Do not repeat details already in the brief.","ja":"位置付け、利用場面、既存素材、読者、制約を補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-54","aishort-245","aishort-254"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('production-bible','published','{"id":"production-bible","group":"production","labels":{"zh":"角色与场景设定册","en":"Character and scene bible","ja":"人物・場面設定集"},"terms":["设定册","character bible","场景设定","設定集"],"guidance":{"zh":"建立稳定ID与不可变特征，描述角色比例、服装、道具、材质和场景方位、出入口、光源及时间。区分固定设定和每镜可变状态，提供正侧背视图与场景俯视图提示词。遇到参考冲突先列差异，不为丰富画面随意改变人物或空间。","en":"Assign stable IDs and invariant traits for proportions, clothing, props and materials, plus scene orientation, entrances, lighting and time. Separate fixed design from shot-specific state. Supply front/side/back and overhead-reference prompts. Flag conflicting references instead of changing characters or geography for visual variety.","ja":"固定IDと不変特徴を設け、体型、服、道具、質感、方位、出入口、光源、時刻を記述。固定設定とカット別状態を分離し、三面図と俯瞰図の生成文を出す。参照矛盾を明記し、見映えで人物や空間を変えない。"},"examples":{"zh":"针对同一角色从房间走到街道的短动画，完成“角色与场景设定册”，给出可以直接使用的内容。","en":"Create character and scene bible for a short animation following one character from a room to a street. Provide a usable deliverable.","ja":"同一人物が部屋から通りへ歩く短編アニメについて「人物・場面設定集」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：故事梗概、角色设定、场景图、时长和生成工具。已写在需求中的信息不必重复。","en":"Provide synopsis, character design, scene references, duration and generation tool. Do not repeat details already in the brief.","ja":"あらすじ、人物設定、場面資料、尺、生成ツールを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-16","aishort-274"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('production-shots','published','{"id":"production-shots","group":"production","labels":{"zh":"景别与镜头清单","en":"Shot sizes and shot list","ja":"画角・ショットリスト"},"terms":["镜头清单","shot list","景别","ショットリスト"],"guidance":{"zh":"按叙事目的安排远景交代空间、中景呈现动作、近景表达细节，避免机械轮流使用。每镜给编号、时长、人物位置、视线、动作起止、机位、运动和转场；汇总时长。把静态画面提示词和视频运动提示词分开，并延续场景与角色ID。","en":"Choose wide shots for geography, medium shots for action and close-ups for detail according to narrative purpose, not a mechanical cycle. For each shot, specify ID, duration, positions, eyelines, start/end action, camera, motion and transition. Reconcile runtime and separate still-image prompts from motion prompts using stable character/scene IDs.","ja":"物語の目的で遠景は空間、中景は動作、近景は詳細に使い、機械的交替を避ける。番号、尺、位置、視線、動作前後、カメラ、移動、つなぎを各カットに記す。合計尺を確認し、固定IDで静止画文と動画運動文を分ける。"},"examples":{"zh":"针对同一角色从房间走到街道的短动画，完成“景别与镜头清单”，给出可以直接使用的内容。","en":"Create shot sizes and shot list for a short animation following one character from a room to a street. Provide a usable deliverable.","ja":"同一人物が部屋から通りへ歩く短編アニメについて「画角・ショットリスト」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：故事梗概、角色设定、场景图、时长和生成工具。已写在需求中的信息不必重复。","en":"Provide synopsis, character design, scene references, duration and generation tool. Do not repeat details already in the brief.","ja":"あらすじ、人物設定、場面資料、尺、生成ツールを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-16","aishort-274"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('production-continuity','published','{"id":"production-continuity","group":"production","labels":{"zh":"跨镜头连续性检查","en":"Cross-shot continuity checks","ja":"カット間連続性の点検"},"terms":["连续性","continuity","穿帮","連続性"],"guidance":{"zh":"用镜头对照表检查服装、道具归属、位置、动作、视线、轴线、光线和时间的延续。逐项列问题、证据、影响镜头和最小修正提示词，区分刻意跳切与错误。没有实际帧图时检查文字计划并标注待视觉复核，不能声称已消除穿帮。","en":"Compare shots for costume, prop ownership, position, action, eyelines, axis, lighting and time. List issue, evidence, affected shots and minimal corrective prompts, distinguishing intentional cuts from mistakes. Without frames, review the textual plan and flag visual checks still needed; do not claim continuity defects are eliminated.","ja":"衣装、道具、位置、動作、視線、軸、光、時刻をカット対照表で点検。問題、証拠、対象、最小修正文を示し意図的カットと誤りを分ける。実フレームなしなら文字計画の確認とし、目視待ちを残す。"},"examples":{"zh":"针对同一角色从房间走到街道的短动画，完成“跨镜头连续性检查”，给出可以直接使用的内容。","en":"Create cross-shot continuity checks for a short animation following one character from a room to a street. Provide a usable deliverable.","ja":"同一人物が部屋から通りへ歩く短編アニメについて「カット間連続性の点検」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：故事梗概、角色设定、场景图、时长和生成工具。已写在需求中的信息不必重复。","en":"Provide synopsis, character design, scene references, duration and generation tool. Do not repeat details already in the brief.","ja":"あらすじ、人物設定、場面資料、尺、生成ツールを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-16","aishort-274"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('productivity-review','published','{"id":"productivity-review","group":"productivity","labels":{"zh":"每周复盘与安排","en":"Weekly review and planning","ja":"週次レビュー・計画"},"terms":["每周复盘","weekly review","週次レビュー"],"guidance":{"zh":"对照目标回顾已完成、延期与取消事项，分析时间消耗和阻塞，不做道德化评判。选出下周少量重点，安排可用时段、缓冲和最小行动，并写明确的放弃或顺延清单。计划总量不得超过用户提供的时间。","en":"Review completed, delayed and cancelled tasks against goals, examining time and blockers without moral judgment. Choose a small set of priorities, schedule available time with buffers and minimum actions, and state what will be dropped or deferred. Keep planned effort within the supplied time budget.","ja":"目標に対し完了、延期、中止を見直し、時間と障害を道徳的評価なしで分析。翌週の少数重点、空き枠、余裕、最小行動を決め、行わない項目を明示。作業量は提供された時間を超えない。"},"examples":{"zh":"针对工作与学习并行且每周可用时间有限的安排，完成“每周复盘与安排”，给出可以直接使用的内容。","en":"Create weekly review and planning for balancing work and study with limited weekly time. Provide a usable deliverable.","ja":"仕事と学習を限られた週時間で両立する計画について「週次レビュー・計画」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：现有任务、固定日程、目标、精力限制和工具。已写在需求中的信息不必重复。","en":"Provide current tasks, fixed commitments, goals, energy limits and tools. Do not repeat details already in the brief.","ja":"現タスク、固定予定、目標、体力制約、ツールを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-70","aishort-215","aishort-279"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('productivity-checklist','published','{"id":"productivity-checklist","group":"productivity","labels":{"zh":"可复用检查清单","en":"Reusable checklists","ja":"再利用チェックリスト"},"terms":["检查清单","checklist","チェックリスト"],"guidance":{"zh":"把重复任务拆成准备、执行、核对与收尾，每项写成可观察的单一动作。加入触发条件、异常分支和完成证据，标明必做与可选；删除无法勾选的空泛要求。提供适合打印或粘贴到任务软件的版本。","en":"Break a recurring task into preparation, execution, verification and closure, with one observable action per item. Add triggers, exception branches and completion evidence; distinguish required from optional steps and remove vague uncheckable advice. Provide a printable or task-app-ready version.","ja":"反復作業を準備、実行、確認、終了に分け、一項目一つの観察可能な行動にする。条件、例外、完了証拠、必須・任意を付け、チェック不能な抽象助言を除く。印刷やタスクアプリに使える形式を出す。"},"examples":{"zh":"针对工作与学习并行且每周可用时间有限的安排，完成“可复用检查清单”，给出可以直接使用的内容。","en":"Create reusable checklists for balancing work and study with limited weekly time. Provide a usable deliverable.","ja":"仕事と学習を限られた週時間で両立する計画について「再利用チェックリスト」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：现有任务、固定日程、目标、精力限制和工具。已写在需求中的信息不必重复。","en":"Provide current tasks, fixed commitments, goals, energy limits and tools. Do not repeat details already in the brief.","ja":"現タスク、固定予定、目標、体力制約、ツールを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-70","aishort-215","aishort-279"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('productivity-knowledge','published','{"id":"productivity-knowledge","group":"productivity","labels":{"zh":"个人知识库整理","en":"Personal knowledge organization","ja":"個人ナレッジ整理"},"terms":["知识库整理","knowledge organization","笔记分类","ノート整理"],"guidance":{"zh":"按检索和复用目的设计少量稳定分类、标签和命名规则，给示例笔记的归类、摘要、关联与后续行动。区分原始资料、个人理解和待核实信息，设置来源字段和去重规则。先给迁移映射与预览，不默认删除原文件或重排全部资料。","en":"Design a small stable set of categories, tags and naming rules around retrieval and reuse. Classify sample notes with summaries, links and follow-up actions. Separate source material, interpretation and unverified information, including provenance and deduplication rules. Provide migration mapping and preview before any file changes.","ja":"検索・再利用を軸に少数の安定分類、タグ、命名規則を作り、例ノートの分類、要約、関連、次の行動を示す。原資料、解釈、未確認を分け出典と重複規則を付ける。変更前に移行対応とプレビューを出し原本を削除しない。"},"examples":{"zh":"针对工作与学习并行且每周可用时间有限的安排，完成“个人知识库整理”，给出可以直接使用的内容。","en":"Create personal knowledge organization for balancing work and study with limited weekly time. Provide a usable deliverable.","ja":"仕事と学習を限られた週時間で両立する計画について「個人ナレッジ整理」を、使える具体的な内容で作成してください。"},"questions":{"zh":"请补充：现有任务、固定日程、目标、精力限制和工具。已写在需求中的信息不必重复。","en":"Provide current tasks, fixed commitments, goals, energy limits and tools. Do not repeat details already in the brief.","ja":"現タスク、固定予定、目標、体力制約、ツールを補足してください。要望に記載済みなら繰り返し不要です。"},"sourceReferences":["aishort-70","aishort-215","aishort-279"],"editorialStatus":"reviewed-original-adaptation","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('operations-sop','published','{"id":"operations-sop","group":"operations","labels":{"zh":"标准操作流程","en":"Standard operating procedure","ja":"標準作業手順"},"terms":["SOP","标准流程","operating procedure","標準手順"],"guidance":{"zh":"按触发、输入检查、操作、异常和收尾写编号步骤，每步给责任角色、系统位置和完成证据。把判断条件写清，附示例记录和版本信息，不只写加强管理等口号。","en":"Write numbered steps for triggers, input checks, actions, exceptions and closure. Give role, system location and completion evidence per step. Specify decision criteria, example records and version data rather than management slogans.","ja":"開始、入力確認、操作、例外、終了を番号化し、担当、画面位置、完了証拠を付ける。判断条件、記録例、版を示し、抽象的な管理強化で済ませない。"},"examples":{"zh":"针对一个需要减少订单漏处理的小团队，完成“标准操作流程”，按实际条件交付可用内容。","en":"Create standard operating procedure for a small team trying to prevent missed orders. Use the stated constraints and deliver usable content.","ja":"注文の処理漏れを減らしたい小チームについて「標準作業手順」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：现有步骤、角色、输入输出、异常样例和时效要求。已提供的信息不必重复。","en":"Provide current steps, roles, inputs/outputs, exception samples and deadlines. Do not repeat information already supplied.","ja":"現手順、役割、入出力、例外例、時間条件を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('operations-bottleneck','published','{"id":"operations-bottleneck","group":"operations","labels":{"zh":"流程瓶颈与改进实验","en":"Process bottleneck experiments","ja":"業務ボトルネックの改善実験"},"terms":["流程优化","process improvement","bottleneck","業務改善"],"guidance":{"zh":"画出现状步骤与等待，依据提供的工时和返工记录定位瓶颈。提出小范围改进、负责人、试验期限和对照指标，保留未验证假设；不把减少步骤自动等同降低总成本。","en":"Map current steps and waits using supplied effort and rework records. Propose a small improvement, owner, trial period and comparison metrics. Retain untested assumptions; fewer steps do not automatically mean lower total cost.","ja":"現工程と待ち時間を工数・手戻り記録で整理。小規模変更、担当、期間、比較指標を提案し仮説を明示。工程減少を総費用低下と決めつけない。"},"examples":{"zh":"针对一个需要减少订单漏处理的小团队，完成“流程瓶颈与改进实验”，按实际条件交付可用内容。","en":"Create process bottleneck experiments for a small team trying to prevent missed orders. Use the stated constraints and deliver usable content.","ja":"注文の処理漏れを減らしたい小チームについて「業務ボトルネックの改善実験」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：现有步骤、角色、输入输出、异常样例和时效要求。已提供的信息不必重复。","en":"Provide current steps, roles, inputs/outputs, exception samples and deadlines. Do not repeat information already supplied.","ja":"現手順、役割、入出力、例外例、時間条件を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('operations-stock','published','{"id":"operations-stock","group":"operations","labels":{"zh":"库存台账与补货规则","en":"Inventory and replenishment rules","ja":"在庫台帳・補充規則"},"terms":["库存","inventory","reorder","在庫管理"],"guidance":{"zh":"定义SKU、单位、入出库、可用量和预留量字段，给台账示例与核对公式。按已知需求和交期推导补货提醒，注明假设、缺货与滞销处理；没有销量数据不编造最优库存数。","en":"Define SKU, units, movements, available and reserved stock. Provide ledger examples and reconciliation formulas. Derive replenishment alerts from known demand and lead time, with assumptions and shortage/overstock handling. Do not invent optimal stock without sales data.","ja":"SKU、単位、入出庫、使用可能量、引当を定め台帳例と照合式を出す。既知需要と納期から補充を決め、仮定、欠品、余剰を扱う。売上なしで最適量を作らない。"},"examples":{"zh":"针对一个需要减少订单漏处理的小团队，完成“库存台账与补货规则”，按实际条件交付可用内容。","en":"Create inventory and replenishment rules for a small team trying to prevent missed orders. Use the stated constraints and deliver usable content.","ja":"注文の処理漏れを減らしたい小チームについて「在庫台帳・補充規則」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：现有步骤、角色、输入输出、异常样例和时效要求。已提供的信息不必重复。","en":"Provide current steps, roles, inputs/outputs, exception samples and deadlines. Do not repeat information already supplied.","ja":"現手順、役割、入出力、例外例、時間条件を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('procurement-rfq','published','{"id":"procurement-rfq","group":"procurement","labels":{"zh":"采购需求与询价函","en":"Requirements and RFQ","ja":"調達要件・見積依頼"},"terms":["询价","RFQ","采购需求","見積依頼"],"guidance":{"zh":"把用途转为可比较的规格、数量、交货、安装和售后问题，写可直接发送的询价函。要求分项报价、有效期与排除项，未知型号留待确认，不暗示已经选定供应商。","en":"Convert use needs into comparable specifications, quantity, delivery, installation and support questions. Draft an RFQ requesting itemized prices, validity and exclusions. Leave unknown models pending and do not imply a supplier has been selected.","ja":"用途を比較可能な仕様、数量、配送、設置、保守の質問にし、内訳、有効期限、除外を求める依頼文を作る。不明型番は保留し選定済みと示唆しない。"},"examples":{"zh":"针对为小型办公室采购十套桌椅，完成“采购需求与询价函”，按实际条件交付可用内容。","en":"Create requirements and rfq for buying ten desk-and-chair sets for a small office. Use the stated constraints and deliver usable content.","ja":"小規模事務所用の机と椅子10セットの調達について「調達要件・見積依頼」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：规格、数量、预算、交期、已有报价和验收要求。已提供的信息不必重复。","en":"Provide specifications, quantity, budget, deadline, quotes and acceptance requirements. Do not repeat information already supplied.","ja":"仕様、数量、予算、納期、見積、受入条件を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('procurement-compare','published','{"id":"procurement-compare","group":"procurement","labels":{"zh":"供应商报价对比","en":"Supplier quote comparison","ja":"仕入先見積比較"},"terms":["报价对比","quote comparison","vendor evaluation","見積比較"],"guidance":{"zh":"统一含税口径、货币、运费和服务范围，给总拥有成本明细、权重及评分依据。缺项单列并给澄清问题，区分最低价格与需求适配，不为缺失报价编数字或伪造评级。","en":"Normalize tax basis, currency, shipping and scope. Compare total ownership costs, weights and evidence. Flag missing items with clarification questions, distinguishing lowest price from fit. Do not invent prices or supplier ratings.","ja":"税、通貨、送料、範囲を統一し総保有費、重み、根拠を比較。不足と確認質問を分け、最安と適合を区別し、価格や評価を捏造しない。"},"examples":{"zh":"针对为小型办公室采购十套桌椅，完成“供应商报价对比”，按实际条件交付可用内容。","en":"Create supplier quote comparison for buying ten desk-and-chair sets for a small office. Use the stated constraints and deliver usable content.","ja":"小規模事務所用の机と椅子10セットの調達について「仕入先見積比較」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：规格、数量、预算、交期、已有报价和验收要求。已提供的信息不必重复。","en":"Provide specifications, quantity, budget, deadline, quotes and acceptance requirements. Do not repeat information already supplied.","ja":"仕様、数量、予算、納期、見積、受入条件を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('procurement-acceptance','published','{"id":"procurement-acceptance","group":"procurement","labels":{"zh":"到货验收与差异沟通","en":"Delivery acceptance and discrepancies","ja":"納品確認・相違連絡"},"terms":["到货验收","delivery acceptance","采购验收","検収"],"guidance":{"zh":"列数量、规格、外观、功能和附件检查及证据记录，区分通过、待补和不符。根据实际差异写中立沟通邮件与解决期限建议，不能声称验收已完成或代用户接受不符品。","en":"List quantity, specification, appearance, function and accessory checks with evidence. Mark accepted, incomplete and nonconforming items. Draft neutral discrepancy communication and proposed deadlines without claiming checks occurred or accepting defects for the user.","ja":"数量、仕様、外観、機能、付属品と証拠を確認表にし、合格、不足、不適合を分ける。相違連絡と期限案を作り、実施済みや不適合受入れを装わない。"},"examples":{"zh":"针对为小型办公室采购十套桌椅，完成“到货验收与差异沟通”，按实际条件交付可用内容。","en":"Create delivery acceptance and discrepancies for buying ten desk-and-chair sets for a small office. Use the stated constraints and deliver usable content.","ja":"小規模事務所用の机と椅子10セットの調達について「納品確認・相違連絡」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：规格、数量、预算、交期、已有报价和验收要求。已提供的信息不必重复。","en":"Provide specifications, quantity, budget, deadline, quotes and acceptance requirements. Do not repeat information already supplied.","ja":"仕様、数量、予算、納期、見積、受入条件を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('accessibility-plain','published','{"id":"accessibility-plain","group":"accessibility","labels":{"zh":"复杂说明简明化","en":"Plain-language rewrite","ja":"難しい説明の平易化"},"terms":["易读","plain language","简明表达","やさしい説明"],"guidance":{"zh":"保留条件、例外与操作顺序，用熟悉词汇、短句和明确主语重写全文。专业词首次解释，给真实可理解的例子和下一步；附含义核对表，不用删掉关键限制换取简单。","en":"Rewrite with familiar words, short sentences and explicit subjects while preserving conditions, exceptions and sequence. Explain jargon, add concrete examples and next actions. Include a meaning check; simplicity must not erase essential limits.","ja":"条件、例外、順序を保ち、身近な語、短文、明確な主語で全文を直す。専門語説明、具体例、次の行動、意味照合を付け、簡単さのために重要制約を消さない。"},"examples":{"zh":"针对一份需要让不同阅读能力用户理解的服务说明，完成“复杂说明简明化”，按实际条件交付可用内容。","en":"Create plain-language rewrite for service instructions for readers with varied reading abilities. Use the stated constraints and deliver usable content.","ja":"読解力の異なる利用者向けのサービス説明について「難しい説明の平易化」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：原文、读者需求、使用渠道、必须保留的信息和辅助技术场景。已提供的信息不必重复。","en":"Provide source, reader needs, channel, required details and assistive-technology context. Do not repeat information already supplied.","ja":"原文、読者の必要、媒体、必須情報、支援技術の利用場面を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('accessibility-alt','published','{"id":"accessibility-alt","group":"accessibility","labels":{"zh":"图片替代文本","en":"Image alternative text","ja":"画像の代替テキスト"},"terms":["替代文本","alt text","image description","代替テキスト"],"guidance":{"zh":"依据图片在页面中的用途写替代文本：信息图保留关键关系，按钮描述动作，纯装饰说明可留空。复杂图另给长描述，不能猜测未看到的图像细节或人物身份。","en":"Write alt text according to purpose: key relationships for informational images, actions for controls and empty text for decoration where appropriate. Add long descriptions for complex diagrams. Do not guess unseen details or identities.","ja":"ページ内の役割に合わせ、情報図は主要関係、操作画像は動作、装飾は適切に空欄とする。複雑図には詳細説明を添え、見えない詳細や人物名を推測しない。"},"examples":{"zh":"针对一份需要让不同阅读能力用户理解的服务说明，完成“图片替代文本”，按实际条件交付可用内容。","en":"Create image alternative text for service instructions for readers with varied reading abilities. Use the stated constraints and deliver usable content.","ja":"読解力の異なる利用者向けのサービス説明について「画像の代替テキスト」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：原文、读者需求、使用渠道、必须保留的信息和辅助技术场景。已提供的信息不必重复。","en":"Provide source, reader needs, channel, required details and assistive-technology context. Do not repeat information already supplied.","ja":"原文、読者の必要、媒体、必須情報、支援技術の利用場面を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('accessibility-instructions','published','{"id":"accessibility-instructions","group":"accessibility","labels":{"zh":"无障碍操作指引","en":"Accessible task instructions","ja":"利用しやすい操作案内"},"terms":["无障碍说明","accessible instructions","screen reader","操作案内"],"guidance":{"zh":"按真实界面标签写前提、步骤、结果和失败恢复，不只依赖颜色、方位或鼠标动作。提供键盘或替代路径的待验证项，说明辅助技术测试方法；未实测不宣称符合某级标准。","en":"Use actual UI labels for prerequisites, steps, results and recovery. Do not rely solely on color, position or mouse actions. Identify keyboard alternatives and assistive-technology checks, marking untested paths; do not claim standards conformance without testing.","ja":"実ラベルで前提、手順、結果、復旧を示し、色、位置、マウスだけに頼らない。キーボード代替と支援技術の確認を記し、未検証で規格適合を宣言しない。"},"examples":{"zh":"针对一份需要让不同阅读能力用户理解的服务说明，完成“无障碍操作指引”，按实际条件交付可用内容。","en":"Create accessible task instructions for service instructions for readers with varied reading abilities. Use the stated constraints and deliver usable content.","ja":"読解力の異なる利用者向けのサービス説明について「利用しやすい操作案内」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：原文、读者需求、使用渠道、必须保留的信息和辅助技术场景。已提供的信息不必重复。","en":"Provide source, reader needs, channel, required details and assistive-technology context. Do not repeat information already supplied.","ja":"原文、読者の必要、媒体、必須情報、支援技術の利用場面を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('travel-itinerary','published','{"id":"travel-itinerary","group":"travel","labels":{"zh":"按约束排日程","en":"Constraint-based itinerary","ja":"条件に合う日程"},"terms":["旅行日程","itinerary","travel plan","旅行日程"],"guidance":{"zh":"按地理位置、交通、休息和固定预订安排每日路线，给时间段、停留、转场与备选。营业时间、票价和交通须当前核实，不能把估算当预约；控制步行量并保留弹性。","en":"Plan daily routes around geography, transport, rest and fixed bookings. Include time blocks, visits, transfers and alternatives. Verify current hours, fares and transport; estimates are not reservations. Respect walking limits and allow flexibility.","ja":"位置、移動、休憩、予約で日程を組み、時間枠、滞在、移動、代案を示す。営業時間、料金、交通は最新確認し、推定を予約としない。歩行制限と余裕を守る。"},"examples":{"zh":"针对一次带长辈同行、每天步行量有限的三日城市游，完成“按约束排日程”，按实际条件交付可用内容。","en":"Create constraint-based itinerary for a three-day city trip with an older relative and limited daily walking. Use the stated constraints and deliver usable content.","ja":"歩行量を抑えたい年長家族との3日間の都市旅行について「条件に合う日程」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：目的地、日期、同行者需求、预算、住宿位置和已确认预订。已提供的信息不必重复。","en":"Provide destination, dates, group needs, budget, lodging and confirmed bookings. Do not repeat information already supplied.","ja":"行先、日程、同行者条件、予算、宿泊地、確定予約を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('travel-packing','published','{"id":"travel-packing","group":"travel","labels":{"zh":"行李与出发检查","en":"Packing and departure checklist","ja":"荷物・出発確認"},"terms":["行李","packing list","出发检查","持ち物"],"guidance":{"zh":"按天气、活动、洗衣条件和行李额度列数量与用途，区分随身、托运和临行事项。标明需向承运方核实的限制，避免重复携带；根据已知需求定制，不默认购买所有物品。","en":"List quantities and purposes based on weather, activities, laundry and baggage allowance. Separate carry-on, checked items and departure tasks. Flag carrier-specific restrictions and remove duplication; tailor to known needs rather than requiring purchases.","ja":"天候、活動、洗濯、荷物枠で数量と用途を決め、手荷物、預け、直前作業を分ける。運送者への確認事項と重複を示し、全品購入を前提にしない。"},"examples":{"zh":"针对一次带长辈同行、每天步行量有限的三日城市游，完成“行李与出发检查”，按实际条件交付可用内容。","en":"Create packing and departure checklist for a three-day city trip with an older relative and limited daily walking. Use the stated constraints and deliver usable content.","ja":"歩行量を抑えたい年長家族との3日間の都市旅行について「荷物・出発確認」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：目的地、日期、同行者需求、预算、住宿位置和已确认预订。已提供的信息不必重复。","en":"Provide destination, dates, group needs, budget, lodging and confirmed bookings. Do not repeat information already supplied.","ja":"行先、日程、同行者条件、予算、宿泊地、確定予約を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('travel-access','published','{"id":"travel-access","group":"travel","labels":{"zh":"低步行与无障碍路线核查","en":"Low-walking route checks","ja":"歩行を抑える経路確認"},"terms":["无障碍旅行","step-free","accessible travel","段差なし"],"guidance":{"zh":"把台阶、电梯、座位、厕所和换乘距离列为逐段确认项，区分官方已确认与待联系信息。给询问场馆的具体问题和雨天备选，不从地图距离推断无障碍，也不保证未核实路线可通行。","en":"Check steps, lifts, seating, toilets and transfer distances per segment. Separate official confirmations from pending enquiries. Provide venue questions and wet-weather alternatives. Map distance alone does not prove accessibility; do not guarantee unverified routes.","ja":"区間ごとに段差、昇降機、席、トイレ、乗換距離を確認。公式確認と照会待ちを分け、施設質問と雨天案を出す。地図距離だけで利用可能と保証しない。"},"examples":{"zh":"针对一次带长辈同行、每天步行量有限的三日城市游，完成“低步行与无障碍路线核查”，按实际条件交付可用内容。","en":"Create low-walking route checks for a three-day city trip with an older relative and limited daily walking. Use the stated constraints and deliver usable content.","ja":"歩行量を抑えたい年長家族との3日間の都市旅行について「歩行を抑える経路確認」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：目的地、日期、同行者需求、预算、住宿位置和已确认预订。已提供的信息不必重复。","en":"Provide destination, dates, group needs, budget, lodging and confirmed bookings. Do not repeat information already supplied.","ja":"行先、日程、同行者条件、予算、宿泊地、確定予約を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('cooking-recipe','published','{"id":"cooking-recipe","group":"cooking","labels":{"zh":"按现有食材写食谱","en":"Recipe from available ingredients","ja":"手元の食材で作るレシピ"},"terms":["食谱","recipe","ingredients","レシピ"],"guidance":{"zh":"给准确用量、准备步骤、烹饪顺序和可观察的熟度提示，按厨具和人数调整。列缺料替代及味道影响，计入准备时间；不推荐用户过敏食材，不把普通食谱写成治疗方案。","en":"Provide quantities, preparation, cooking order and observable doneness cues adjusted to equipment and servings. Include substitutions and flavor effects, counting prep time. Respect allergies and do not present an ordinary recipe as treatment.","ja":"分量、下準備、順序、火通りの目安を器具と人数に合わせる。代替と味の変化、準備時間を示し、アレルギー食材を避け、治療目的としない。"},"examples":{"zh":"针对两人份、每晚只有30分钟准备时间的家常晚餐，完成“按现有食材写食谱”，按实际条件交付可用内容。","en":"Create recipe from available ingredients for home dinners for two with 30 minutes of preparation each evening. Use the stated constraints and deliver usable content.","ja":"毎晩30分で準備する2人分の家庭夕食について「手元の食材で作るレシピ」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：现有食材、过敏或忌口、厨具、人数、时间和预算。已提供的信息不必重复。","en":"Provide available ingredients, allergies/restrictions, equipment, servings, time and budget. Do not repeat information already supplied.","ja":"食材、アレルギー・避ける物、器具、人数、時間、予算を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('cooking-menu','published','{"id":"cooking-menu","group":"cooking","labels":{"zh":"一周菜单与购物清单","en":"Weekly menu and shopping list","ja":"週間献立・買物表"},"terms":["一周菜单","meal plan","shopping list","献立"],"guidance":{"zh":"按用户偏好和可用时间安排菜品，复用食材但避免每天完全相同。汇总采购量并扣除库存，标明预算估算和先后使用顺序；未知价格不编精确总价。","en":"Plan meals around preferences and time, reusing ingredients without identical daily meals. Aggregate quantities minus existing stock, noting estimated cost and use order. Do not invent exact totals for unknown prices.","ja":"好みと時間で献立を組み、食材を共用しつつ同じ料理の連続を避ける。在庫を引いた買物量、概算、使用順を出し、不明価格から精密総額を作らない。"},"examples":{"zh":"针对两人份、每晚只有30分钟准备时间的家常晚餐，完成“一周菜单与购物清单”，按实际条件交付可用内容。","en":"Create weekly menu and shopping list for home dinners for two with 30 minutes of preparation each evening. Use the stated constraints and deliver usable content.","ja":"毎晩30分で準備する2人分の家庭夕食について「週間献立・買物表」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：现有食材、过敏或忌口、厨具、人数、时间和预算。已提供的信息不必重复。","en":"Provide available ingredients, allergies/restrictions, equipment, servings, time and budget. Do not repeat information already supplied.","ja":"食材、アレルギー・避ける物、器具、人数、時間、予算を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('cooking-timing','published','{"id":"cooking-timing","group":"cooking","labels":{"zh":"多道菜并行时间表","en":"Multi-dish cooking schedule","ja":"複数料理の進行表"},"terms":["做饭顺序","cooking timeline","备菜","調理段取り"],"guidance":{"zh":"从目标上桌时间倒排清洗、切配、加热与装盘，明确可并行和必须顺序的步骤。考虑灶眼、锅具和操作者数量，给延迟时的调整；生熟处理分开，不用不可靠的保存建议补救超时。","en":"Work backward from serving time through washing, chopping, heating and plating. Mark parallel versus sequential steps around burners, cookware and cooks. Add delay adjustments and keep raw/cooked handling separate without relying on dubious storage shortcuts.","ja":"配膳から逆算し洗浄、切出し、加熱、盛付けを配置。火口、器具、人数で並行と順序を分ける。遅延調整と生・加熱済みの分離を示し、無理な保存で補わない。"},"examples":{"zh":"针对两人份、每晚只有30分钟准备时间的家常晚餐，完成“多道菜并行时间表”，按实际条件交付可用内容。","en":"Create multi-dish cooking schedule for home dinners for two with 30 minutes of preparation each evening. Use the stated constraints and deliver usable content.","ja":"毎晩30分で準備する2人分の家庭夕食について「複数料理の進行表」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：现有食材、过敏或忌口、厨具、人数、时间和预算。已提供的信息不必重复。","en":"Provide available ingredients, allergies/restrictions, equipment, servings, time and budget. Do not repeat information already supplied.","ja":"食材、アレルギー・避ける物、器具、人数、時間、予算を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('home-organize','published','{"id":"home-organize","group":"home","labels":{"zh":"小空间收纳规划","en":"Small-space organization","ja":"小空間の収納計画"},"terms":["收纳","home organization","storage","収納"],"guidance":{"zh":"按活动和使用频率划分位置，给保留、移位与待决定清单，标注尺寸和通行限制。先利用现有容器，设计标签与归位规则；不擅自决定丢弃纪念物或购买新家具。","en":"Zone items by activity and frequency. List keep, relocate and undecided items with dimensions and circulation limits. Reuse containers and define labels/return rules. Do not decide to discard sentimental objects or buy furniture for the user.","ja":"活動と頻度で配置し、保持、移動、保留を寸法と動線付きで整理。既存容器、表示、戻し方を使い、思い出の品の廃棄や家具購入を勝手に決めない。"},"examples":{"zh":"针对一个有工作桌、储物柜和阳台盆栽的小公寓，完成“小空间收纳规划”，按实际条件交付可用内容。","en":"Create small-space organization for a small apartment with a desk, storage and balcony plants. Use the stated constraints and deliver usable content.","ja":"机、収納、ベランダの鉢植えがある小さな部屋について「小空間の収納計画」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：空间尺寸、物品数量、使用频率、时间预算和相关照片。已提供的信息不必重复。","en":"Provide dimensions, item counts, use frequency, time budget and photos. Do not repeat information already supplied.","ja":"寸法、物量、使用頻度、時間枠、写真を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('home-maintenance','published','{"id":"home-maintenance","group":"home","labels":{"zh":"家务轮值与维护记录","en":"Chore rotation and maintenance log","ja":"家事分担・手入れ記録"},"terms":["家务","chore schedule","maintenance log","家事"],"guidance":{"zh":"按房间、频率、耗时和参与者排任务，明确完成标准、替换规则及延期处理。给可打印周表和维护记录字段，总量符合可用时间；涉及专业维修仅记录现象和联系事项，不给危险拆修步骤。","en":"Schedule chores by room, frequency, effort and participants, with completion criteria, swaps and deferrals. Provide a printable week and maintenance fields within available time. For professional repairs, record symptoms and contacts rather than hazardous dismantling instructions.","ja":"部屋、頻度、工数、人で家事を割当て、完了基準、交代、延期を定める。週表と保守記録を時間内に収め、専門修理は現象と連絡事項を記す。"},"examples":{"zh":"针对一个有工作桌、储物柜和阳台盆栽的小公寓，完成“家务轮值与维护记录”，按实际条件交付可用内容。","en":"Create chore rotation and maintenance log for a small apartment with a desk, storage and balcony plants. Use the stated constraints and deliver usable content.","ja":"机、収納、ベランダの鉢植えがある小さな部屋について「家事分担・手入れ記録」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：空间尺寸、物品数量、使用频率、时间预算和相关照片。已提供的信息不必重复。","en":"Provide dimensions, item counts, use frequency, time budget and photos. Do not repeat information already supplied.","ja":"寸法、物量、使用頻度、時間枠、写真を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('home-plants','published','{"id":"home-plants","group":"home","labels":{"zh":"盆栽观察与养护记录","en":"Houseplant observation log","ja":"鉢植え観察・管理記録"},"terms":["盆栽","plant journal","gardening","植物記録"],"guidance":{"zh":"建立植物名称待确认、光照、浇水、盆土和叶片变化记录，按观察给待核查原因与下一步信息。区分干湿状态与固定日历浇水，未知品种不武断诊断，也不随意给药剂配比。","en":"Log provisional plant identity, light, watering, substrate and leaf changes. Use observations to list hypotheses and missing information. Distinguish actual moisture from calendar watering; do not diagnose unknown species confidently or invent chemical dosages.","ja":"仮の植物名、光、水やり、土、葉変化を記録し、観察から仮説と追加情報を出す。実際の湿りと暦を分け、不明種を断定診断せず薬剤量を作らない。"},"examples":{"zh":"针对一个有工作桌、储物柜和阳台盆栽的小公寓，完成“盆栽观察与养护记录”，按实际条件交付可用内容。","en":"Create houseplant observation log for a small apartment with a desk, storage and balcony plants. Use the stated constraints and deliver usable content.","ja":"机、収納、ベランダの鉢植えがある小さな部屋について「鉢植え観察・管理記録」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：空间尺寸、物品数量、使用频率、时间预算和相关照片。已提供的信息不必重复。","en":"Provide dimensions, item counts, use frequency, time budget and photos. Do not repeat information already supplied.","ja":"寸法、物量、使用頻度、時間枠、写真を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('research-methods-question','published','{"id":"research-methods-question","group":"research-methods","labels":{"zh":"研究问题与变量","en":"Research questions and variables","ja":"研究課題・変数"},"terms":["研究问题","research question","variables","研究課題"],"guidance":{"zh":"把宽泛题目缩成可回答的问题，定义核心概念、观察单位、变量及操作化方式。给主问题、子问题、可证伪预期和可行性判断，区分描述、关联和因果目标，不把预期写成结果。","en":"Narrow the topic to answerable questions. Define concepts, units, variables and operational measures. Supply main/subquestions, falsifiable expectations and feasibility checks. Separate descriptive, associative and causal aims; expectations are not findings.","ja":"題目を答えられる問いに絞り、概念、観察単位、変数、測定を定義。主・副問い、反証可能な予想、実現性を示し、記述・関連・因果を分け、予想を結果としない。"},"examples":{"zh":"针对研究远程协作工具如何影响团队沟通的课程论文，完成“研究问题与变量”，按实际条件交付可用内容。","en":"Create research questions and variables for a course paper on how remote collaboration tools affect team communication. Use the stated constraints and deliver usable content.","ja":"遠隔協働ツールとチーム連絡を扱う授業論文について「研究課題・変数」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：研究问题、可用数据、对象范围、时间、方法基础和要求。已提供的信息不必重复。","en":"Provide question, available data, population, timeline, method experience and requirements. Do not repeat information already supplied.","ja":"研究疑問、利用データ、対象、期間、方法経験、条件を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('research-methods-protocol','published','{"id":"research-methods-protocol","group":"research-methods","labels":{"zh":"研究方案与流程","en":"Research protocol","ja":"研究計画・手順"},"terms":["研究方案","protocol","sampling","研究計画"],"guidance":{"zh":"根据问题选择设计与抽样，交付纳入排除规则、收集步骤、数据字典和分析计划。说明偏差、缺失处理、伦理与审批需求，列时间表；不捏造伦理批准或假设所有人都能被招募。","en":"Choose design and sampling around the question. Deliver eligibility rules, collection steps, data dictionary and analysis plan, including bias, missingness, ethics and approvals. Add a timeline without inventing approval or guaranteed recruitment.","ja":"問いに合う設計と抽出を選び、適格基準、収集、辞書、分析を作る。偏り、欠損、倫理、承認、日程を示し、承認取得や募集成功を装わない。"},"examples":{"zh":"针对研究远程协作工具如何影响团队沟通的课程论文，完成“研究方案与流程”，按实际条件交付可用内容。","en":"Create research protocol for a course paper on how remote collaboration tools affect team communication. Use the stated constraints and deliver usable content.","ja":"遠隔協働ツールとチーム連絡を扱う授業論文について「研究計画・手順」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：研究问题、可用数据、对象范围、时间、方法基础和要求。已提供的信息不必重复。","en":"Provide question, available data, population, timeline, method experience and requirements. Do not repeat information already supplied.","ja":"研究疑問、利用データ、対象、期間、方法経験、条件を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('research-methods-methods','published','{"id":"research-methods-methods","group":"research-methods","labels":{"zh":"方法章节与可复现清单","en":"Methods section and reproducibility","ja":"方法章・再現性確認"},"terms":["方法章节","methods section","reproducibility","方法章"],"guidance":{"zh":"仅据实际已做步骤写方法章节，包含样本、工具版本、处理规则和分析参数。把未实施计划与完成工作分开，给复现材料清单及待补字段，不编造实验、样本量或软件运行记录。","en":"Write methods only from work actually performed: sample, tool versions, processing rules and analysis parameters. Separate planned from completed steps. Provide reproducibility materials and missing fields without inventing experiments, sample sizes or execution logs.","ja":"実施済みの手順から標本、ツール版、処理、分析条件を書く。計画と完了を分け、再現資料と不足欄を示す。実験、人数、実行記録を作らない。"},"examples":{"zh":"针对研究远程协作工具如何影响团队沟通的课程论文，完成“方法章节与可复现清单”，按实际条件交付可用内容。","en":"Create methods section and reproducibility for a course paper on how remote collaboration tools affect team communication. Use the stated constraints and deliver usable content.","ja":"遠隔協働ツールとチーム連絡を扱う授業論文について「方法章・再現性確認」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：研究问题、可用数据、对象范围、时间、方法基础和要求。已提供的信息不必重复。","en":"Provide question, available data, population, timeline, method experience and requirements. Do not repeat information already supplied.","ja":"研究疑問、利用データ、対象、期間、方法経験、条件を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('surveys-questionnaire','published','{"id":"surveys-questionnaire","group":"surveys","labels":{"zh":"问卷设计与预测试","en":"Questionnaire and pilot test","ja":"質問票・予備調査"},"terms":["问卷","survey design","questionnaire","質問票"],"guidance":{"zh":"按测量目标设计中立单义问题、选项和跳转规则，标明必答与可跳过。给量表方向、编码表和预测试检查，避免双重问题、暗示性措辞和互相重叠的选项。","en":"Map neutral, single-focus questions to measurement goals, with options, branching and skip choices. Provide scale direction, coding and pilot checks. Avoid double-barreled questions, leading wording and overlapping answer ranges.","ja":"測定目的に対応する中立な単一質問、選択肢、分岐、任意回答を作る。尺度方向、符号化、予備確認を示し、二重質問、誘導、選択肢重複を避ける。"},"examples":{"zh":"针对了解学生使用学习应用时困难的小型调研，完成“问卷设计与预测试”，按实际条件交付可用内容。","en":"Create questionnaire and pilot test for a small study of difficulties students face with a learning app. Use the stated constraints and deliver usable content.","ja":"学習アプリで学生が困る点を調べる小規模調査について「質問票・予備調査」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：调研目标、对象、样本来源、问题数量、已有回答和隐私要求。已提供的信息不必重复。","en":"Provide goals, participants, recruitment, question count, responses and privacy needs. Do not repeat information already supplied.","ja":"目的、対象、募集元、設問数、回答、プライバシー条件を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('surveys-interview','published','{"id":"surveys-interview","group":"surveys","labels":{"zh":"半结构化访谈提纲","en":"Semi-structured interview guide","ja":"半構造化面接ガイド"},"terms":["访谈提纲","interview guide","probe","面接ガイド"],"guidance":{"zh":"给开场说明、暖场、核心问题、事实追问和收尾，按具体经历追问而不是让受访者赞同观点。附时间分配、记录模板和同意说明；不预填受访者答案，敏感问题可跳过。","en":"Provide an introduction, warm-up, core questions, factual probes and close. Ask about concrete experiences instead of seeking agreement. Include timing, note structure and consent language; never prefill answers and allow sensitive questions to be skipped.","ja":"導入、準備、中心質問、事実の深掘り、終了を作る。同意を誘導せず具体経験を聞く。時間、記録様式、同意説明を付け、回答を先作りせず敏感な質問は省略可能にする。"},"examples":{"zh":"针对了解学生使用学习应用时困难的小型调研，完成“半结构化访谈提纲”，按实际条件交付可用内容。","en":"Create semi-structured interview guide for a small study of difficulties students face with a learning app. Use the stated constraints and deliver usable content.","ja":"学習アプリで学生が困る点を調べる小規模調査について「半構造化面接ガイド」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：调研目标、对象、样本来源、问题数量、已有回答和隐私要求。已提供的信息不必重复。","en":"Provide goals, participants, recruitment, question count, responses and privacy needs. Do not repeat information already supplied.","ja":"目的、対象、募集元、設問数、回答、プライバシー条件を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('surveys-coding','published','{"id":"surveys-coding","group":"surveys","labels":{"zh":"访谈编码与主题提炼","en":"Interview coding and themes","ja":"面接のコード化・主題抽出"},"terms":["质性编码","thematic analysis","coding interview","質的分析"],"guidance":{"zh":"从脱敏逐字稿建立代码定义、纳入排除标准和原话证据，逐步合并主题并保留反例。给代码本、主题关系和解释边界；区分出现次数与普遍程度，不把推测动机当受访者原意。","en":"Build codes, inclusion/exclusion rules and quote evidence from redacted transcripts. Develop themes while retaining counterexamples. Deliver a codebook, relationships and limits. Distinguish frequency from prevalence and inferred motives from participant statements.","ja":"匿名化記録からコード定義、適用基準、引用根拠を作り、反例を残して主題化。コード表、関係、限界を出し、回数と一般性、推測動機と発言を分ける。"},"examples":{"zh":"针对了解学生使用学习应用时困难的小型调研，完成“访谈编码与主题提炼”，按实际条件交付可用内容。","en":"Create interview coding and themes for a small study of difficulties students face with a learning app. Use the stated constraints and deliver usable content.","ja":"学習アプリで学生が困る点を調べる小規模調査について「面接のコード化・主題抽出」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：调研目标、对象、样本来源、问题数量、已有回答和隐私要求。已提供的信息不必重复。","en":"Provide goals, participants, recruitment, question count, responses and privacy needs. Do not repeat information already supplied.","ja":"目的、対象、募集元、設問数、回答、プライバシー条件を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('editorial-report','published','{"id":"editorial-report","group":"editorial","labels":{"zh":"事实报道与消息稿","en":"Factual report and news brief","ja":"事実報告・ニュース原稿"},"terms":["报道","news brief","factual report","報道"],"guidance":{"zh":"围绕谁、何事、何时、何地、原因与过程组织导语和正文，按重要性分层。明确来源和未核实信息，引用保留原意；只使用提供的事实，不模拟记者到场或虚构采访。","en":"Structure lead and body around who, what, when, where, why and how, prioritizing information. Attribute sources and flag unverified claims. Preserve quotations and use supplied facts only; do not fabricate attendance or interviews.","ja":"誰、何、いつ、どこ、理由、経過で導入と本文を重要度順に構成。出典と未確認を示し引用意図を保つ。提供事実を使い、現地取材や面接を捏造しない。"},"examples":{"zh":"针对一篇根据活动记录撰写的社区报道，完成“事实报道与消息稿”，按实际条件交付可用内容。","en":"Create factual report and news brief for a community report based on event records. Use the stated constraints and deliver usable content.","ja":"行事記録を基にした地域レポートについて「事実報告・ニュース原稿」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：已核实事实、原始记录、读者、发布场景、篇幅和引用权限。已提供的信息不必重复。","en":"Provide verified facts, records, audience, publication context, length and quote permissions. Do not repeat information already supplied.","ja":"確認事実、記録、読者、掲載先、分量、引用許可を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('editorial-factcheck','published','{"id":"editorial-factcheck","group":"editorial","labels":{"zh":"主张与来源核查表","en":"Claims and source checklist","ja":"主張・出典の確認表"},"terms":["事实核查","fact check","claims audit","事実確認"],"guidance":{"zh":"逐句提取可核查主张、数字、日期和引文，对应资料位置及证据充分性。分为已支持、相矛盾、待核实，给改写和补证问题；没有访问来源的能力就列待查，不靠语气判断真假。","en":"Extract checkable claims, figures, dates and quotes. Map each to source locations and evidence strength. Mark supported, contradicted or unresolved, with edits and evidence requests. Without source access, leave checks pending rather than judging truth by tone.","ja":"検証可能な主張、数字、日付、引用を抽出し、出典位置と根拠に対応。支持、矛盾、未確認を分け修正と補足を示す。閲覧できない資料は未確認とする。"},"examples":{"zh":"针对一篇根据活动记录撰写的社区报道，完成“主张与来源核查表”，按实际条件交付可用内容。","en":"Create claims and source checklist for a community report based on event records. Use the stated constraints and deliver usable content.","ja":"行事記録を基にした地域レポートについて「主張・出典の確認表」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：已核实事实、原始记录、读者、发布场景、篇幅和引用权限。已提供的信息不必重复。","en":"Provide verified facts, records, audience, publication context, length and quote permissions. Do not repeat information already supplied.","ja":"確認事実、記録、読者、掲載先、分量、引用許可を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('editorial-formal','published','{"id":"editorial-formal","group":"editorial","labels":{"zh":"正式文稿精准润色","en":"Precise formal editing","ja":"正式文書の精密推敲"},"terms":["正式文稿","formal editing","公文润色","推敲"],"guidance":{"zh":"保持原文事实、立场与称谓，改善句式、逻辑、段落和术语，删空话及重复。给润色全文与重点修改理由，模糊信息标记待补；可参考正式媒体的一般行文特点，但不冒称机构发布或照搬其文章。","en":"Preserve facts, stance and names while improving syntax, logic, paragraphs and terminology. Remove filler and repetition. Deliver the full edit and key reasons, flagging missing details. Use general formal conventions without impersonating an institution or copying articles.","ja":"事実、立場、名称を保ち構文、論理、段落、用語を整え、空疎・重複表現を除く。全文と主要理由、不足情報を出す。正式文体を使っても機関の発表を装わない。"},"examples":{"zh":"针对一篇根据活动记录撰写的社区报道，完成“正式文稿精准润色”，按实际条件交付可用内容。","en":"Create precise formal editing for a community report based on event records. Use the stated constraints and deliver usable content.","ja":"行事記録を基にした地域レポートについて「正式文書の精密推敲」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：已核实事实、原始记录、读者、发布场景、篇幅和引用权限。已提供的信息不必重复。","en":"Provide verified facts, records, audience, publication context, length and quote permissions. Do not repeat information already supplied.","ja":"確認事実、記録、読者、掲載先、分量、引用許可を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('events-runshow','published','{"id":"events-runshow","group":"events","labels":{"zh":"活动流程与岗位表","en":"Run of show and staffing","ja":"進行表・役割分担"},"terms":["活动流程","run of show","event agenda","進行表"],"guidance":{"zh":"按分钟排布准备、签到、开场、互动和结束，列负责人、物料、提示语与切换条件。核对总时长和场地容量，加入缓冲及迟到处理，未确定人员用岗位代称。","en":"Schedule setup, check-in, opening, activities and close by minute, with owners, materials, cues and transitions. Reconcile runtime and capacity, include buffers and late arrivals, and use role placeholders for unassigned staff.","ja":"準備、受付、開始、交流、終了を分単位で組み、担当、物品、合図、切替を記す。総尺と定員、余裕、遅刻対応を確認し未定担当は役割名にする。"},"examples":{"zh":"针对一场40人参加的两小时社区交流会，完成“活动流程与岗位表”，按实际条件交付可用内容。","en":"Create run of show and staffing for a two-hour community meetup for 40 people. Use the stated constraints and deliver usable content.","ja":"40人が参加する2時間の地域交流会について「進行表・役割分担」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：目标、人数、场地、日期、预算、人员和限制。已提供的信息不必重复。","en":"Provide goals, attendance, venue, date, budget, staff and constraints. Do not repeat information already supplied.","ja":"目的、人数、会場、日付、予算、人員、制約を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('events-budget','published','{"id":"events-budget","group":"events","labels":{"zh":"活动预算与物料","en":"Event budget and materials","ja":"行事予算・物品"},"terms":["活动预算","event budget","materials","行事予算"],"guidance":{"zh":"输出数量、单价、费用类型、估价依据和负责人明细，分必需与可选并预留缓冲。核对公式和总额，对未知价格标估算；提供削减方案，不虚构供应商报价。","en":"Itemize quantities, unit costs, cost types, estimate basis and owners. Separate essentials/options and contingency. Check arithmetic and label unknown prices as estimates. Offer reductions without inventing vendor quotes.","ja":"数量、単価、費目、見積根拠、担当を一覧化し必須・任意と予備費を分ける。合計を照合し不明価格は概算とする。削減案を出し業者見積を作らない。"},"examples":{"zh":"针对一场40人参加的两小时社区交流会，完成“活动预算与物料”，按实际条件交付可用内容。","en":"Create event budget and materials for a two-hour community meetup for 40 people. Use the stated constraints and deliver usable content.","ja":"40人が参加する2時間の地域交流会について「行事予算・物品」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：目标、人数、场地、日期、预算、人员和限制。已提供的信息不必重复。","en":"Provide goals, attendance, venue, date, budget, staff and constraints. Do not repeat information already supplied.","ja":"目的、人数、会場、日付、予算、人員、制約を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('events-backup','published','{"id":"events-backup","group":"events","labels":{"zh":"活动异常与备用方案","en":"Event contingency plan","ja":"行事の代替・例外対応"},"terms":["活动预案","contingency event","雨天","代替案"],"guidance":{"zh":"围绕天气、设备、人员和超时列触发信号、决策人、替代流程及通知稿。给现场速查表与演练清单，明确依赖场地方确认的事项，不把一般预案写成已验证安全方案。","en":"For weather, equipment, staffing and delays, define triggers, decision owners, alternatives and notices. Provide a quick-reference sheet and rehearsal list. Flag venue-dependent confirmations; a general plan is not a verified safety assessment.","ja":"天候、機材、人員、遅延の兆候、判断者、代替手順、案内文を作る。早見表と練習項目、会場確認事項を示し、一般案を安全確認済みとしない。"},"examples":{"zh":"针对一场40人参加的两小时社区交流会，完成“活动异常与备用方案”，按实际条件交付可用内容。","en":"Create event contingency plan for a two-hour community meetup for 40 people. Use the stated constraints and deliver usable content.","ja":"40人が参加する2時間の地域交流会について「行事の代替・例外対応」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：目标、人数、场地、日期、预算、人员和限制。已提供的信息不必重复。","en":"Provide goals, attendance, venue, date, budget, staff and constraints. Do not repeat information already supplied.","ja":"目的、人数、会場、日付、予算、人員、制約を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('community-welcome','published','{"id":"community-welcome","group":"community","labels":{"zh":"入群欢迎与新手路径","en":"Member onboarding","ja":"新規参加者の導入"},"terms":["社群欢迎","community onboarding","welcome","参加案内"],"guidance":{"zh":"写欢迎消息、三步入门路径、规则摘要和自我介绍引导，说明哪里提问与获得帮助。按新手负担控制长度，提供可直接发送的文案和管理员检查点，不强迫公开个人信息。","en":"Write welcome copy, a three-step start, rule summary and introductions, explaining where to ask for help. Keep it manageable for newcomers. Provide send-ready text and moderator checks without requiring personal disclosures.","ja":"歓迎文、三段階の開始、規則要約、自己紹介案内、相談先を作る。初心者の負担を抑え、送信用文と管理確認を出す。個人情報公開を強制しない。"},"examples":{"zh":"针对一个面向编程初学者的200人学习社群，完成“入群欢迎与新手路径”，按实际条件交付可用内容。","en":"Create member onboarding for a 200-member community for beginner programmers. Use the stated constraints and deliver usable content.","ja":"プログラミング初心者200人の学習コミュニティについて「新規参加者の導入」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：社群目标、成员特点、平台、运营时间、规则和现有反馈。已提供的信息不必重复。","en":"Provide goals, member profile, platform, staff time, rules and feedback. Do not repeat information already supplied.","ja":"目的、参加者、媒体、運営時間、規則、意見を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('community-engagement','published','{"id":"community-engagement","group":"community","labels":{"zh":"社群话题与参与活动","en":"Community discussion activities","ja":"話題・参加企画"},"terms":["社群话题","engagement","discussion prompt","交流企画"],"guidance":{"zh":"按成员目标设计提问、作品展示和互助任务，逐项给完整开场文、参与门槛、时间和主持追问。提供低参与时的调整，不虚构成员发言或用刷屏换活跃。","en":"Design questions, showcases and peer-help tasks around member goals. Supply opening posts, participation steps, timing and facilitator probes. Add low-participation adjustments without fabricated member comments or spam-based engagement.","ja":"目的に合わせ質問、作品紹介、助け合いを設計し、投稿全文、参加手順、時間、進行の追問を出す。低参加時の調整も示し架空発言や連投で補わない。"},"examples":{"zh":"针对一个面向编程初学者的200人学习社群，完成“社群话题与参与活动”，按实际条件交付可用内容。","en":"Create community discussion activities for a 200-member community for beginner programmers. Use the stated constraints and deliver usable content.","ja":"プログラミング初心者200人の学習コミュニティについて「話題・参加企画」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：社群目标、成员特点、平台、运营时间、规则和现有反馈。已提供的信息不必重复。","en":"Provide goals, member profile, platform, staff time, rules and feedback. Do not repeat information already supplied.","ja":"目的、参加者、媒体、運営時間、規則、意見を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('community-moderation','published','{"id":"community-moderation","group":"community","labels":{"zh":"社区规则与争议处理","en":"Community rules and disputes","ja":"規則・対立への対応"},"terms":["社群规则","moderation","dispute","コミュニティ規則"],"guidance":{"zh":"把抽象规则改成可观察行为和正反例，设计提醒、处理、申诉和记录流程。针对提供的争议写中立回应，引用行为而非攻击身份；保留管理员判断，不自动公开私人对话。","en":"Turn abstract rules into observable behaviors and examples, with warning, action, appeal and logging paths. Draft neutral responses to supplied disputes, addressing conduct rather than identity. Keep moderator judgment and private conversations protected.","ja":"規則を観察可能な行動と例にし、注意、対応、異議申立、記録を設計。対立には属性でなく行為を示す中立文を作り、管理判断と私的会話を守る。"},"examples":{"zh":"针对一个面向编程初学者的200人学习社群，完成“社区规则与争议处理”，按实际条件交付可用内容。","en":"Create community rules and disputes for a 200-member community for beginner programmers. Use the stated constraints and deliver usable content.","ja":"プログラミング初心者200人の学習コミュニティについて「規則・対立への対応」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：社群目标、成员特点、平台、运营时间、规则和现有反馈。已提供的信息不必重复。","en":"Provide goals, member profile, platform, staff time, rules and feedback. Do not repeat information already supplied.","ja":"目的、参加者、媒体、運営時間、規則、意見を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('training-onboarding','published','{"id":"training-onboarding","group":"training","labels":{"zh":"新人上手计划","en":"New-starter plan","ja":"新人導入計画"},"terms":["员工入职","onboarding plan","培训计划","新人研修"],"guidance":{"zh":"按观察、跟做、独立实践分阶段排目标，列每天任务、资料、联系人和完成证据。把权限开通与业务学习分开，安排反馈点及补练，不用参加会议代替掌握技能。","en":"Stage learning through observation, guided practice and independent work. Specify daily tasks, resources, contacts and evidence. Separate access setup from learning, include feedback and remedial practice, and do not equate meeting attendance with competence.","ja":"見学、伴走、自立に分け、日課、資料、連絡先、達成証拠を記す。権限設定と学習を分け、振返りと補習を入れ、会議出席を技能習得としない。"},"examples":{"zh":"针对帮助新同事在两周内掌握订单处理的培训，完成“新人上手计划”，按实际条件交付可用内容。","en":"Create new-starter plan for two-week onboarding for a new order-processing colleague. Use the stated constraints and deliver usable content.","ja":"新人が2週間で注文処理を覚える研修について「新人導入計画」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：岗位任务、已有流程、能力起点、可用时间、导师和验收标准。已提供的信息不必重复。","en":"Provide role tasks, workflows, baseline skills, time, mentors and acceptance criteria. Do not repeat information already supplied.","ja":"職務、既存手順、開始能力、時間、指導者、確認基準を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('training-workshop','published','{"id":"training-workshop","group":"training","labels":{"zh":"实操培训课程","en":"Hands-on workshop","ja":"実践研修"},"terms":["实操培训","workshop","facilitation","実践研修"],"guidance":{"zh":"根据岗位真实任务设计短讲解、示范、练习与反馈，交付讲师流程、学员材料和示例答案。明确每段时间、设备与错误演示，练习输入用脱敏样例，不泄露业务数据。","en":"Build short explanations, demos, practice and feedback around real work. Deliver facilitator notes, learner materials and example answers with timing, equipment and error demonstrations. Use redacted practice data rather than exposing business records.","ja":"実務に沿って短い説明、実演、演習、講評を構成。進行案、教材、解答例、時間、機材、誤り例を出し、演習は機密除去済みデータを使う。"},"examples":{"zh":"针对帮助新同事在两周内掌握订单处理的培训，完成“实操培训课程”，按实际条件交付可用内容。","en":"Create hands-on workshop for two-week onboarding for a new order-processing colleague. Use the stated constraints and deliver usable content.","ja":"新人が2週間で注文処理を覚える研修について「実践研修」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：岗位任务、已有流程、能力起点、可用时间、导师和验收标准。已提供的信息不必重复。","en":"Provide role tasks, workflows, baseline skills, time, mentors and acceptance criteria. Do not repeat information already supplied.","ja":"職務、既存手順、開始能力、時間、指導者、確認基準を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('training-handover','published','{"id":"training-handover","group":"training","labels":{"zh":"岗位交接文档","en":"Role handover document","ja":"業務引継ぎ書"},"terms":["工作交接","handover","交接文档","引継ぎ"],"guidance":{"zh":"整理周期任务、当前事项、文件位置、依赖联系人和未决风险，给到期日、下一步及接手确认。区分已完成与待处理，凭据仅说明获取渠道；输出可维护表格，不依靠离职者记忆补造事实。","en":"Document recurring work, open items, file locations, dependencies and risks, with due dates, next steps and acceptance. Separate done/pending work; describe credential access channels only. Deliver a maintainable table without inventing missing facts.","ja":"定期業務、未完事項、資料場所、依存先、懸念に期限、次の行動、受領確認を付ける。完了と未処理を分け、認証情報は取得経路のみ記し、不明事実を補作しない。"},"examples":{"zh":"针对帮助新同事在两周内掌握订单处理的培训，完成“岗位交接文档”，按实际条件交付可用内容。","en":"Create role handover document for two-week onboarding for a new order-processing colleague. Use the stated constraints and deliver usable content.","ja":"新人が2週間で注文処理を覚える研修について「業務引継ぎ書」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：岗位任务、已有流程、能力起点、可用时间、导师和验收标准。已提供的信息不必重复。","en":"Provide role tasks, workflows, baseline skills, time, mentors and acceptance criteria. Do not repeat information already supplied.","ja":"職務、既存手順、開始能力、時間、指導者、確認基準を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('games-state','published','{"id":"games-state","group":"games","labels":{"zh":"角色状态机","en":"Character state machine","ja":"キャラクター状態機械"},"terms":["状态机","state machine","Godot","Unity","状態機械"],"guidance":{"zh":"定义待机、移动、交互等状态和可触发转换，给目标引擎代码与输入映射。处理重复输入、动画结束和禁用状态，提供转换表及测试场景，避免多个布尔值互相矛盾。","en":"Define states and transitions for idle, movement and interaction. Supply engine-specific code, input mapping and a transition table. Handle repeated input, animation completion and disabled states with test scenes; avoid contradictory boolean flags.","ja":"待機、移動、対話の状態と遷移を定義し、対象エンジンのコード、入力対応、遷移表を出す。連打、アニメ終了、無効状態をテストし矛盾するフラグを避ける。"},"examples":{"zh":"针对一个有背包与关卡的二维解谜小游戏，完成“角色状态机”，按实际条件交付可用内容。","en":"Create character state machine for a small 2D puzzle game with inventory and levels. Use the stated constraints and deliver usable content.","ja":"持ち物とステージがある小規模2Dパズルについて「キャラクター状態機械」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：引擎版本、目标平台、核心循环、资源限制和现有代码。已提供的信息不必重复。","en":"Provide engine version, platform, core loop, asset limits and code. Do not repeat information already supplied.","ja":"エンジン版、OS、基本ループ、素材制約、コードを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('games-levels','published','{"id":"games-levels","group":"games","labels":{"zh":"关卡节奏与教学","en":"Level pacing and tutorials","ja":"ステージ進行・導入"},"terms":["关卡","level design","tutorial","ステージ設計"],"guidance":{"zh":"围绕一个核心机制设计教学、练习、变化和综合挑战，逐关给目标、地图结构、提示和失败恢复。用难度来源解释递进，标注需试玩验证的假设，不靠增加血量假装玩法丰富。","en":"Build introduction, practice, variation and combined challenges around one mechanic. Specify goals, layouts, hints and recovery per level. Explain difficulty progression and playtest assumptions rather than substituting inflated health for variety.","ja":"一つの機構から導入、練習、変化、総合課題を作り、目標、配置、ヒント、再開を各面に示す。難度の理由と試遊仮説を記し、体力増加だけで多様性としない。"},"examples":{"zh":"针对一个有背包与关卡的二维解谜小游戏，完成“关卡节奏与教学”，按实际条件交付可用内容。","en":"Create level pacing and tutorials for a small 2D puzzle game with inventory and levels. Use the stated constraints and deliver usable content.","ja":"持ち物とステージがある小規模2Dパズルについて「ステージ進行・導入」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：引擎版本、目标平台、核心循环、资源限制和现有代码。已提供的信息不必重复。","en":"Provide engine version, platform, core loop, asset limits and code. Do not repeat information already supplied.","ja":"エンジン版、OS、基本ループ、素材制約、コードを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('games-save','published','{"id":"games-save","group":"games","labels":{"zh":"存档与版本兼容","en":"Save files and compatibility","ja":"セーブ・版互換"},"terms":["存档","save game","serialization","セーブ"],"guidance":{"zh":"给存档结构、版本号、校验和迁移流程，区分运行时对象与可序列化数据。实现原子写入、备份和损坏恢复，覆盖旧版本、缺字段及重复加载，不把对象引用直接写入存档。","en":"Define save schemas, versions, validation and migration. Separate runtime objects from serializable data. Implement atomic writes, backups and corruption recovery; test older versions, missing fields and repeated loads without serializing live object references.","ja":"保存構造、版、検証、移行を定め、実行時オブジェクトと保存データを分離。原子的書込み、予備、破損復旧を実装し、旧版、欠項目、再読込を確認する。"},"examples":{"zh":"针对一个有背包与关卡的二维解谜小游戏，完成“存档与版本兼容”，按实际条件交付可用内容。","en":"Create save files and compatibility for a small 2D puzzle game with inventory and levels. Use the stated constraints and deliver usable content.","ja":"持ち物とステージがある小規模2Dパズルについて「セーブ・版互換」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：引擎版本、目标平台、核心循环、资源限制和现有代码。已提供的信息不必重复。","en":"Provide engine version, platform, core loop, asset limits and code. Do not repeat information already supplied.","ja":"エンジン版、OS、基本ループ、素材制約、コードを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('assets3d-model','published','{"id":"assets3d-model","group":"assets3d","labels":{"zh":"模型生成需求","en":"Model generation brief","ja":"モデル生成仕様"},"terms":["3D模型","low poly","model brief","3Dモデル"],"guidance":{"zh":"拆分主体、结构、道具和不可变尺寸，写正侧背视图需求、比例、拓扑重点及命名规则。给通用描述与目标工具可用参数分栏，列验收角度；没有模型文件时不声称拓扑已检查。","en":"Specify structure, props, fixed dimensions, front/side/back views, proportions, topology needs and naming. Separate portable descriptions from supported tool parameters. Provide inspection views without claiming topology was checked when no model exists.","ja":"本体、構造、小物、固定寸法、三面図、比率、トポロジー、命名を指定。共通記述と対応パラメーターを分け、検査視点を出す。モデルなしで構造確認済みとしない。"},"examples":{"zh":"针对用于低多边形城市动画的街角咖啡店，完成“模型生成需求”，按实际条件交付可用内容。","en":"Create model generation brief for a corner café for a low-poly city animation. Use the stated constraints and deliver usable content.","ja":"ローポリ都市アニメ用の街角カフェについて「モデル生成仕様」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：用途、建模工具、尺度、面数预算、参考图和导出格式。已提供的信息不必重复。","en":"Provide use case, modeling tool, scale, polygon budget, references and export format. Do not repeat information already supplied.","ja":"用途、制作ツール、尺度、ポリゴン予算、参考、出力形式を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('assets3d-material','published','{"id":"assets3d-material","group":"assets3d","labels":{"zh":"PBR 材质与贴图","en":"PBR material and texture brief","ja":"PBR材質・テクスチャ仕様"},"terms":["PBR","贴图","roughness","texture","マテリアル"],"guidance":{"zh":"描述表面材质、粗糙度变化、磨损位置和尺度，按目标工作流列贴图通道、色彩空间与分辨率。保持无缝平铺和光照中性，区分材质本身与烘焙阴影；工具不支持的通道不要伪造参数。","en":"Describe surface, roughness variation, wear and scale. List workflow-specific maps, color spaces and resolution. Address seamless tiling and neutral lighting, separating material properties from baked shadows. Do not invent unsupported channels or parameters.","ja":"表面、粗さ変化、摩耗、尺度を記し、方式に合うマップ、色空間、解像度を列挙。継ぎ目と中立照明を確認し、材質と焼付け影を分け、非対応設定を作らない。"},"examples":{"zh":"针对用于低多边形城市动画的街角咖啡店，完成“PBR 材质与贴图”，按实际条件交付可用内容。","en":"Create pbr material and texture brief for a corner café for a low-poly city animation. Use the stated constraints and deliver usable content.","ja":"ローポリ都市アニメ用の街角カフェについて「PBR材質・テクスチャ仕様」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：用途、建模工具、尺度、面数预算、参考图和导出格式。已提供的信息不必重复。","en":"Provide use case, modeling tool, scale, polygon budget, references and export format. Do not repeat information already supplied.","ja":"用途、制作ツール、尺度、ポリゴン予算、参考、出力形式を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('assets3d-export','published','{"id":"assets3d-export","group":"assets3d","labels":{"zh":"资产交付与导出检查","en":"Asset export checklist","ja":"素材納品・出力確認"},"terms":["模型导出","glTF","FBX","asset export","モデル出力"],"guidance":{"zh":"按目标引擎整理单位、轴向、枢轴、命名、材质路径、碰撞和LOD需求。给导出设置、目录清单及重新导入验证步骤，标明格式损失；未实际导入时把结果列为待验证。","en":"Specify units, axes, pivots, names, material paths, collisions and LODs for the target engine. Provide export settings, file inventory and re-import checks, including format losses. Mark results pending when no actual import was performed.","ja":"対象エンジンの単位、軸、原点、命名、材質参照、衝突、LODを整理。設定、納品一覧、再取込手順と形式の欠落を示し、未実行は確認待ちにする。"},"examples":{"zh":"针对用于低多边形城市动画的街角咖啡店，完成“资产交付与导出检查”，按实际条件交付可用内容。","en":"Create asset export checklist for a corner café for a low-poly city animation. Use the stated constraints and deliver usable content.","ja":"ローポリ都市アニメ用の街角カフェについて「素材納品・出力確認」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：用途、建模工具、尺度、面数预算、参考图和导出格式。已提供的信息不必重复。","en":"Provide use case, modeling tool, scale, polygon budget, references and export format. Do not repeat information already supplied.","ja":"用途、制作ツール、尺度、ポリゴン予算、参考、出力形式を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('photo-packshot','published','{"id":"photo-packshot","group":"photo","labels":{"zh":"商品白底与细节图","en":"Product packshots and details","ja":"白背景商品・詳細画像"},"terms":["白底图","packshot","产品细节","商品画像"],"guidance":{"zh":"固定产品轮廓、颜色、标志和部件数量，分别输出正面、侧面及材质近景提示词。明确背景、落影、焦点和留白，禁止凭空增加功能；文字标识交给可控后期，附与参考图核对表。","en":"Lock silhouette, color, logo and component count. Write front, side and material close-up prompts with background, contact shadow, focus and space. Do not add product features. Reserve exact lettering for controlled postproduction and compare against references.","ja":"輪郭、色、ロゴ、部品数を固定し、正面、側面、材質接写の文を作る。背景、接地影、焦点、余白を指定。機能を増やさず正確な文字は後処理とし、参考照合を添える。"},"examples":{"zh":"针对一款哑光陶瓷杯及其生活方式展示图，完成“商品白底与细节图”，按实际条件交付可用内容。","en":"Create product packshots and details for a matte ceramic mug and lifestyle images. Use the stated constraints and deliver usable content.","ja":"マットな陶器カップと使用場面の画像について「白背景商品・詳細画像」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：产品实物参考、不可改特征、尺寸、用途、画幅和目标工具。已提供的信息不必重复。","en":"Provide product references, fixed features, dimensions, use case, aspect ratio and tool. Do not repeat information already supplied.","ja":"商品参考、固定特徴、寸法、用途、縦横比、ツールを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('photo-lifestyle','published','{"id":"photo-lifestyle","group":"photo","labels":{"zh":"生活方式场景图","en":"Lifestyle product scenes","ja":"商品利用シーン"},"terms":["生活方式","lifestyle image","场景图","利用シーン"],"guidance":{"zh":"围绕真实使用动作构图，说明人物手部、产品比例、承重接触和环境光。给远景展示环境、中景展示使用、近景展示细节的独立版本，保持同一产品ID，不靠堆砌形容词替代空间关系。","en":"Compose around a believable use action, specifying hands, product scale, physical contact and light. Provide wide context, medium usage and close detail variants with a stable product ID. Describe spatial relationships instead of adjective piles.","ja":"自然な使用動作を軸に手、製品比率、接触、光を指定。遠景の環境、中景の使用、近景の詳細を同一商品IDで分ける。形容詞の羅列で空間関係を代用しない。"},"examples":{"zh":"针对一款哑光陶瓷杯及其生活方式展示图，完成“生活方式场景图”，按实际条件交付可用内容。","en":"Create lifestyle product scenes for a matte ceramic mug and lifestyle images. Use the stated constraints and deliver usable content.","ja":"マットな陶器カップと使用場面の画像について「商品利用シーン」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：产品实物参考、不可改特征、尺寸、用途、画幅和目标工具。已提供的信息不必重复。","en":"Provide product references, fixed features, dimensions, use case, aspect ratio and tool. Do not repeat information already supplied.","ja":"商品参考、固定特徴、寸法、用途、縦横比、ツールを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('photo-interior','published','{"id":"photo-interior","group":"photo","labels":{"zh":"室内布局与氛围图","en":"Interior layout and mood images","ja":"室内配置・雰囲気画像"},"terms":["室内","interior","room layout","室内配置"],"guidance":{"zh":"锁定墙体、门窗、尺度和通行动线，分开布局图与氛围效果图。给机位、视角、家具位置、材料和光源，明确可变装饰；图像只作概念参考，不能假定满足施工或结构要求。","en":"Lock walls, openings, dimensions and circulation. Separate layout diagrams from mood renders. Specify camera, furniture, materials and lighting, distinguishing adjustable decor. Treat images as concepts rather than verified construction or structural plans.","ja":"壁、開口、寸法、動線を固定し、配置図と雰囲気図を分ける。視点、家具、材質、光、可変装飾を指定。画像は構想であり施工・構造の適合確認としない。"},"examples":{"zh":"针对一款哑光陶瓷杯及其生活方式展示图，完成“室内布局与氛围图”，按实际条件交付可用内容。","en":"Create interior layout and mood images for a matte ceramic mug and lifestyle images. Use the stated constraints and deliver usable content.","ja":"マットな陶器カップと使用場面の画像について「室内配置・雰囲気画像」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：产品实物参考、不可改特征、尺寸、用途、画幅和目标工具。已提供的信息不必重复。","en":"Provide product references, fixed features, dimensions, use case, aspect ratio and tool. Do not repeat information already supplied.","ja":"商品参考、固定特徴、寸法、用途、縦横比、ツールを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('character-turnaround','published','{"id":"character-turnaround","group":"character","labels":{"zh":"角色三视图与设定表","en":"Character turnaround sheet","ja":"キャラクター三面図"},"terms":["三视图","turnaround","character sheet","三面図"],"guidance":{"zh":"建立角色ID和脸型、发型、服装、配饰清单，输出同尺度正侧背视图的分别提示词。统一姿态基准、光照和背景，标记不可改变项；将年龄外观与身份设定分开，避免视图间添加不同配饰。","en":"Define a character ID and fixed face, hair, clothing and accessories. Write same-scale front/side/back prompts with consistent pose baseline, light and background. Separate visual age from biography and prevent accessories from changing between views.","ja":"ID、顔、髪、衣服、装飾を固定し、同縮尺の正側背面文を作る。姿勢基準、光、背景をそろえ、見た目年齢と設定を分け、視点間で小物を増減させない。"},"examples":{"zh":"针对一位穿蓝色外套、携带旧相机的原创探险者，完成“角色三视图与设定表”，按实际条件交付可用内容。","en":"Create character turnaround sheet for an original explorer in a blue coat carrying an old camera. Use the stated constraints and deliver usable content.","ja":"青い上着と古いカメラを持つオリジナル探検家について「キャラクター三面図」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：角色设定、固定特征、画风、参考素材、画幅和目标软件。已提供的信息不必重复。","en":"Provide character profile, fixed traits, style, references, aspect ratio and software. Do not repeat information already supplied.","ja":"人物設定、固定特徴、画風、参考、縦横比、ソフトを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('character-expression','published','{"id":"character-expression","group":"character","labels":{"zh":"表情与动作参考板","en":"Expression and pose board","ja":"表情・ポーズ資料"},"terms":["表情板","expression sheet","pose","表情集"],"guidance":{"zh":"按情绪原因而非标签罗列设计表情，描述眉眼、嘴角、肩颈和重心。分别给面部近景和全身动作版本，保留角色固定特征；九宫格使用格号与单格内容，避免一格多动作相互冲突。","en":"Design expressions from emotional causes, describing eyes, mouth, shoulders and balance. Supply close-up and full-body variants while preserving identity. For a nine-panel board, number panels and assign one clear state to each.","ja":"感情の理由から眉目、口、肩首、重心を描写し、接写と全身を分ける。固定特徴を守り、九分割なら番号ごとに一つの状態を割り当てる。"},"examples":{"zh":"针对一位穿蓝色外套、携带旧相机的原创探险者，完成“表情与动作参考板”，按实际条件交付可用内容。","en":"Create expression and pose board for an original explorer in a blue coat carrying an old camera. Use the stated constraints and deliver usable content.","ja":"青い上着と古いカメラを持つオリジナル探検家について「表情・ポーズ資料」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：角色设定、固定特征、画风、参考素材、画幅和目标软件。已提供的信息不必重复。","en":"Provide character profile, fixed traits, style, references, aspect ratio and software. Do not repeat information already supplied.","ja":"人物設定、固定特徴、画風、参考、縦横比、ソフトを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('character-style','published','{"id":"character-style","group":"character","labels":{"zh":"视觉风格规范","en":"Visual style guide","ja":"ビジュアル様式規約"},"terms":["风格规范","style bible","visual guide","画風規約"],"guidance":{"zh":"把参考中的线条、色板、形状语言、材质和光照整理为可执行规则。输出允许/避免对照、示例提示词与一致性检查，不只写高级感；区分整体风格和特定角色固定项。","en":"Extract actionable rules for linework, palette, shape language, materials and light. Provide do/avoid comparisons, example prompts and consistency checks rather than vague quality adjectives. Separate global style from character-specific constraints.","ja":"線、色、形状言語、材質、光を実行可能な規則にする。推奨・回避例、生成文、一貫性確認を出し、抽象的な上質さで済ませず全体様式と人物固有条件を分ける。"},"examples":{"zh":"针对一位穿蓝色外套、携带旧相机的原创探险者，完成“视觉风格规范”，按实际条件交付可用内容。","en":"Create visual style guide for an original explorer in a blue coat carrying an old camera. Use the stated constraints and deliver usable content.","ja":"青い上着と古いカメラを持つオリジナル探検家について「ビジュアル様式規約」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：角色设定、固定特征、画风、参考素材、画幅和目标软件。已提供的信息不必重复。","en":"Provide character profile, fixed traits, style, references, aspect ratio and software. Do not repeat information already supplied.","ja":"人物設定、固定特徴、画風、参考、縦横比、ソフトを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('editing-assembly','published','{"id":"editing-assembly","group":"editing","labels":{"zh":"剪辑时间线与节奏","en":"Edit timeline and pacing","ja":"編集タイムライン・テンポ"},"terms":["剪辑","timeline","rough cut","編集"],"guidance":{"zh":"逐段给源素材入出点、时间线位置、画面用途和声音衔接，核对总时长。按叙事需要选择远中近景和留白，缺镜头列补拍清单；没有素材时间码则用明确占位，不编造可直接导入的工程文件。","en":"List source in/out points, timeline position, visual purpose and audio transitions, reconciling duration. Choose shot scale and pauses for the story; list missing coverage. Use explicit placeholders when timecodes are absent, without claiming an importable project.","ja":"素材の入出点、配置、画面目的、音のつなぎを列挙し総尺を照合。物語で画角と間を選び不足カットを示す。時間コードなしは仮欄にし、読込可能なプロジェクトと装わない。"},"examples":{"zh":"针对由六段素材组成的45秒产品短片，完成“剪辑时间线与节奏”，按实际条件交付可用内容。","en":"Create edit timeline and pacing for a 45-second product video assembled from six clips. Use the stated constraints and deliver usable content.","ja":"六つの素材で作る45秒の商品動画について「編集タイムライン・テンポ」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：素材清单或时间码、目标时长、叙事重点、配音和剪辑软件。已提供的信息不必重复。","en":"Provide asset list/timecodes, duration, narrative focus, voice track and editor. Do not repeat information already supplied.","ja":"素材一覧・時間コード、尺、重点、音声、編集ソフトを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('editing-captions','published','{"id":"editing-captions","group":"editing","labels":{"zh":"字幕排版与可读性","en":"Caption layout and readability","ja":"字幕配置・可読性"},"terms":["字幕排版","caption layout","safe area","字幕配置"],"guidance":{"zh":"根据语言、画幅和平台安全区设计字体层级、行长、断句与显示时长。逐条标记拥挤和遮挡问题，提供短版文案与样式表；保持原意，未看视频时不声称检查全部遮挡。","en":"Design hierarchy, line length, segmentation and duration for the language, frame and platform safe areas. Flag crowded or obstructive cues and supply shorter wording plus a style sheet. Preserve meaning; without video, mark occlusion checks pending.","ja":"言語、画幅、安全域で階層、行長、改行、表示尺を設計。詰込みや遮蔽を指摘し短文と様式表を出す。意味を保ち、映像なしの遮蔽確認は未実施にする。"},"examples":{"zh":"针对由六段素材组成的45秒产品短片，完成“字幕排版与可读性”，按实际条件交付可用内容。","en":"Create caption layout and readability for a 45-second product video assembled from six clips. Use the stated constraints and deliver usable content.","ja":"六つの素材で作る45秒の商品動画について「字幕配置・可読性」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：素材清单或时间码、目标时长、叙事重点、配音和剪辑软件。已提供的信息不必重复。","en":"Provide asset list/timecodes, duration, narrative focus, voice track and editor. Do not repeat information already supplied.","ja":"素材一覧・時間コード、尺、重点、音声、編集ソフトを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('editing-delivery','published','{"id":"editing-delivery","group":"editing","labels":{"zh":"导出与多平台版本","en":"Export and platform variants","ja":"書出し・媒体別版"},"terms":["视频导出","export video","aspect ratio","動画書出し"],"guidance":{"zh":"列主版本与横竖版的裁切、字幕安全区、声音和编码要求，目标平台限制以用户资料或当前文档为准。给导出检查清单和文件命名，区分重构画面与硬裁切，不虚构渲染完成。","en":"Define master and landscape/portrait variants with reframing, captions, audio and encoding. Use supplied or current platform documentation for limits. Deliver export checks and filenames, distinguishing recomposition from cropping; do not claim rendering occurred.","ja":"マスターと横縦版の再構図、字幕、音、符号化を整理。制限は提供・最新資料に合わせ、確認表と命名を出す。構図変更と切抜きを分け、書出し済みとしない。"},"examples":{"zh":"针对由六段素材组成的45秒产品短片，完成“导出与多平台版本”，按实际条件交付可用内容。","en":"Create export and platform variants for a 45-second product video assembled from six clips. Use the stated constraints and deliver usable content.","ja":"六つの素材で作る45秒の商品動画について「書出し・媒体別版」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：素材清单或时间码、目标时长、叙事重点、配音和剪辑软件。已提供的信息不必重复。","en":"Provide asset list/timecodes, duration, narrative focus, voice track and editor. Do not repeat information already supplied.","ja":"素材一覧・時間コード、尺、重点、音声、編集ソフトを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('fiction-plot','published','{"id":"fiction-plot","group":"fiction","labels":{"zh":"情节大纲与伏笔","en":"Plot outline and foreshadowing","ja":"筋書き・伏線"},"terms":["小说大纲","plot outline","foreshadowing","伏線"],"guidance":{"zh":"用人物目标、阻力、选择和代价串联场景，给起因、转折、高潮与结局。建立伏笔设置和回收对照，解释悬念信息何时对读者开放；避免靠突然新增设定解决主要冲突。","en":"Link scenes through goals, obstacles, choices and costs. Outline setup, turns, climax and ending, mapping planted clues to payoffs and reader knowledge. Avoid resolving the central conflict with an unprepared new rule.","ja":"目的、障害、選択、代償で場面をつなぎ、発端、転換、頂点、結末を構成。伏線と回収、読者への開示時点を対応させ、突然の新設定で解決しない。"},"examples":{"zh":"针对一篇围绕失踪相机展开的3000字原创悬疑故事，完成“情节大纲与伏笔”，按实际条件交付可用内容。","en":"Create plot outline and foreshadowing for an original 3,000-word mystery about a missing camera. Use the stated constraints and deliver usable content.","ja":"消えたカメラを巡る約3000字のオリジナル短編ミステリーについて「筋書き・伏線」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：题材、篇幅、视角、人物目标、已有情节和内容边界。已提供的信息不必重复。","en":"Provide genre, length, viewpoint, character goals, existing plot and boundaries. Do not repeat information already supplied.","ja":"ジャンル、長さ、視点、人物目的、既存筋、内容範囲を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('fiction-scene','published','{"id":"fiction-scene","group":"fiction","labels":{"zh":"场景与人物对话","en":"Scenes and dialogue","ja":"場面・会話の執筆"},"terms":["人物对话","dialogue","scene writing","会話"],"guidance":{"zh":"先明确本场景的冲突和信息变化，再写完整正文。通过动作、感官和潜台词展现人物，区分各人说话习惯；维持视角与时间一致，删除重复解释，附场景如何推进主线的简短说明。","en":"Define the scene conflict and information change, then write the full scene. Use action, sensory detail and subtext with distinct voices. Keep viewpoint/time consistent, remove redundant explanation and briefly state how the scene advances the story.","ja":"対立と情報変化を定め全文を書く。動作、感覚、含意で人物を示し話し方を分ける。視点と時制を保ち重複説明を除き、本筋への役割を短く添える。"},"examples":{"zh":"针对一篇围绕失踪相机展开的3000字原创悬疑故事，完成“场景与人物对话”，按实际条件交付可用内容。","en":"Create scenes and dialogue for an original 3,000-word mystery about a missing camera. Use the stated constraints and deliver usable content.","ja":"消えたカメラを巡る約3000字のオリジナル短編ミステリーについて「場面・会話の執筆」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：题材、篇幅、视角、人物目标、已有情节和内容边界。已提供的信息不必重复。","en":"Provide genre, length, viewpoint, character goals, existing plot and boundaries. Do not repeat information already supplied.","ja":"ジャンル、長さ、視点、人物目的、既存筋、内容範囲を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('fiction-continuity','published','{"id":"fiction-continuity","group":"fiction","labels":{"zh":"故事设定与时间线核对","en":"Story continuity audit","ja":"設定・時系列の照合"},"terms":["设定冲突","story continuity","timeline","設定矛盾"],"guidance":{"zh":"从已提供正文提取人物、地点、物品和事件时间线，逐处引用矛盾证据。区分叙述者不可靠、刻意悬念和实际疏漏，给最小修订与连锁影响；不要假设未提供章节已经解释问题。","en":"Extract people, places, objects and chronology from supplied text. Cite contradictions, distinguishing unreliable narration and deliberate mystery from errors. Suggest minimal edits and downstream effects without assuming unseen chapters explain gaps.","ja":"提供本文から人物、場所、物、時系列を抽出し矛盾の箇所を引用。不確かな語り、意図的謎、誤りを分け、最小修正と波及を示す。未提供章で解決済みと推定しない。"},"examples":{"zh":"针对一篇围绕失踪相机展开的3000字原创悬疑故事，完成“故事设定与时间线核对”，按实际条件交付可用内容。","en":"Create story continuity audit for an original 3,000-word mystery about a missing camera. Use the stated constraints and deliver usable content.","ja":"消えたカメラを巡る約3000字のオリジナル短編ミステリーについて「設定・時系列の照合」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：题材、篇幅、视角、人物目标、已有情节和内容边界。已提供的信息不必重复。","en":"Provide genre, length, viewpoint, character goals, existing plot and boundaries. Do not repeat information already supplied.","ja":"ジャンル、長さ、視点、人物目的、既存筋、内容範囲を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('security-access','published','{"id":"security-access","group":"security","labels":{"zh":"越权与权限检查","en":"Authorization review","ja":"権限チェック"},"terms":["越权","RBAC","authorization","IDOR","権限"],"guidance":{"zh":"建立角色×资源×操作矩阵，检查服务端默认拒绝、对象归属和跨租户访问。给具体代码修正与允许/拒绝测试，覆盖直接请求接口；只分析授权项目，不把隐藏按钮当权限控制。","en":"Build a role/resource/action matrix. Review server-side default denial, ownership and tenant isolation. Supply targeted code fixes and allow/deny tests, including direct API requests. Stay within the authorized project; hiding buttons is not access control.","ja":"役割・資源・操作の表を作り、サーバー側の既定拒否、所有権、テナント分離を確認。直接API要求を含む許可・拒否テストと修正コードを出す。許可された範囲を守り、ボタン非表示を権限制御としない。"},"examples":{"zh":"针对一个含管理员与普通成员的团队文件应用，完成“越权与权限检查”，按实际条件交付可用内容。","en":"Create authorization review for a team file app with administrators and members. Use the stated constraints and deliver usable content.","ja":"管理者と一般メンバーがいるファイル共有アプリについて「権限チェック」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：授权范围、角色、资源归属、登录流程和脱敏代码。已提供的信息不必重复。","en":"Provide authorized scope, roles, resource ownership, login flow and redacted code. Do not repeat information already supplied.","ja":"許可範囲、役割、所有権、ログイン手順、機密除去済みコードを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('security-sessions','published','{"id":"security-sessions","group":"security","labels":{"zh":"登录与会话加固","en":"Login and session hardening","ja":"ログイン・セッション強化"},"terms":["会话","cookie","session","登录安全","セッション"],"guidance":{"zh":"画出登录、续期、退出和失效流程，检查Cookie属性、CSRF边界、过期及会话撤销。按现有框架给配置和回归用例，区分认证与授权，不自创加密算法或输出真实密钥。","en":"Map login, renewal, logout and expiry. Review cookie attributes, CSRF boundaries and session revocation. Deliver framework-specific settings and regression cases, distinguishing authentication from authorization. Do not invent cryptography or include real secrets.","ja":"ログイン、更新、ログアウト、失効を図式化し、Cookie属性、CSRF境界、セッション取消を確認。既存構成の設定と回帰例を出す。認証と認可を分け、独自暗号や実秘密値を使わない。"},"examples":{"zh":"针对一个含管理员与普通成员的团队文件应用，完成“登录与会话加固”，按实际条件交付可用内容。","en":"Create login and session hardening for a team file app with administrators and members. Use the stated constraints and deliver usable content.","ja":"管理者と一般メンバーがいるファイル共有アプリについて「ログイン・セッション強化」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：授权范围、角色、资源归属、登录流程和脱敏代码。已提供的信息不必重复。","en":"Provide authorized scope, roles, resource ownership, login flow and redacted code. Do not repeat information already supplied.","ja":"許可範囲、役割、所有権、ログイン手順、機密除去済みコードを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('security-dependencies','published','{"id":"security-dependencies","group":"security","labels":{"zh":"依赖与密钥检查","en":"Dependency and secret review","ja":"依存関係・秘密情報の確認"},"terms":["依赖漏洞","secret scan","dependency audit","依存監査"],"guidance":{"zh":"整理依赖来源、锁文件和已有扫描报告，按可达性与影响排序修复；秘密仅显示文件位置和脱敏片段。交付升级步骤、兼容检查和密钥轮换清单。未查询公告不声称发现某个CVE，不重复泄露凭据。","en":"Review dependency origins, lockfiles and supplied scan reports. Prioritize fixes by reachability and impact. Show secret locations with redacted excerpts only. Provide upgrades, compatibility checks and rotation steps; do not invent CVEs or expose credentials.","ja":"依存元、ロックファイル、提供された検査結果から到達性と影響で修正順を決める。秘密は位置と伏せ字のみ示す。更新、互換確認、鍵更新手順を出し、未確認CVEや認証情報を出さない。"},"examples":{"zh":"针对一个含管理员与普通成员的团队文件应用，完成“依赖与密钥检查”，按实际条件交付可用内容。","en":"Create dependency and secret review for a team file app with administrators and members. Use the stated constraints and deliver usable content.","ja":"管理者と一般メンバーがいるファイル共有アプリについて「依存関係・秘密情報の確認」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：授权范围、角色、资源归属、登录流程和脱敏代码。已提供的信息不必重复。","en":"Provide authorized scope, roles, resource ownership, login flow and redacted code. Do not repeat information already supplied.","ja":"許可範囲、役割、所有権、ログイン手順、機密除去済みコードを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('performance-profile','published','{"id":"performance-profile","group":"performance","labels":{"zh":"性能瓶颈定位","en":"Bottleneck profiling","ja":"ボトルネック調査"},"terms":["性能瓶颈","profiling","latency","ボトルネック"],"guidance":{"zh":"先定义可重复负载与基线，再分解网络、数据库、CPU和渲染耗时。给采样步骤、证据表和按收益排序的最小修改，说明如何同条件复测P50/P95。没有测量数据时只给实验方案，不编造提升百分比。","en":"Define a repeatable workload and baseline. Separate network, database, CPU and rendering time. Deliver profiling steps, evidence and prioritized minimal changes, then comparable P50/P95 checks. Without measurements, provide experiments rather than invented speedups.","ja":"再現負荷と基準を定め、通信、DB、CPU、描画の時間を分解。計測手順、証拠、効果順の最小変更と同条件のP50/P95再計測を示す。測定なしで改善率を作らない。"},"examples":{"zh":"针对一个高峰期列表查询变慢的商品服务，完成“性能瓶颈定位”，按实际条件交付可用内容。","en":"Create bottleneck profiling for a product service whose list queries slow down at peak load. Use the stated constraints and deliver usable content.","ja":"ピーク時に一覧検索が遅くなる商品サービスについて「ボトルネック調査」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：运行环境、数据规模、基线耗时、分析记录和延迟目标。已提供的信息不必重复。","en":"Provide runtime, data volume, baseline timings, profiles and latency targets. Do not repeat information already supplied.","ja":"環境、データ量、基準時間、計測記録、遅延目標を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('performance-cache','published','{"id":"performance-cache","group":"performance","labels":{"zh":"缓存设计与失效","en":"Caching and invalidation","ja":"キャッシュ設計・失効"},"terms":["缓存","cache","invalidation","キャッシュ"],"guidance":{"zh":"明确缓存对象、键、租户边界、TTL和一致性要求，提供读写路径、主动失效与穿透保护实现。覆盖空值、热点、旧值和更新竞态测试，解释缓存关闭后的行为，不把缓存当作唯一数据源。","en":"Define cached objects, keys, tenant boundaries, TTL and consistency. Implement read/write paths, invalidation and miss protection. Test nulls, hot keys, stale data and update races. Describe behavior with caching disabled; preserve the authoritative data source.","ja":"対象、キー、テナント境界、TTL、整合性を定義し、読み書きの経路、失効、ミス集中対策を実装。空値、集中キー、古い値、更新競合をテストし、無効時の動作と正本を明確にする。"},"examples":{"zh":"针对一个高峰期列表查询变慢的商品服务，完成“缓存设计与失效”，按实际条件交付可用内容。","en":"Create caching and invalidation for a product service whose list queries slow down at peak load. Use the stated constraints and deliver usable content.","ja":"ピーク時に一覧検索が遅くなる商品サービスについて「キャッシュ設計・失効」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：运行环境、数据规模、基线耗时、分析记录和延迟目标。已提供的信息不必重复。","en":"Provide runtime, data volume, baseline timings, profiles and latency targets. Do not repeat information already supplied.","ja":"環境、データ量、基準時間、計測記録、遅延目標を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('performance-race','published','{"id":"performance-race","group":"performance","labels":{"zh":"竞态与并发错误","en":"Race conditions","ja":"競合状態の修正"},"terms":["竞态","race condition","deadlock","并发","競合"],"guidance":{"zh":"用事件时间线复现共享状态冲突，识别事务、锁或异步取消的边界。给最小修复及并发测试，覆盖重复提交、超时、死锁重试和取消后的写入。比较吞吐与一致性的取舍，不用任意等待掩盖竞态。","en":"Reproduce shared-state conflicts with an event timeline. Locate transaction, lock and cancellation boundaries. Supply a minimal fix and concurrent tests for duplicates, timeouts, deadlock retries and post-cancellation writes. Explain throughput/consistency tradeoffs; do not hide races with sleeps.","ja":"時系列で共有状態の競合を再現し、トランザクション、ロック、取消境界を特定。重複、時間切れ、デッドロック再試行、取消後書込みの修正と並行テストを出す。待機で競合を隠さない。"},"examples":{"zh":"针对一个高峰期列表查询变慢的商品服务，完成“竞态与并发错误”，按实际条件交付可用内容。","en":"Create race conditions for a product service whose list queries slow down at peak load. Use the stated constraints and deliver usable content.","ja":"ピーク時に一覧検索が遅くなる商品サービスについて「競合状態の修正」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：运行环境、数据规模、基线耗时、分析记录和延迟目标。已提供的信息不必重复。","en":"Provide runtime, data volume, baseline timings, profiles and latency targets. Do not repeat information already supplied.","ja":"環境、データ量、基準時間、計測記録、遅延目標を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('mobile-navigation','published','{"id":"mobile-navigation","group":"mobile","labels":{"zh":"移动页面与导航","en":"Mobile screens and navigation","ja":"画面・ナビゲーション"},"terms":["移动端","navigation","Flutter","React Native","画面遷移"],"guidance":{"zh":"按用户流程定义页面、导航参数、返回栈和深链行为，交付目标框架的组件与路由代码。覆盖加载、空、错误、安全区、键盘遮挡和系统返回，给小屏与大字号验收步骤。","en":"Define screens, navigation parameters, back stack and deep links from the user flow. Deliver components and routes in the chosen framework. Handle loading, empty/error states, safe areas, keyboard overlap and system back, with small-screen and large-text checks.","ja":"画面、遷移引数、履歴、ディープリンクを定義し、指定構成の部品とルートを実装。読込、空、失敗、セーフエリア、キーボード、戻る操作を扱い、小画面と文字拡大の確認を添える。"},"examples":{"zh":"针对需要弱网可用的活动报名应用，完成“移动页面与导航”，按实际条件交付可用内容。","en":"Create mobile screens and navigation for an event registration app that must work on unreliable networks. Use the stated constraints and deliver usable content.","ja":"不安定な回線でも使うイベント申込アプリについて「画面・ナビゲーション」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：平台与框架版本、页面流程、设备范围、网络条件和代码。已提供的信息不必重复。","en":"Provide platform/framework versions, flows, devices, network conditions and code. Do not repeat information already supplied.","ja":"OS・構成の版、画面遷移、端末範囲、通信条件、コードを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('mobile-offline','published','{"id":"mobile-offline","group":"mobile","labels":{"zh":"离线存储与同步","en":"Offline storage and sync","ja":"オフライン保存・同期"},"terms":["离线","offline","sync conflict","同期"],"guidance":{"zh":"定义本地与服务端数据模型、待同步队列、冲突归并和删除标记。提供断网写入、重连重试及状态提示代码，处理重复上传和时钟差异。列数据迁移与容量边界，不默认最后写入一定正确。","en":"Define local/server models, pending queues, conflict resolution and tombstones. Implement offline writes, reconnect retries and visible sync status. Handle duplicate uploads and clock skew. Include migrations and storage limits; do not assume last-write-wins is always valid.","ja":"ローカル・サーバーのモデル、待機列、競合解決、削除印を定義。切断時保存、再接続、同期表示を実装し、二重送信と時刻差を扱う。移行と容量も示し、後勝ちを無条件に採用しない。"},"examples":{"zh":"针对需要弱网可用的活动报名应用，完成“离线存储与同步”，按实际条件交付可用内容。","en":"Create offline storage and sync for an event registration app that must work on unreliable networks. Use the stated constraints and deliver usable content.","ja":"不安定な回線でも使うイベント申込アプリについて「オフライン保存・同期」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：平台与框架版本、页面流程、设备范围、网络条件和代码。已提供的信息不必重复。","en":"Provide platform/framework versions, flows, devices, network conditions and code. Do not repeat information already supplied.","ja":"OS・構成の版、画面遷移、端末範囲、通信条件、コードを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('mobile-permissions','published','{"id":"mobile-permissions","group":"mobile","labels":{"zh":"权限申请与通知","en":"Permissions and notifications","ja":"権限要求・通知"},"terms":["推送","permission","push notification","通知"],"guidance":{"zh":"把每项设备权限对应到用户可理解的功能与请求时机，给允许、拒绝、永久拒绝和撤回分支。设计通知载荷、去重、跳转和静默处理，按目标平台核对支持能力，不假装已取得推送凭据。","en":"Map device permissions to understandable features and request timing. Implement granted, denied, permanently denied and revoked states. Design notification payloads, deduplication, routing and silent handling. Verify target-platform support without claiming push credentials are available.","ja":"端末権限を機能と要求時点に対応させ、許可、拒否、再要求不可、取消の分岐を実装。通知内容、重複除去、遷移、無音処理を設計。対象OSの対応を確認し、資格情報の取得を装わない。"},"examples":{"zh":"针对需要弱网可用的活动报名应用，完成“权限申请与通知”，按实际条件交付可用内容。","en":"Create permissions and notifications for an event registration app that must work on unreliable networks. Use the stated constraints and deliver usable content.","ja":"不安定な回線でも使うイベント申込アプリについて「権限要求・通知」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：平台与框架版本、页面流程、设备范围、网络条件和代码。已提供的信息不必重复。","en":"Provide platform/framework versions, flows, devices, network conditions and code. Do not repeat information already supplied.","ja":"OS・構成の版、画面遷移、端末範囲、通信条件、コードを補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('automation-rename','published','{"id":"automation-rename","group":"automation","labels":{"zh":"批量文件整理","en":"Batch file organization","ja":"ファイル一括整理"},"terms":["批量重命名","rename files","文件整理","一括改名"],"guidance":{"zh":"生成先预览后执行的重命名或归档脚本，校验目标路径与冲突，保留扩展名和可回滚映射。覆盖Unicode、空格、同名、只读文件和中途失败，不默认删除重复内容；输出逐项操作日志。","en":"Create a dry-run-first rename/archive script with path validation, collision handling, extensions and rollback mapping. Cover Unicode, spaces, duplicate names, read-only files and partial failure. Do not delete duplicates by default; log each operation.","ja":"プレビュー後に実行する改名・整理スクリプトを作り、パス、衝突、拡張子、復元対応を確認。Unicode、空白、同名、読取専用、中断を扱い、既定で重複削除せず操作ログを出す。"},"examples":{"zh":"针对一个含重复文件与混合命名的资料目录，完成“批量文件整理”，按实际条件交付可用内容。","en":"Create batch file organization for a document directory with duplicates and inconsistent names. Use the stated constraints and deliver usable content.","ja":"重複と命名揺れがある資料フォルダーについて「ファイル一括整理」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：操作系统、路径示例、输入输出规则、保留要求和脚本语言。已提供的信息不必重复。","en":"Provide OS, sample paths, input/output rules, retention needs and language. Do not repeat information already supplied.","ja":"OS、パス例、入出力規則、保存条件、言語を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('automation-convert','published','{"id":"automation-convert","group":"automation","labels":{"zh":"文档批量转换","en":"Batch document conversion","ja":"文書一括変換"},"terms":["批量转换","CSV","JSON","conversion","一括変換"],"guidance":{"zh":"明确编码、分隔符、日期、空值和字段映射，提供保留原文件的转换脚本。逐文件报告成功与失败，核对行数、必填字段及输出可解析性；不能支持的格式说明依赖，不把改扩展名当转换。","en":"Specify encoding, delimiters, dates, nulls and field mapping. Preserve originals in a conversion script with per-file success/failure reports. Check row counts, required fields and parseability. Explain dependencies for unsupported formats; renaming extensions is not conversion.","ja":"文字コード、区切り、日付、空値、項目対応を指定し、原本を保つ変換を実装。ファイル別結果と件数、必須項目、解析可否を確認。必要依存を示し、拡張子変更を変換としない。"},"examples":{"zh":"针对一个含重复文件与混合命名的资料目录，完成“文档批量转换”，按实际条件交付可用内容。","en":"Create batch document conversion for a document directory with duplicates and inconsistent names. Use the stated constraints and deliver usable content.","ja":"重複と命名揺れがある資料フォルダーについて「文書一括変換」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：操作系统、路径示例、输入输出规则、保留要求和脚本语言。已提供的信息不必重复。","en":"Provide OS, sample paths, input/output rules, retention needs and language. Do not repeat information already supplied.","ja":"OS、パス例、入出力規則、保存条件、言語を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('automation-jobs','published','{"id":"automation-jobs","group":"automation","labels":{"zh":"定时任务与失败恢复","en":"Scheduled jobs and recovery","ja":"定期処理・復旧"},"terms":["定时脚本","scheduled job","cron","定期処理"],"guidance":{"zh":"交付目标系统的调度配置、时区、互斥锁、超时和幂等实现，说明重启后补跑策略。提供日志轮转、失败通知接口和恢复步骤，密钥走环境变量；先给可测试配置，不声称已创建后台任务。","en":"Deliver scheduler configuration, timezone, locking, timeouts and idempotency for the target OS. Define missed-run behavior after restart, log rotation, failure hooks and recovery. Use environment variables for secrets. Provide testable configuration without claiming a job was installed.","ja":"対象OSの時刻設定、タイムゾーン、排他、時間制限、冪等性を実装。再起動後の補完、ログ循環、失敗通知、復旧を定義。秘密は環境変数にし、設定を実際に登録済みとしない。"},"examples":{"zh":"针对一个含重复文件与混合命名的资料目录，完成“定时任务与失败恢复”，按实际条件交付可用内容。","en":"Create scheduled jobs and recovery for a document directory with duplicates and inconsistent names. Use the stated constraints and deliver usable content.","ja":"重複と命名揺れがある資料フォルダーについて「定期処理・復旧」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：操作系统、路径示例、输入输出规则、保留要求和脚本语言。已提供的信息不必重复。","en":"Provide OS, sample paths, input/output rules, retention needs and language. Do not repeat information already supplied.","ja":"OS、パス例、入出力規則、保存条件、言語を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('git-conflicts','published','{"id":"git-conflicts","group":"git","labels":{"zh":"合并冲突分析","en":"Merge conflict resolution","ja":"マージ競合の解決"},"terms":["合并冲突","merge conflict","rebase","マージ"],"guidance":{"zh":"解释双方修改意图与共同基线，按业务行为给合并后的片段及原因。列继续合并前的检查和测试，保留未提交工作；信息不足先读取状态，不默认选全部ours/theirs或强制推送。","en":"Explain both changes and their common base. Resolve snippets according to intended behavior, with rationale and checks before continuing. Preserve uncommitted work. Inspect status when context is missing; do not default to blanket ours/theirs or force-push.","ja":"双方の意図と共通基点を説明し、期待動作に沿う統合コードと理由を出す。続行前の確認とテストを示し未コミット作業を保つ。全面ours/theirsや強制pushを既定にしない。"},"examples":{"zh":"针对多人修改同一功能且准备发布的代码库，完成“合并冲突分析”，按实际条件交付可用内容。","en":"Create merge conflict resolution for a repository with concurrent changes preparing a release. Use the stated constraints and deliver usable content.","ja":"複数人が同時変更し公開準備中のリポジトリについて「マージ競合の解決」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：分支关系、工作区状态、冲突片段、团队约定和发布目标。已提供的信息不必重复。","en":"Provide branch relationships, working-tree state, conflict excerpts, conventions and release target. Do not repeat information already supplied.","ja":"ブランチ関係、作業状態、競合箇所、規約、公開先を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('git-review','published','{"id":"git-review","group":"git","labels":{"zh":"PR 说明与评审","en":"Pull request description and review","ja":"PR説明・レビュー"},"terms":["PR描述","pull request","code review","PRレビュー"],"guidance":{"zh":"从实际差异写问题、行为变化、影响范围和验证证据，再按严重程度列可定位的缺陷。评论给文件位置、触发条件与修正建议，区分阻塞问题和可选建议；不把没有运行的测试写成通过。","en":"Use the actual diff to describe the problem, behavior change, impact and validation. Rank actionable defects with file locations, triggers and fixes. Separate blockers from suggestions. Never describe unrun tests as passed.","ja":"実差分から問題、動作変更、影響、検証を書く。欠陥に位置、発生条件、修正案、優先度を付け、必須と提案を分ける。未実行テストを合格と書かない。"},"examples":{"zh":"针对多人修改同一功能且准备发布的代码库，完成“PR 说明与评审”，按实际条件交付可用内容。","en":"Create pull request description and review for a repository with concurrent changes preparing a release. Use the stated constraints and deliver usable content.","ja":"複数人が同時変更し公開準備中のリポジトリについて「PR説明・レビュー」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：分支关系、工作区状态、冲突片段、团队约定和发布目标。已提供的信息不必重复。","en":"Provide branch relationships, working-tree state, conflict excerpts, conventions and release target. Do not repeat information already supplied.","ja":"ブランチ関係、作業状態、競合箇所、規約、公開先を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('git-release','published','{"id":"git-release","group":"git","labels":{"zh":"版本说明与迁移指南","en":"Release notes and migration","ja":"リリースノート・移行案内"},"terms":["版本说明","changelog","migration guide","変更履歴"],"guidance":{"zh":"根据已提供提交和议题归并用户可感知的变化，单列破坏性变更、迁移步骤和已知限制。给升级前后示例与回退条件，关联真实来源；不把提交数量当价值，也不虚构发布日期。","en":"Group supplied commits and issues into user-visible changes. Separate breaking changes, migration steps and known limitations. Provide before/after examples and rollback conditions linked to actual evidence. Do not equate commit counts with value or invent release dates.","ja":"提供コミットと課題を利用者視点で整理し、破壊的変更、移行、制限を分ける。前後例と復旧条件を実根拠に結び付け、件数を価値とせず公開日を作らない。"},"examples":{"zh":"针对多人修改同一功能且准备发布的代码库，完成“版本说明与迁移指南”，按实际条件交付可用内容。","en":"Create release notes and migration for a repository with concurrent changes preparing a release. Use the stated constraints and deliver usable content.","ja":"複数人が同時変更し公開準備中のリポジトリについて「リリースノート・移行案内」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：分支关系、工作区状态、冲突片段、团队约定和发布目标。已提供的信息不必重复。","en":"Provide branch relationships, working-tree state, conflict excerpts, conventions and release target. Do not repeat information already supplied.","ja":"ブランチ関係、作業状態、競合箇所、規約、公開先を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('integration-client','published','{"id":"integration-client","group":"integration","labels":{"zh":"API 客户端封装","en":"API client wrapper","ja":"APIクライアント実装"},"terms":["SDK封装","API client","rate limit","APIクライアント"],"guidance":{"zh":"依官方文档封装鉴权、超时、分页、错误类型和速率限制处理，给类型化请求响应与调用例。只对可安全重试的操作退避重试，脱敏日志；缺少端点或版本时明确待核实，不编造SDK方法。","en":"Build authentication, timeouts, pagination, typed errors and rate-limit handling from official docs, with typed requests and examples. Retry only safe operations with backoff and redact logs. Flag missing endpoints or versions instead of inventing SDK methods.","ja":"公式資料に基づき認証、時間切れ、ページ分割、型付きエラー、制限対応を実装。安全な操作だけ再試行しログを伏せる。不明な経路や版は確認待ちとしSDKメソッドを作らない。"},"examples":{"zh":"针对需要同步外部订单状态的内部工具，完成“API 客户端封装”，按实际条件交付可用内容。","en":"Create api client wrapper for an internal tool synchronizing external order status. Use the stated constraints and deliver usable content.","ja":"外部の注文状態を同期する社内ツールについて「APIクライアント実装」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：官方接口文档、鉴权方式、限额、错误样例和同步方向。已提供的信息不必重复。","en":"Provide official API docs, authentication, limits, error samples and sync direction. Do not repeat information already supplied.","ja":"公式API資料、認証、制限、失敗例、同期方向を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('integration-webhook','published','{"id":"integration-webhook","group":"integration","labels":{"zh":"Webhook 验签与重放","en":"Webhook verification and replay","ja":"Webhook検証・再送"},"terms":["webhook","验签","signature","署名検証"],"guidance":{"zh":"给原始请求体验签、时间窗、事件ID去重和异步处理代码，说明快速响应与处理失败重试。覆盖重复、乱序、非法签名和重放测试；签名算法按服务商文档，不用普通字符串比较替代安全校验。","en":"Implement signature verification over the raw body, timestamp windows, event deduplication and queued processing. Define quick acknowledgement and retries. Test duplicates, out-of-order events, invalid signatures and replay. Follow provider documentation and use appropriate secure verification.","ja":"生本文の署名、時間窓、イベントID重複除去、非同期処理を実装。早期応答と再試行を定め、重複、順序逆転、不正署名、再送をテスト。方式は提供元資料に従う。"},"examples":{"zh":"针对需要同步外部订单状态的内部工具，完成“Webhook 验签与重放”，按实际条件交付可用内容。","en":"Create webhook verification and replay for an internal tool synchronizing external order status. Use the stated constraints and deliver usable content.","ja":"外部の注文状態を同期する社内ツールについて「Webhook検証・再送」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：官方接口文档、鉴权方式、限额、错误样例和同步方向。已提供的信息不必重复。","en":"Provide official API docs, authentication, limits, error samples and sync direction. Do not repeat information already supplied.","ja":"公式API資料、認証、制限、失敗例、同期方向を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('integration-mapping','published','{"id":"integration-mapping","group":"integration","labels":{"zh":"系统数据映射与对账","en":"System mapping and reconciliation","ja":"システム間対応・照合"},"terms":["数据对账","reconciliation","sync mapping","データ照合"],"guidance":{"zh":"建立源字段、目标字段、转换、枚举及空值对应表，定义主键关联和冲突来源优先级。提供增量同步游标、对账查询、差异报告和补偿步骤；保留审计信息，不静默覆盖不一致记录。","en":"Map source/target fields, conversions, enums and null handling. Define identity links and conflict precedence. Deliver incremental cursors, reconciliation queries, discrepancy reports and recovery steps. Preserve audit data rather than silently overwriting inconsistencies.","ja":"元・先の項目、変換、列挙、空値を対応させ、識別子と競合優先順位を定義。差分カーソル、照合クエリ、差異報告、補完手順を出し、監査を残して不一致を黙って上書きしない。"},"examples":{"zh":"针对需要同步外部订单状态的内部工具，完成“系统数据映射与对账”，按实际条件交付可用内容。","en":"Create system mapping and reconciliation for an internal tool synchronizing external order status. Use the stated constraints and deliver usable content.","ja":"外部の注文状態を同期する社内ツールについて「システム間対応・照合」を作成してください。指定条件に合わせて使える内容を出してください。"},"questions":{"zh":"请补充：官方接口文档、鉴权方式、限额、错误样例和同步方向。已提供的信息不必重复。","en":"Provide official API docs, authentication, limits, error samples and sync direction. Do not repeat information already supplied.","ja":"公式API資料、認証、制限、失敗例、同期方向を補足してください。記載済みの情報は繰り返し不要です。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('security-focused-upload','published','{"id":"security-focused-upload","group":"security","labels":{"zh":"文件上传安全","en":"File upload security","ja":"アップロード検証"},"terms":["文件上传安全","File upload security","アップロード検証","upload"],"guidance":{"zh":"核对扩展名、实际类型、大小、存储路径和下载权限；交付校验代码及伪装类型、超限、路径穿越测试，上传内容不可默认执行。","en":"Validate extension, actual type, size, storage path and access. Supply code and spoofed-type, oversized and traversal tests; uploaded content must not execute by default.","ja":"拡張子、実形式、容量、保存先、権限を検証。形式偽装、超過、パス逸脱のテストとコードを出し、内容を自動実行しない。"},"examples":{"zh":"请根据我提供的材料完成：文件上传安全. 核对扩展名、实际类型、大小、存储路径和下载权限；交付校验代码及伪装类型、超限、路径穿越测试，上传内容不可默认执行","en":"Using my supplied material, deliver: File upload security. Validate extension, actual type, size, storage path and access. Supply code and spoofed-type, oversized and traversal tests; uploaded content must not execute by default.","ja":"提供資料に基づき作成してください：アップロード検証. 拡張子、実形式、容量、保存先、権限を検証"},"questions":{"zh":"请提供与“文件上传安全”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For file upload security, provide source material, target software/use case and fixed constraints.","ja":"「アップロード検証」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('security-focused-redaction','published','{"id":"security-focused-redaction","group":"security","labels":{"zh":"日志脱敏与隐私","en":"Log redaction","ja":"ログの機密除去"},"terms":["日志脱敏与隐私","Log redaction","ログの機密除去","redaction"],"guidance":{"zh":"列出日志中必要字段与不该记录的字段，给结构化脱敏实现和嵌套对象测试；保留排错线索，禁止打印密码、令牌和完整身份信息。","en":"Define necessary and prohibited log fields. Implement structured redaction with nested-object tests while retaining debugging signals. Never print passwords, tokens or full identity data.","ja":"必要・禁止項目を分け、入れ子も扱う機密除去とテストを実装。調査情報を残し、パスワード、トークン、本人情報を出さない。"},"examples":{"zh":"请根据我提供的材料完成：日志脱敏与隐私. 列出日志中必要字段与不该记录的字段，给结构化脱敏实现和嵌套对象测试；保留排错线索，禁止打印密码、令牌和完整身份信息","en":"Using my supplied material, deliver: Log redaction. Define necessary and prohibited log fields. Implement structured redaction with nested-object tests while retaining debugging signals. Never print passwords, tokens or full identity data.","ja":"提供資料に基づき作成してください：ログの機密除去. 必要・禁止項目を分け、入れ子も扱う機密除去とテストを実装"},"questions":{"zh":"请提供与“日志脱敏与隐私”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For log redaction, provide source material, target software/use case and fixed constraints.","ja":"「ログの機密除去」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('security-focused-validation','published','{"id":"security-focused-validation","group":"security","labels":{"zh":"输入校验与错误边界","en":"Input validation boundaries","ja":"入力検証の境界"},"terms":["输入校验与错误边界","Input validation boundaries","入力検証の境界","validation"],"guidance":{"zh":"给信任边界、字段规则、长度与枚举限制，区分校验和输出转义。交付服务端实现及空值、超长、嵌套异常测试，不只靠前端限制。","en":"Define trust boundaries, field rules, lengths and enums. Separate validation from output escaping. Deliver server-side checks for nulls, oversized inputs and malformed nesting, not frontend limits alone.","ja":"信頼境界、項目、長さ、列挙を定義。検証と出力エスケープを分け、空値、超長、異常入れ子をサーバーでテストする。"},"examples":{"zh":"请根据我提供的材料完成：输入校验与错误边界. 给信任边界、字段规则、长度与枚举限制，区分校验和输出转义","en":"Using my supplied material, deliver: Input validation boundaries. Define trust boundaries, field rules, lengths and enums. Separate validation from output escaping. Deliver server-side checks for nulls, oversized inputs and malformed nesting, not frontend limits alone.","ja":"提供資料に基づき作成してください：入力検証の境界. 信頼境界、項目、長さ、列挙を定義"},"questions":{"zh":"请提供与“输入校验与错误边界”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For input validation boundaries, provide source material, target software/use case and fixed constraints.","ja":"「入力検証の境界」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('performance-focused-memory','published','{"id":"performance-focused-memory","group":"performance","labels":{"zh":"内存泄漏定位","en":"Memory leak investigation","ja":"メモリリーク調査"},"terms":["内存泄漏定位","Memory leak investigation","メモリリーク調査","memory"],"guidance":{"zh":"给可重复的内存增长实验，检查监听器、定时器、缓存和引用释放。按堆快照证据给修复与稳定性复测；没有快照只列假设，不把正常缓存判为泄漏。","en":"Design a repeatable growth experiment and inspect listeners, timers, caches and retained references. Base fixes on heap evidence and retest stability; distinguish normal caching from leaks.","ja":"再現実験でリスナー、タイマー、キャッシュ、参照解放を調べる。ヒープ証拠に基づき修正・再計測し、通常キャッシュを漏れと断定しない。"},"examples":{"zh":"请根据我提供的材料完成：内存泄漏定位. 给可重复的内存增长实验，检查监听器、定时器、缓存和引用释放","en":"Using my supplied material, deliver: Memory leak investigation. Design a repeatable growth experiment and inspect listeners, timers, caches and retained references. Base fixes on heap evidence and retest stability; distinguish normal caching from leaks.","ja":"提供資料に基づき作成してください：メモリリーク調査. 再現実験でリスナー、タイマー、キャッシュ、参照解放を調べる"},"questions":{"zh":"请提供与“内存泄漏定位”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For memory leak investigation, provide source material, target software/use case and fixed constraints.","ja":"「メモリリーク調査」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('performance-focused-query','published','{"id":"performance-focused-query","group":"performance","labels":{"zh":"慢查询与执行计划","en":"Slow query analysis","ja":"遅いクエリの解析"},"terms":["慢查询与执行计划","Slow query analysis","遅いクエリの解析","query"],"guidance":{"zh":"根据实际SQL与执行计划解释扫描、连接和排序成本，提出索引与查询改写。给等价性、读写代价和前后耗时核对，不能只凭字段名猜最优索引。","en":"Explain scans, joins and sorts from actual SQL and plans. Propose indexes and rewrites with equivalence, write-cost and timing checks; field names alone cannot prove the best index.","ja":"実SQLと計画から走査、結合、ソートを説明。索引・書換えに同値性、書込費用、時間比較を添え、名前だけで最適としない。"},"examples":{"zh":"请根据我提供的材料完成：慢查询与执行计划. 根据实际SQL与执行计划解释扫描、连接和排序成本，提出索引与查询改写","en":"Using my supplied material, deliver: Slow query analysis. Explain scans, joins and sorts from actual SQL and plans. Propose indexes and rewrites with equivalence, write-cost and timing checks; field names alone cannot prove the best index.","ja":"提供資料に基づき作成してください：遅いクエリの解析. 実SQLと計画から走査、結合、ソートを説明"},"questions":{"zh":"请提供与“慢查询与执行计划”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For slow query analysis, provide source material, target software/use case and fixed constraints.","ja":"「遅いクエリの解析」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('performance-focused-render','published','{"id":"performance-focused-render","group":"performance","labels":{"zh":"前端渲染卡顿","en":"UI rendering jank","ja":"描画の引っ掛かり"},"terms":["前端渲染卡顿","UI rendering jank","描画の引っ掛かり","render"],"guidance":{"zh":"用性能记录区分长任务、布局抖动与重复渲染，给最小组件修正。验证输入响应、滚动和低端设备表现，不为优化引入过度缓存或破坏可访问性。","en":"Use traces to distinguish long tasks, layout thrashing and redundant renders. Make minimal fixes and verify input, scroll and slower-device behavior without excessive caching or accessibility regressions.","ja":"記録から長時間処理、レイアウト反復、再描画を分け最小修正。入力、スクロール、低性能端末を確認し、過剰キャッシュや利用障害を避ける。"},"examples":{"zh":"请根据我提供的材料完成：前端渲染卡顿. 用性能记录区分长任务、布局抖动与重复渲染，给最小组件修正","en":"Using my supplied material, deliver: UI rendering jank. Use traces to distinguish long tasks, layout thrashing and redundant renders. Make minimal fixes and verify input, scroll and slower-device behavior without excessive caching or accessibility regressions.","ja":"提供資料に基づき作成してください：描画の引っ掛かり. 記録から長時間処理、レイアウト反復、再描画を分け最小修正"},"questions":{"zh":"请提供与“前端渲染卡顿”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For ui rendering jank, provide source material, target software/use case and fixed constraints.","ja":"「描画の引っ掛かり」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('mobile-focused-forms','published','{"id":"mobile-focused-forms","group":"mobile","labels":{"zh":"移动表单与键盘","en":"Mobile forms and keyboards","ja":"モバイルフォーム・キーボード"},"terms":["移动表单与键盘","Mobile forms and keyboards","モバイルフォーム・キーボード","forms"],"guidance":{"zh":"为实际字段设置键盘、焦点顺序、错误文案与提交状态，处理键盘遮挡和离开提醒。给目标框架代码与辅助技术操作检查，保留已输入内容。","en":"Set keyboard types, focus order, errors and submission states per field. Handle occlusion and leaving warnings, preserving input. Supply framework code and assistive-technology checks.","ja":"項目別キーボード、焦点、エラー、送信状態を設定。遮蔽と離脱確認を扱い入力を保持し、コードと支援技術確認を出す。"},"examples":{"zh":"请根据我提供的材料完成：移动表单与键盘. 为实际字段设置键盘、焦点顺序、错误文案与提交状态，处理键盘遮挡和离开提醒","en":"Using my supplied material, deliver: Mobile forms and keyboards. Set keyboard types, focus order, errors and submission states per field. Handle occlusion and leaving warnings, preserving input. Supply framework code and assistive-technology checks.","ja":"提供資料に基づき作成してください：モバイルフォーム・キーボード. 項目別キーボード、焦点、エラー、送信状態を設定"},"questions":{"zh":"请提供与“移动表单与键盘”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For mobile forms and keyboards, provide source material, target software/use case and fixed constraints.","ja":"「モバイルフォーム・キーボード」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('mobile-focused-images','published','{"id":"mobile-focused-images","group":"mobile","labels":{"zh":"移动图片加载","en":"Mobile image loading","ja":"モバイル画像読込み"},"terms":["移动图片加载","Mobile image loading","モバイル画像読込み","images"],"guidance":{"zh":"按屏幕尺寸设计缩略图、缓存、占位与失败重试，避免一次解码大图。给取消过期请求、内存释放和列表滚动测试，保留原图下载的明确入口。","en":"Design thumbnails, caching, placeholders and retries for screen size. Avoid full-resolution decoding, cancel stale requests and test memory release and scrolling. Keep original downloads explicit.","ja":"画面に合う縮小図、キャッシュ、仮表示、再試行を設計。大画像一括展開を避け、旧要求取消、解放、スクロールを確認する。"},"examples":{"zh":"请根据我提供的材料完成：移动图片加载. 按屏幕尺寸设计缩略图、缓存、占位与失败重试，避免一次解码大图","en":"Using my supplied material, deliver: Mobile image loading. Design thumbnails, caching, placeholders and retries for screen size. Avoid full-resolution decoding, cancel stale requests and test memory release and scrolling. Keep original downloads explicit.","ja":"提供資料に基づき作成してください：モバイル画像読込み. 画面に合う縮小図、キャッシュ、仮表示、再試行を設計"},"questions":{"zh":"请提供与“移动图片加载”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For mobile image loading, provide source material, target software/use case and fixed constraints.","ja":"「モバイル画像読込み」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('mobile-focused-deeplink','published','{"id":"mobile-focused-deeplink","group":"mobile","labels":{"zh":"深链与登录返回","en":"Deep links and login return","ja":"ディープリンク・ログイン復帰"},"terms":["深链与登录返回","Deep links and login return","ディープリンク・ログイン復帰","deeplink"],"guidance":{"zh":"定义合法链接、参数校验和未登录重定向，登录后回到原目标。覆盖不存在资源、过期链接和外部链接，防开放重定向，不假设客户端参数可信。","en":"Validate allowed links and parameters, preserve the destination through login, and handle missing resources and expired links. Prevent open redirects; client parameters are not trusted.","ja":"許可リンクと引数を検証しログイン後の目的地を保持。対象なし、期限切れ、外部遷移を扱い、無制限リダイレクトを防ぐ。"},"examples":{"zh":"请根据我提供的材料完成：深链与登录返回. 定义合法链接、参数校验和未登录重定向，登录后回到原目标","en":"Using my supplied material, deliver: Deep links and login return. Validate allowed links and parameters, preserve the destination through login, and handle missing resources and expired links. Prevent open redirects; client parameters are not trusted.","ja":"提供資料に基づき作成してください：ディープリンク・ログイン復帰. 許可リンクと引数を検証しログイン後の目的地を保持"},"questions":{"zh":"请提供与“深链与登录返回”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For deep links and login return, provide source material, target software/use case and fixed constraints.","ja":"「ディープリンク・ログイン復帰」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('automation-focused-encoding','published','{"id":"automation-focused-encoding","group":"automation","labels":{"zh":"乱码与编码修复","en":"Text encoding repair","ja":"文字化けの修正"},"terms":["乱码与编码修复","Text encoding repair","文字化けの修正","encoding"],"guidance":{"zh":"检查原始字节、声明编码和解码路径，保留原文件后给转换脚本与抽样核对。无法恢复的字符标记未知，不能通过重复转码掩盖数据丢失。","en":"Inspect bytes, declared encoding and decoding paths. Preserve originals and provide conversion plus sample checks. Mark unrecoverable characters; repeated transcoding cannot restore lost data.","ja":"バイト、宣言、復号経路を確認し原本を保った変換と抽出照合を出す。復元不能文字は不明とし再変換で損失を隠さない。"},"examples":{"zh":"请根据我提供的材料完成：乱码与编码修复. 检查原始字节、声明编码和解码路径，保留原文件后给转换脚本与抽样核对","en":"Using my supplied material, deliver: Text encoding repair. Inspect bytes, declared encoding and decoding paths. Preserve originals and provide conversion plus sample checks. Mark unrecoverable characters; repeated transcoding cannot restore lost data.","ja":"提供資料に基づき作成してください：文字化けの修正. バイト、宣言、復号経路を確認し原本を保った変換と抽出照合を出す"},"questions":{"zh":"请提供与“乱码与编码修复”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For text encoding repair, provide source material, target software/use case and fixed constraints.","ja":"「文字化けの修正」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('automation-focused-dedupe','published','{"id":"automation-focused-dedupe","group":"automation","labels":{"zh":"重复文件识别预览","en":"Duplicate file preview","ja":"重複ファイルの確認"},"terms":["重复文件识别预览","Duplicate file preview","重複ファイルの確認","dedupe"],"guidance":{"zh":"按文件大小与内容哈希分组，输出路径、时间和保留候选。默认仅生成报告，分开完全重复与近似文件；处理符号链接和权限错误，不自动删除。","en":"Group by size and content hash, listing paths, dates and retention candidates. Default to a report, distinguish exact from similar files, and handle symlinks/permissions without automatic deletion.","ja":"容量と内容ハッシュで分類し、パス、日時、保存候補を報告。完全一致と類似を分け、リンクと権限を扱い自動削除しない。"},"examples":{"zh":"请根据我提供的材料完成：重复文件识别预览. 按文件大小与内容哈希分组，输出路径、时间和保留候选","en":"Using my supplied material, deliver: Duplicate file preview. Group by size and content hash, listing paths, dates and retention candidates. Default to a report, distinguish exact from similar files, and handle symlinks/permissions without automatic deletion.","ja":"提供資料に基づき作成してください：重複ファイルの確認. 容量と内容ハッシュで分類し、パス、日時、保存候補を報告"},"questions":{"zh":"请提供与“重复文件识别预览”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For duplicate file preview, provide source material, target software/use case and fixed constraints.","ja":"「重複ファイルの確認」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('automation-focused-extract','published','{"id":"automation-focused-extract","group":"automation","labels":{"zh":"文本提取与正则","en":"Text extraction and regex","ja":"文字抽出・正規表現"},"terms":["文本提取与正则","Text extraction and regex","文字抽出・正規表現","extract"],"guidance":{"zh":"从样例定义提取目标与排除项，给目标语言正则、解释和边界用例。保留行号及未匹配报告，说明正则不适合的嵌套结构并选解析器，不用贪婪匹配吞掉正文。","en":"Define extraction and exclusions from samples. Provide language-specific regex, explanation and edge tests with line numbers and unmatched reports. Use parsers for unsuitable nested structures.","ja":"例から抽出・除外を定め、言語別正規表現、説明、境界テスト、行番号、未一致を出す。複雑な入れ子はパーサーを選ぶ。"},"examples":{"zh":"请根据我提供的材料完成：文本提取与正则. 从样例定义提取目标与排除项，给目标语言正则、解释和边界用例","en":"Using my supplied material, deliver: Text extraction and regex. Define extraction and exclusions from samples. Provide language-specific regex, explanation and edge tests with line numbers and unmatched reports. Use parsers for unsuitable nested structures.","ja":"提供資料に基づき作成してください：文字抽出・正規表現. 例から抽出・除外を定め、言語別正規表現、説明、境界テスト、行番号、未一致を出す"},"questions":{"zh":"请提供与“文本提取与正则”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For text extraction and regex, provide source material, target software/use case and fixed constraints.","ja":"「文字抽出・正規表現」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('git-focused-bisect','published','{"id":"git-focused-bisect","group":"git","labels":{"zh":"定位引入问题的提交","en":"Find a regression commit","ja":"不具合導入コミットの特定"},"terms":["定位引入问题的提交","Find a regression commit","不具合導入コミットの特定","bisect"],"guidance":{"zh":"定义可靠的好坏判断命令与已知边界，给bisect步骤、跳过不构建提交及退出恢复方法。保留工作区，最终用最小复现核实提交，不把相关当根因。","en":"Define a reliable good/bad command and known bounds. Provide bisect, skip and reset steps while preserving work. Confirm the candidate with a minimal reproduction rather than equating correlation with cause.","ja":"良否判定と境界を定め、bisect、スキップ、復帰を示す。作業を保ち最小再現で候補を確認し、相関を原因としない。"},"examples":{"zh":"请根据我提供的材料完成：定位引入问题的提交. 定义可靠的好坏判断命令与已知边界，给bisect步骤、跳过不构建提交及退出恢复方法","en":"Using my supplied material, deliver: Find a regression commit. Define a reliable good/bad command and known bounds. Provide bisect, skip and reset steps while preserving work. Confirm the candidate with a minimal reproduction rather than equating correlation with cause.","ja":"提供資料に基づき作成してください：不具合導入コミットの特定. 良否判定と境界を定め、bisect、スキップ、復帰を示す"},"questions":{"zh":"请提供与“定位引入问题的提交”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For find a regression commit, provide source material, target software/use case and fixed constraints.","ja":"「不具合導入コミットの特定」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('git-focused-revert','published','{"id":"git-focused-revert","group":"git","labels":{"zh":"安全撤销与恢复","en":"Safe undo and recovery","ja":"変更取消・復元"},"terms":["安全撤销与恢复","Safe undo and recovery","変更取消・復元","revert"],"guidance":{"zh":"先区分未提交、已提交未推送与共享历史，按状态选择恢复方案。给备份分支、预览与验证步骤，解释revert和reset影响，不默认丢弃改动或改写共享历史。","en":"Distinguish uncommitted, local commits and shared history before choosing recovery. Provide backups, previews and checks, explaining revert/reset effects without default data loss or shared-history rewriting.","ja":"未コミット、ローカル履歴、共有履歴を分け復元を選ぶ。予備、プレビュー、確認とrevert/resetの影響を示し、既定で作業を捨てない。"},"examples":{"zh":"请根据我提供的材料完成：安全撤销与恢复. 先区分未提交、已提交未推送与共享历史，按状态选择恢复方案","en":"Using my supplied material, deliver: Safe undo and recovery. Distinguish uncommitted, local commits and shared history before choosing recovery. Provide backups, previews and checks, explaining revert/reset effects without default data loss or shared-history rewriting.","ja":"提供資料に基づき作成してください：変更取消・復元. 未コミット、ローカル履歴、共有履歴を分け復元を選ぶ"},"questions":{"zh":"请提供与“安全撤销与恢复”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For safe undo and recovery, provide source material, target software/use case and fixed constraints.","ja":"「変更取消・復元」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('git-focused-commit','published','{"id":"git-focused-commit","group":"git","labels":{"zh":"拆分提交与变更说明","en":"Split commits and explain changes","ja":"コミット分割・変更説明"},"terms":["拆分提交与变更说明","Split commits and explain changes","コミット分割・変更説明","commit"],"guidance":{"zh":"按独立行为把差异分组，给分批暂存与提交说明，保留测试和实现的关联。检查临时文件与秘密，不能声称已提交；未知工作区先读状态。","en":"Group diffs by independent behavior, with staging steps and commit messages. Keep tests with implementation and check temporary files/secrets. Inspect unknown state and do not claim commits were made.","ja":"独立動作で差分を分け、段階的追加と説明を作る。テストと実装の関係、仮ファイル・秘密を確認し、実行済みとしない。"},"examples":{"zh":"请根据我提供的材料完成：拆分提交与变更说明. 按独立行为把差异分组，给分批暂存与提交说明，保留测试和实现的关联","en":"Using my supplied material, deliver: Split commits and explain changes. Group diffs by independent behavior, with staging steps and commit messages. Keep tests with implementation and check temporary files/secrets. Inspect unknown state and do not claim commits were made.","ja":"提供資料に基づき作成してください：コミット分割・変更説明. 独立動作で差分を分け、段階的追加と説明を作る"},"questions":{"zh":"请提供与“拆分提交与变更说明”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For split commits and explain changes, provide source material, target software/use case and fixed constraints.","ja":"「コミット分割・変更説明」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('integration-focused-oauth','published','{"id":"integration-focused-oauth","group":"integration","labels":{"zh":"OAuth 回调与令牌刷新","en":"OAuth callbacks and refresh","ja":"OAuthコールバック・更新"},"terms":["OAuth 回调与令牌刷新","OAuth callbacks and refresh","OAuthコールバック・更新","oauth"],"guidance":{"zh":"根据官方协议和应用类型说明state、PKCE、回调白名单与令牌存储。给失败分支、撤销和刷新竞态测试，密钥不进浏览器，不自创授权协议。","en":"Use official protocol and app type to define state, PKCE, redirect allowlists and token storage. Test failures, revocation and refresh races; keep secrets out of browsers.","ja":"公式方式とアプリ種別からstate、PKCE、許可先、保存を定める。失敗、取消、更新競合をテストし秘密をブラウザーに置かない。"},"examples":{"zh":"请根据我提供的材料完成：OAuth 回调与令牌刷新. 根据官方协议和应用类型说明state、PKCE、回调白名单与令牌存储","en":"Using my supplied material, deliver: OAuth callbacks and refresh. Use official protocol and app type to define state, PKCE, redirect allowlists and token storage. Test failures, revocation and refresh races; keep secrets out of browsers.","ja":"提供資料に基づき作成してください：OAuthコールバック・更新. 公式方式とアプリ種別からstate、PKCE、許可先、保存を定める"},"questions":{"zh":"请提供与“OAuth 回调与令牌刷新”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For oauth callbacks and refresh, provide source material, target software/use case and fixed constraints.","ja":"「OAuthコールバック・更新」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('integration-focused-pagination','published','{"id":"integration-focused-pagination","group":"integration","labels":{"zh":"分页拉取与断点续传","en":"Paginated fetch and resume","ja":"ページ取得・再開"},"terms":["分页拉取与断点续传","Paginated fetch and resume","ページ取得・再開","pagination"],"guidance":{"zh":"定义游标持久化、稳定排序、限速和检查点，给中断恢复代码。处理重复页、游标失效、空页及新增记录，不默认页码能保证完整性。","en":"Define persisted cursors, stable order, limits and checkpoints. Implement recovery for repeated/empty pages, expired cursors and new records; page numbers alone do not ensure completeness.","ja":"カーソル保存、安定順序、制限、確認点を定義。重複・空ページ、失効、追加レコードを扱い、ページ番号だけで完全性を保証しない。"},"examples":{"zh":"请根据我提供的材料完成：分页拉取与断点续传. 定义游标持久化、稳定排序、限速和检查点，给中断恢复代码","en":"Using my supplied material, deliver: Paginated fetch and resume. Define persisted cursors, stable order, limits and checkpoints. Implement recovery for repeated/empty pages, expired cursors and new records; page numbers alone do not ensure completeness.","ja":"提供資料に基づき作成してください：ページ取得・再開. カーソル保存、安定順序、制限、確認点を定義"},"questions":{"zh":"请提供与“分页拉取与断点续传”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For paginated fetch and resume, provide source material, target software/use case and fixed constraints.","ja":"「ページ取得・再開」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('integration-focused-mock','published','{"id":"integration-focused-mock","group":"integration","labels":{"zh":"接口模拟与契约验证","en":"API mocks and contracts","ja":"APIモック・契約確認"},"terms":["接口模拟与契约验证","API mocks and contracts","APIモック・契約確認","mock"],"guidance":{"zh":"根据真实接口定义生成成功与错误样例、类型及模拟处理器。验证请求响应契约和版本差异，明确模拟数据；不将模拟通过当作生产服务已连通。","en":"Generate typed success/error fixtures and mock handlers from real contracts. Validate request/response shape and version differences. Label simulated data; passing mocks does not prove production connectivity.","ja":"実契約から型付き成功・失敗例とモックを作る。入出力と版差を検証し、模擬成功を本番接続としない。"},"examples":{"zh":"请根据我提供的材料完成：接口模拟与契约验证. 根据真实接口定义生成成功与错误样例、类型及模拟处理器","en":"Using my supplied material, deliver: API mocks and contracts. Generate typed success/error fixtures and mock handlers from real contracts. Validate request/response shape and version differences. Label simulated data; passing mocks does not prove production connectivity.","ja":"提供資料に基づき作成してください：APIモック・契約確認. 実契約から型付き成功・失敗例とモックを作る"},"questions":{"zh":"请提供与“接口模拟与契约验证”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For api mocks and contracts, provide source material, target software/use case and fixed constraints.","ja":"「APIモック・契約確認」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('games-focused-inventory','published','{"id":"games-focused-inventory","group":"games","labels":{"zh":"背包与物品堆叠","en":"Inventory and item stacking","ja":"持ち物・スタック"},"terms":["背包与物品堆叠","Inventory and item stacking","持ち物・スタック","inventory"],"guidance":{"zh":"定义物品ID、容量、堆叠上限和装备规则，交付增删移动代码及溢出测试。区分物品定义和实例，处理存档升级，不复制同一引用产生重复物品。","en":"Define item IDs, capacity, stack limits and equipment rules. Implement add/remove/move and overflow tests, separating definitions from instances and handling save upgrades.","ja":"ID、容量、重ね上限、装備を定め、追加・削除・移動と超過テストを実装。定義と個体を分け、保存版の更新も扱う。"},"examples":{"zh":"请根据我提供的材料完成：背包与物品堆叠. 定义物品ID、容量、堆叠上限和装备规则，交付增删移动代码及溢出测试","en":"Using my supplied material, deliver: Inventory and item stacking. Define item IDs, capacity, stack limits and equipment rules. Implement add/remove/move and overflow tests, separating definitions from instances and handling save upgrades.","ja":"提供資料に基づき作成してください：持ち物・スタック. ID、容量、重ね上限、装備を定め、追加・削除・移動と超過テストを実装"},"questions":{"zh":"请提供与“背包与物品堆叠”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For inventory and item stacking, provide source material, target software/use case and fixed constraints.","ja":"「持ち物・スタック」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('games-focused-input','published','{"id":"games-focused-input","group":"games","labels":{"zh":"输入重映射与手柄","en":"Input remapping and controllers","ja":"入力変更・コントローラー"},"terms":["输入重映射与手柄","Input remapping and controllers","入力変更・コントローラー","input"],"guidance":{"zh":"建立动作映射、死区、设备切换和冲突提示，给目标引擎实现。覆盖断连、暂停、菜单与游戏输入隔离，并保存用户配置，不把按键写死。","en":"Implement action maps, dead zones, device changes and binding conflicts. Test disconnects, pause and menu/gameplay separation; persist user settings instead of hard-coding keys.","ja":"動作対応、遊び幅、機器切替、割当競合を実装。切断、一時停止、メニュー分離を確認し、キーを固定せず設定保存する。"},"examples":{"zh":"请根据我提供的材料完成：输入重映射与手柄. 建立动作映射、死区、设备切换和冲突提示，给目标引擎实现","en":"Using my supplied material, deliver: Input remapping and controllers. Implement action maps, dead zones, device changes and binding conflicts. Test disconnects, pause and menu/gameplay separation; persist user settings instead of hard-coding keys.","ja":"提供資料に基づき作成してください：入力変更・コントローラー. 動作対応、遊び幅、機器切替、割当競合を実装"},"questions":{"zh":"请提供与“输入重映射与手柄”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For input remapping and controllers, provide source material, target software/use case and fixed constraints.","ja":"「入力変更・コントローラー」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('games-focused-balance','published','{"id":"games-focused-balance","group":"games","labels":{"zh":"数值平衡小实验","en":"Game balance experiment","ja":"ゲーム調整の小実験"},"terms":["数值平衡小实验","Game balance experiment","ゲーム調整の小実験","balance"],"guidance":{"zh":"列玩法目标、可调参数与观测指标，用显式假设构建小规模对照。给配置表、试玩问题和修改范围，不伪造玩家数据或把理论计算当真实乐趣。","en":"Define goals, parameters and metrics for a small controlled balance experiment. Provide configurations, playtest questions and adjustment bounds without invented player data or equating calculations with fun.","ja":"目的、変数、指標を定め小さな比較実験を作る。設定、試遊質問、変更幅を示し、架空プレイヤーデータや計算上の楽しさを断定しない。"},"examples":{"zh":"请根据我提供的材料完成：数值平衡小实验. 列玩法目标、可调参数与观测指标，用显式假设构建小规模对照","en":"Using my supplied material, deliver: Game balance experiment. Define goals, parameters and metrics for a small controlled balance experiment. Provide configurations, playtest questions and adjustment bounds without invented player data or equating calculations with fun.","ja":"提供資料に基づき作成してください：ゲーム調整の小実験. 目的、変数、指標を定め小さな比較実験を作る"},"questions":{"zh":"请提供与“数值平衡小实验”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For game balance experiment, provide source material, target software/use case and fixed constraints.","ja":"「ゲーム調整の小実験」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('backend-focused-transactions','published','{"id":"backend-focused-transactions","group":"backend","labels":{"zh":"事务与回滚边界","en":"Transactions and rollback","ja":"トランザクション境界"},"terms":["事务与回滚边界","Transactions and rollback","トランザクション境界","transactions"],"guidance":{"zh":"标明必须原子完成的写入、隔离级别与外部副作用，提供事务代码和中途失败测试。解释回滚不能撤销已发邮件等外部动作，并设计补偿。","en":"Identify atomic writes, isolation and external effects. Supply transaction code and mid-operation failures. Explain why rollback cannot undo sent messages and design compensation.","ja":"原子的書込、隔離、外部作用を定めコードと途中失敗テストを出す。送信済み通知などが巻戻らない理由と補償を示す。"},"examples":{"zh":"请根据我提供的材料完成：事务与回滚边界. 标明必须原子完成的写入、隔离级别与外部副作用，提供事务代码和中途失败测试","en":"Using my supplied material, deliver: Transactions and rollback. Identify atomic writes, isolation and external effects. Supply transaction code and mid-operation failures. Explain why rollback cannot undo sent messages and design compensation.","ja":"提供資料に基づき作成してください：トランザクション境界. 原子的書込、隔離、外部作用を定めコードと途中失敗テストを出す"},"questions":{"zh":"请提供与“事务与回滚边界”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For transactions and rollback, provide source material, target software/use case and fixed constraints.","ja":"「トランザクション境界」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('backend-focused-jobs','published','{"id":"backend-focused-jobs","group":"backend","labels":{"zh":"后台队列与重试","en":"Background queues and retries","ja":"バックグラウンド処理・再試行"},"terms":["后台队列与重试","Background queues and retries","バックグラウンド処理・再試行","jobs"],"guidance":{"zh":"定义任务状态、幂等键、重试退避与死信处理，给消费者代码与观测字段。覆盖重复投递和进程中断，区分至少一次与恰好一次，不空口保证不重复。","en":"Define states, idempotency keys, backoff and dead letters. Implement consumers and observability, testing duplicates and crashes. Distinguish at-least-once delivery from exactly-once effects.","ja":"状態、冪等キー、再試行間隔、失敗保管を定め、消費処理と観測を実装。重複と停止を確認し配送保証と副作用を分ける。"},"examples":{"zh":"请根据我提供的材料完成：后台队列与重试. 定义任务状态、幂等键、重试退避与死信处理，给消费者代码与观测字段","en":"Using my supplied material, deliver: Background queues and retries. Define states, idempotency keys, backoff and dead letters. Implement consumers and observability, testing duplicates and crashes. Distinguish at-least-once delivery from exactly-once effects.","ja":"提供資料に基づき作成してください：バックグラウンド処理・再試行. 状態、冪等キー、再試行間隔、失敗保管を定め、消費処理と観測を実装"},"questions":{"zh":"请提供与“后台队列与重试”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For background queues and retries, provide source material, target software/use case and fixed constraints.","ja":"「バックグラウンド処理・再試行」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('backend-focused-search','published','{"id":"backend-focused-search","group":"backend","labels":{"zh":"站内搜索与排序","en":"Site search and ranking","ja":"サイト検索・順位付け"},"terms":["站内搜索与排序","Site search and ranking","サイト検索・順位付け","search"],"guidance":{"zh":"定义分词、字段权重、拼写差异、过滤与稳定排序，给查询代码和相关性样例。核对空查询、无结果、权限过滤与分页，保留可解释匹配证据。","en":"Define tokenization, field weights, spelling variation, filters and stable ranking. Deliver query code and relevance examples, checking empty queries, no results, permissions and pagination with explainable matches.","ja":"分割、項目重み、表記揺れ、絞込、安定順位を定義。空、該当なし、権限、ページを検証し、一致根拠付きのクエリを出す。"},"examples":{"zh":"请根据我提供的材料完成：站内搜索与排序. 定义分词、字段权重、拼写差异、过滤与稳定排序，给查询代码和相关性样例","en":"Using my supplied material, deliver: Site search and ranking. Define tokenization, field weights, spelling variation, filters and stable ranking. Deliver query code and relevance examples, checking empty queries, no results, permissions and pagination with explainable matches.","ja":"提供資料に基づき作成してください：サイト検索・順位付け. 分割、項目重み、表記揺れ、絞込、安定順位を定義"},"questions":{"zh":"请提供与“站内搜索与排序”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For site search and ranking, provide source material, target software/use case and fixed constraints.","ja":"「サイト検索・順位付け」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('testing-focused-flaky','published','{"id":"testing-focused-flaky","group":"testing","labels":{"zh":"不稳定测试排查","en":"Flaky test diagnosis","ja":"不安定テストの調査"},"terms":["不稳定测试排查","Flaky test diagnosis","不安定テストの調査","flaky"],"guidance":{"zh":"收集重复运行的失败模式，区分时序、共享状态、随机性与外部依赖。给最小修复和复测矩阵，不靠增加长等待或关闭断言取得绿灯。","en":"Classify repeated failures as timing, shared state, randomness or external dependency issues. Provide minimal fixes and rerun matrices without long sleeps or removed assertions.","ja":"反復失敗を時序、共有状態、乱数、外部依存に分け最小修正と再試験を出す。長待機や検証削除で合格にしない。"},"examples":{"zh":"请根据我提供的材料完成：不稳定测试排查. 收集重复运行的失败模式，区分时序、共享状态、随机性与外部依赖","en":"Using my supplied material, deliver: Flaky test diagnosis. Classify repeated failures as timing, shared state, randomness or external dependency issues. Provide minimal fixes and rerun matrices without long sleeps or removed assertions.","ja":"提供資料に基づき作成してください：不安定テストの調査. 反復失敗を時序、共有状態、乱数、外部依存に分け最小修正と再試験を出す"},"questions":{"zh":"请提供与“不稳定测试排查”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For flaky test diagnosis, provide source material, target software/use case and fixed constraints.","ja":"「不安定テストの調査」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('testing-focused-boundaries','published','{"id":"testing-focused-boundaries","group":"testing","labels":{"zh":"日期金额边界测试","en":"Date and money boundary tests","ja":"日付・金額の境界テスト"},"terms":["日期金额边界测试","Date and money boundary tests","日付・金額の境界テスト","boundaries"],"guidance":{"zh":"围绕时区、闰日、月末、精度和舍入列输入及明确期待值，使用目标业务规则。控制时间来源，金额用适当表示，不复制实现计算预期。","en":"Test timezones, leap days, month ends, precision and rounding with explicit business expectations. Control clocks and monetary representations without duplicating implementation to calculate answers.","ja":"時差、閏日、月末、精度、丸めの明示期待値を業務規則で作る。時刻源と金額表現を管理し、実装複製で期待値を出さない。"},"examples":{"zh":"请根据我提供的材料完成：日期金额边界测试. 围绕时区、闰日、月末、精度和舍入列输入及明确期待值，使用目标业务规则","en":"Using my supplied material, deliver: Date and money boundary tests. Test timezones, leap days, month ends, precision and rounding with explicit business expectations. Control clocks and monetary representations without duplicating implementation to calculate answers.","ja":"提供資料に基づき作成してください：日付・金額の境界テスト. 時差、閏日、月末、精度、丸めの明示期待値を業務規則で作る"},"questions":{"zh":"请提供与“日期金额边界测试”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For date and money boundary tests, provide source material, target software/use case and fixed constraints.","ja":"「日付・金額の境界テスト」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('testing-focused-accessibility','published','{"id":"testing-focused-accessibility","group":"testing","labels":{"zh":"键盘与读屏测试","en":"Keyboard and screen-reader tests","ja":"キーボード・読み上げテスト"},"terms":["键盘与读屏测试","Keyboard and screen-reader tests","キーボード・読み上げテスト","accessibility"],"guidance":{"zh":"按焦点顺序、可访问名称、对话框、错误提示和状态更新设计操作测试。区分自动检查与人工读屏项目，记录证据和未测范围，不凭扫描分数宣称全面合规。","en":"Test focus order, accessible names, dialogs, errors and status updates. Separate automated checks from manual screen-reader tasks, recording evidence and untested scope rather than claiming compliance from a score.","ja":"焦点順、名称、ダイアログ、エラー、状態通知をテスト。自動と手動読上げを分け、証拠と未確認を記し点数だけで適合宣言しない。"},"examples":{"zh":"请根据我提供的材料完成：键盘与读屏测试. 按焦点顺序、可访问名称、对话框、错误提示和状态更新设计操作测试","en":"Using my supplied material, deliver: Keyboard and screen-reader tests. Test focus order, accessible names, dialogs, errors and status updates. Separate automated checks from manual screen-reader tasks, recording evidence and untested scope rather than claiming compliance from a score.","ja":"提供資料に基づき作成してください：キーボード・読み上げテスト. 焦点順、名称、ダイアログ、エラー、状態通知をテスト"},"questions":{"zh":"请提供与“键盘与读屏测试”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For keyboard and screen-reader tests, provide source material, target software/use case and fixed constraints.","ja":"「キーボード・読み上げテスト」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('devops-focused-env','published','{"id":"devops-focused-env","group":"devops","labels":{"zh":"环境差异与配置排错","en":"Environment configuration debugging","ja":"環境差・設定の調査"},"terms":["环境差异与配置排错","Environment configuration debugging","環境差・設定の調査","env"],"guidance":{"zh":"对照本地与部署环境的版本、构建参数、变量名和运行入口，给脱敏差异表。按证据定位缺失配置与缓存问题，不打印变量值或无关秘密。","en":"Compare versions, build options, variable names and entrypoints across local/deployed environments. Produce a redacted diff and evidence-based checks for missing configuration and stale caches without printing secrets.","ja":"ローカルと配備先の版、設定、変数名、入口を比較。機密除去した差分で不足・古いキャッシュを調べ、値や秘密を出さない。"},"examples":{"zh":"请根据我提供的材料完成：环境差异与配置排错. 对照本地与部署环境的版本、构建参数、变量名和运行入口，给脱敏差异表","en":"Using my supplied material, deliver: Environment configuration debugging. Compare versions, build options, variable names and entrypoints across local/deployed environments. Produce a redacted diff and evidence-based checks for missing configuration and stale caches without printing secrets.","ja":"提供資料に基づき作成してください：環境差・設定の調査. ローカルと配備先の版、設定、変数名、入口を比較"},"questions":{"zh":"请提供与“环境差异与配置排错”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For environment configuration debugging, provide source material, target software/use case and fixed constraints.","ja":"「環境差・設定の調査」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('devops-focused-backup','published','{"id":"devops-focused-backup","group":"devops","labels":{"zh":"备份与恢复演练","en":"Backup restoration drill","ja":"バックアップ復元演習"},"terms":["备份与恢复演练","Backup restoration drill","バックアップ復元演習","backup"],"guidance":{"zh":"以恢复目标定义备份范围、频率、加密和保留，给隔离环境恢复步骤及完整性验证。记录实测恢复时间与未测项，不把备份任务成功当恢复成功。","en":"Define scope, frequency, encryption and retention from recovery objectives. Restore in an isolated environment and validate integrity, recording measured times and gaps. Backup success is not restoration success.","ja":"復旧目標から範囲、周期、暗号、保存を決め隔離環境で復元・整合性確認。実時間と未確認を記し、保存成功を復元成功としない。"},"examples":{"zh":"请根据我提供的材料完成：备份与恢复演练. 以恢复目标定义备份范围、频率、加密和保留，给隔离环境恢复步骤及完整性验证","en":"Using my supplied material, deliver: Backup restoration drill. Define scope, frequency, encryption and retention from recovery objectives. Restore in an isolated environment and validate integrity, recording measured times and gaps. Backup success is not restoration success.","ja":"提供資料に基づき作成してください：バックアップ復元演習. 復旧目標から範囲、周期、暗号、保存を決め隔離環境で復元・整合性確認"},"questions":{"zh":"请提供与“备份与恢复演练”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For backup restoration drill, provide source material, target software/use case and fixed constraints.","ja":"「バックアップ復元演習」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('devops-focused-monitor','published','{"id":"devops-focused-monitor","group":"devops","labels":{"zh":"监控告警降噪","en":"Actionable monitoring alerts","ja":"対応可能な監視通知"},"terms":["监控告警降噪","Actionable monitoring alerts","対応可能な監視通知","monitor"],"guidance":{"zh":"从用户影响定义指标、阈值、持续时间和负责人，给告警内容与运行手册链接规则。区分症状和原因、去重与静默，核对误报和漏报，不默认每个异常都通知。","en":"Define metrics, thresholds, duration and owners from user impact. Design actionable alerts and runbook links with grouping and silencing. Check false positives and misses instead of alerting on every anomaly.","ja":"利用者影響から指標、閾値、継続時間、担当を定め通知と手順参照を作る。集約・抑制と誤報・見逃しを確認する。"},"examples":{"zh":"请根据我提供的材料完成：监控告警降噪. 从用户影响定义指标、阈值、持续时间和负责人，给告警内容与运行手册链接规则","en":"Using my supplied material, deliver: Actionable monitoring alerts. Define metrics, thresholds, duration and owners from user impact. Design actionable alerts and runbook links with grouping and silencing. Check false positives and misses instead of alerting on every anomaly.","ja":"提供資料に基づき作成してください：対応可能な監視通知. 利用者影響から指標、閾値、継続時間、担当を定め通知と手順参照を作る"},"questions":{"zh":"请提供与“监控告警降噪”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For actionable monitoring alerts, provide source material, target software/use case and fixed constraints.","ja":"「対応可能な監視通知」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('photo-focused-restore','published','{"id":"photo-focused-restore","group":"photo","labels":{"zh":"老照片修复描述","en":"Old-photo restoration brief","ja":"古い写真の修復指示"},"terms":["老照片修复描述","Old-photo restoration brief","古い写真の修復指示","restore"],"guidance":{"zh":"描述划痕、褪色和破损修复范围，锁定脸部身份、服饰与构图。区分清晰度改善和猜测重建，未知细节不要捏造；给保守修复与可选上色两版，保留原件。","en":"Specify scratches, fading and damage while preserving identity, clothing and framing. Separate enhancement from speculative reconstruction. Keep originals and provide conservative restoration plus optional colorization.","ja":"傷、退色、破損の範囲を示し顔、服、構図を固定。鮮明化と推測再構築を分け、原本を保つ控えめ修復と任意着色を出す。"},"examples":{"zh":"请根据我提供的材料完成：老照片修复描述. 描述划痕、褪色和破损修复范围，锁定脸部身份、服饰与构图","en":"Using my supplied material, deliver: Old-photo restoration brief. Specify scratches, fading and damage while preserving identity, clothing and framing. Separate enhancement from speculative reconstruction. Keep originals and provide conservative restoration plus optional colorization.","ja":"提供資料に基づき作成してください：古い写真の修復指示. 傷、退色、破損の範囲を示し顔、服、構図を固定"},"questions":{"zh":"请提供与“老照片修复描述”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For old-photo restoration brief, provide source material, target software/use case and fixed constraints.","ja":"「古い写真の修復指示」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('photo-focused-background','published','{"id":"photo-focused-background","group":"photo","labels":{"zh":"商品换背景与落影","en":"Product background replacement","ja":"商品背景・影の置換"},"terms":["商品换背景与落影","Product background replacement","商品背景・影の置換","background"],"guidance":{"zh":"固定商品形状、色彩和比例，只改指定背景；说明接触阴影、反射、光向和景深。提供遮罩范围及边缘检查，不重绘用户要求保留的标签。","en":"Preserve shape, color and scale while replacing only the specified background. Define contact shadows, reflections, light and depth, with mask/edge checks. Do not redraw protected labels.","ja":"形、色、比率を固定し指定背景だけ変える。接地影、反射、光、奥行きとマスク・縁確認を示し、保持ラベルを描き直さない。"},"examples":{"zh":"请根据我提供的材料完成：商品换背景与落影. 固定商品形状、色彩和比例，只改指定背景；说明接触阴影、反射、光向和景深","en":"Using my supplied material, deliver: Product background replacement. Preserve shape, color and scale while replacing only the specified background. Define contact shadows, reflections, light and depth, with mask/edge checks. Do not redraw protected labels.","ja":"提供資料に基づき作成してください：商品背景・影の置換. 形、色、比率を固定し指定背景だけ変える"},"questions":{"zh":"请提供与“商品换背景与落影”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For product background replacement, provide source material, target software/use case and fixed constraints.","ja":"「商品背景・影の置換」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('photo-focused-series','published','{"id":"photo-focused-series","group":"photo","labels":{"zh":"同款商品系列图","en":"Consistent product image set","ja":"同一商品の画像セット"},"terms":["同款商品系列图","Consistent product image set","同一商品の画像セット","series"],"guidance":{"zh":"建立固定商品ID和共有参数，分别给不同用途图片的独立提示词。统一颜色与材质，改变机位或场景时注明可变项；输出逐张验收表，不用同一段提示词机械复制。","en":"Create a stable product ID and shared parameters, then distinct prompts per use case. Keep materials/colors consistent and specify allowed camera/scene changes. Include per-image checks rather than identical prompts.","ja":"商品IDと共通条件を決め用途別の独立文を作る。色・材質を保ち機位や場面の可変範囲と個別確認を記す。"},"examples":{"zh":"请根据我提供的材料完成：同款商品系列图. 建立固定商品ID和共有参数，分别给不同用途图片的独立提示词","en":"Using my supplied material, deliver: Consistent product image set. Create a stable product ID and shared parameters, then distinct prompts per use case. Keep materials/colors consistent and specify allowed camera/scene changes. Include per-image checks rather than identical prompts.","ja":"提供資料に基づき作成してください：同一商品の画像セット. 商品IDと共通条件を決め用途別の独立文を作る"},"questions":{"zh":"请提供与“同款商品系列图”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For consistent product image set, provide source material, target software/use case and fixed constraints.","ja":"「同一商品の画像セット」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('character-focused-wardrobe','published','{"id":"character-focused-wardrobe","group":"character","labels":{"zh":"角色换装保持身份","en":"Character wardrobe variations","ja":"同一人物の衣装変更"},"terms":["角色换装保持身份","Character wardrobe variations","同一人物の衣装変更","wardrobe"],"guidance":{"zh":"区分面部、体型、发型等固定特征与衣服可变项，给三套符合情节的服装描述。保留角色ID和比例，检查配饰归属，不把换装变成换人。","en":"Separate fixed face, body and hair from clothing changes. Describe three story-appropriate outfits with stable ID/proportions and accessory ownership; a wardrobe change must not change the character.","ja":"顔、体型、髪を固定し、物語に合う衣装三案を作る。ID、比率、小物を保ち、別人にしない。"},"examples":{"zh":"请根据我提供的材料完成：角色换装保持身份. 区分面部、体型、发型等固定特征与衣服可变项，给三套符合情节的服装描述","en":"Using my supplied material, deliver: Character wardrobe variations. Separate fixed face, body and hair from clothing changes. Describe three story-appropriate outfits with stable ID/proportions and accessory ownership; a wardrobe change must not change the character.","ja":"提供資料に基づき作成してください：同一人物の衣装変更. 顔、体型、髪を固定し、物語に合う衣装三案を作る"},"questions":{"zh":"请提供与“角色换装保持身份”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For character wardrobe variations, provide source material, target software/use case and fixed constraints.","ja":"「同一人物の衣装変更」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('character-focused-duo','published','{"id":"character-focused-duo","group":"character","labels":{"zh":"双人互动与位置","en":"Two-character interaction","ja":"二人の動作・位置"},"terms":["双人互动与位置","Two-character interaction","二人の動作・位置","duo"],"guidance":{"zh":"给每个人物ID、左右位置、朝向、视线与动作接触点，写前中后景及遮挡关系。分开两人的衣服道具，避免手臂融合与身份互换，附检查清单。","en":"Specify each ID, position, orientation, eyeline and contact point, with depth and occlusion. Keep costumes/props separate and check fused limbs or swapped identities.","ja":"各ID、左右、向き、視線、接触、奥行き、遮蔽を指定。衣服・小物を分け、腕の融合や人物入替を確認する。"},"examples":{"zh":"请根据我提供的材料完成：双人互动与位置. 给每个人物ID、左右位置、朝向、视线与动作接触点，写前中后景及遮挡关系","en":"Using my supplied material, deliver: Two-character interaction. Specify each ID, position, orientation, eyeline and contact point, with depth and occlusion. Keep costumes/props separate and check fused limbs or swapped identities.","ja":"提供資料に基づき作成してください：二人の動作・位置. 各ID、左右、向き、視線、接触、奥行き、遮蔽を指定"},"questions":{"zh":"请提供与“双人互动与位置”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For two-character interaction, provide source material, target software/use case and fixed constraints.","ja":"「二人の動作・位置」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('character-focused-grid','published','{"id":"character-focused-grid","group":"character","labels":{"zh":"九宫格逐格分镜","en":"Nine-panel character board","ja":"九分割の人物ボード"},"terms":["九宫格逐格分镜","Nine-panel character board","九分割の人物ボード","grid"],"guidance":{"zh":"先锁定角色与场景，再为九格分别写格号、景别、动作和构图。各格只表达一个时刻，连续镜头保持方位；同时提供单格生成文本，防多格拥挤。","en":"Lock character and setting, then define panel number, shot scale, action and composition for nine panels. Use one moment per panel and stable geography, with separate single-panel prompts.","ja":"人物と場面を固定し九格の番号、画角、動作、構図を指定。一格一時点で方位を保ち、個別生成文も出す。"},"examples":{"zh":"请根据我提供的材料完成：九宫格逐格分镜. 先锁定角色与场景，再为九格分别写格号、景别、动作和构图","en":"Using my supplied material, deliver: Nine-panel character board. Lock character and setting, then define panel number, shot scale, action and composition for nine panels. Use one moment per panel and stable geography, with separate single-panel prompts.","ja":"提供資料に基づき作成してください：九分割の人物ボード. 人物と場面を固定し九格の番号、画角、動作、構図を指定"},"questions":{"zh":"请提供与“九宫格逐格分镜”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For nine-panel character board, provide source material, target software/use case and fixed constraints.","ja":"「九分割の人物ボード」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('editing-focused-transition','published','{"id":"editing-focused-transition","group":"editing","labels":{"zh":"镜头衔接与转场","en":"Shot transitions","ja":"カット接続・転換"},"terms":["镜头衔接与转场","Shot transitions","カット接続・転換","transition"],"guidance":{"zh":"根据相邻镜头结束与开始状态设计动作、视线或声音衔接，说明切点和转场时长。优先服务叙事，区分硬切与镜内运动，不用花哨特效掩盖连续性错误。","en":"Match adjacent end/start states through action, eyeline or audio, specifying cut points and transition duration. Serve the story and distinguish cuts from in-shot motion rather than hiding continuity errors with effects.","ja":"前後状態を動作・視線・音でつなぎ切点と尺を指定。物語を優先し、切替と鏡内移動を分け、効果で矛盾を隠さない。"},"examples":{"zh":"请根据我提供的材料完成：镜头衔接与转场. 根据相邻镜头结束与开始状态设计动作、视线或声音衔接，说明切点和转场时长","en":"Using my supplied material, deliver: Shot transitions. Match adjacent end/start states through action, eyeline or audio, specifying cut points and transition duration. Serve the story and distinguish cuts from in-shot motion rather than hiding continuity errors with effects.","ja":"提供資料に基づき作成してください：カット接続・転換. 前後状態を動作・視線・音でつなぎ切点と尺を指定"},"questions":{"zh":"请提供与“镜头衔接与转场”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For shot transitions, provide source material, target software/use case and fixed constraints.","ja":"「カット接続・転換」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('editing-focused-audio','published','{"id":"editing-focused-audio","group":"editing","labels":{"zh":"对白与背景音平衡","en":"Dialogue and background sound","ja":"台詞・背景音の調整"},"terms":["对白与背景音平衡","Dialogue and background sound","台詞・背景音の調整","audio"],"guidance":{"zh":"按对白清晰度安排音乐压低、音效层次和静音段，给时间线标注与监听检查。目标响度依据交付要求，未听音频只给方案，不声称已消除噪声。","en":"Plan music ducking, effects and silence around dialogue, with timeline notes and listening checks. Follow delivery loudness requirements; without audio, offer a plan rather than claiming noise removal.","ja":"台詞を軸に音楽抑制、効果、無音を配置し時間線と試聴確認を出す。音量は納品条件に従い、未聴取で除去済みとしない。"},"examples":{"zh":"请根据我提供的材料完成：对白与背景音平衡. 按对白清晰度安排音乐压低、音效层次和静音段，给时间线标注与监听检查","en":"Using my supplied material, deliver: Dialogue and background sound. Plan music ducking, effects and silence around dialogue, with timeline notes and listening checks. Follow delivery loudness requirements; without audio, offer a plan rather than claiming noise removal.","ja":"提供資料に基づき作成してください：台詞・背景音の調整. 台詞を軸に音楽抑制、効果、無音を配置し時間線と試聴確認を出す"},"questions":{"zh":"请提供与“对白与背景音平衡”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For dialogue and background sound, provide source material, target software/use case and fixed constraints.","ja":"「台詞・背景音の調整」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('editing-focused-shorten','published','{"id":"editing-focused-shorten","group":"editing","labels":{"zh":"长视频压缩成短片","en":"Condense a long video","ja":"長尺から短編への編集"},"terms":["长视频压缩成短片","Condense a long video","長尺から短編への編集","shorten"],"guidance":{"zh":"从逐字稿或镜头表选核心信息，给保留片段、删除理由与新顺序。核对总尺、语义完整和出处，缺少画面时列补镜需求，不把断章取义当高效。","en":"Select key information from transcripts/shot lists with retained sections, deletion reasons and new order. Check duration, meaning and attribution, listing missing coverage rather than distorting context.","ja":"文字起こし・カット表から核心を選び、保持、削除理由、新順序を示す。尺、意味、出典を確認し不足画面を列挙する。"},"examples":{"zh":"请根据我提供的材料完成：长视频压缩成短片. 从逐字稿或镜头表选核心信息，给保留片段、删除理由与新顺序","en":"Using my supplied material, deliver: Condense a long video. Select key information from transcripts/shot lists with retained sections, deletion reasons and new order. Check duration, meaning and attribution, listing missing coverage rather than distorting context.","ja":"提供資料に基づき作成してください：長尺から短編への編集. 文字起こし・カット表から核心を選び、保持、削除理由、新順序を示す"},"questions":{"zh":"请提供与“长视频压缩成短片”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For condense a long video, provide source material, target software/use case and fixed constraints.","ja":"「長尺から短編への編集」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('assets3d-focused-uv','published','{"id":"assets3d-focused-uv","group":"assets3d","labels":{"zh":"UV 与贴图接缝规划","en":"UV and seam planning","ja":"UV・継ぎ目設計"},"terms":["UV 与贴图接缝规划","UV and seam planning","UV・継ぎ目設計","uv"],"guidance":{"zh":"按模型用途与可见面分配纹素密度、接缝、镜像和重叠策略，给检查步骤与导出要求。缺少网格时只给规划，不声称已展开或修复UV。","en":"Plan texel density, seams, mirroring and overlaps around use and visible surfaces, with checks/export requirements. Without a mesh, deliver a plan rather than claiming UV unwrapping or repair.","ja":"用途と可視面で密度、継ぎ目、反転、重複を設計し確認・出力を示す。メッシュなしで展開や修正済みとしない。"},"examples":{"zh":"请根据我提供的材料完成：UV 与贴图接缝规划. 按模型用途与可见面分配纹素密度、接缝、镜像和重叠策略，给检查步骤与导出要求","en":"Using my supplied material, deliver: UV and seam planning. Plan texel density, seams, mirroring and overlaps around use and visible surfaces, with checks/export requirements. Without a mesh, deliver a plan rather than claiming UV unwrapping or repair.","ja":"提供資料に基づき作成してください：UV・継ぎ目設計. 用途と可視面で密度、継ぎ目、反転、重複を設計し確認・出力を示す"},"questions":{"zh":"请提供与“UV 与贴图接缝规划”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For uv and seam planning, provide source material, target software/use case and fixed constraints.","ja":"「UV・継ぎ目設計」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('assets3d-focused-lighting','published','{"id":"assets3d-focused-lighting","group":"assets3d","labels":{"zh":"3D 场景灯光方案","en":"3D scene lighting plan","ja":"3D照明設計"},"terms":["3D 场景灯光方案","3D scene lighting plan","3D照明設計","lighting"],"guidance":{"zh":"定义主光、补光、轮廓光的位置、色温关系和阴影目的，给目标渲染器可用设置。分开艺术效果与物理参数，核对曝光及材质高光，不随意保证渲染速度。","en":"Define key, fill and rim placement, color relationships and shadow purpose with renderer-supported settings. Separate artistic intent from physical parameters and check exposure/highlights without speed guarantees.","ja":"主光、補光、輪郭光の位置、色関係、影目的を定め対応設定を出す。演出と物理値を分け、露出・反射を確認する。"},"examples":{"zh":"请根据我提供的材料完成：3D 场景灯光方案. 定义主光、补光、轮廓光的位置、色温关系和阴影目的，给目标渲染器可用设置","en":"Using my supplied material, deliver: 3D scene lighting plan. Define key, fill and rim placement, color relationships and shadow purpose with renderer-supported settings. Separate artistic intent from physical parameters and check exposure/highlights without speed guarantees.","ja":"提供資料に基づき作成してください：3D照明設計. 主光、補光、輪郭光の位置、色関係、影目的を定め対応設定を出す"},"questions":{"zh":"请提供与“3D 场景灯光方案”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For 3d scene lighting plan, provide source material, target software/use case and fixed constraints.","ja":"「3D照明設計」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('assets3d-focused-rig','published','{"id":"assets3d-focused-rig","group":"assets3d","labels":{"zh":"骨骼绑定需求与检查","en":"Rigging brief and checks","ja":"リグ仕様・確認"},"terms":["骨骼绑定需求与检查","Rigging brief and checks","リグ仕様・確認","rig"],"guidance":{"zh":"按动作范围定义骨骼、控制器、命名和变形重点，列关节极限姿势测试。给模型准备与权重检查清单，不把文字方案当已完成绑定，说明目标引擎限制。","en":"Define bones, controls, names and deformation priorities from motion needs. Test extreme joint poses and list mesh/weight preparation, noting engine limits. A written brief is not a completed rig.","ja":"動作範囲から骨、操作子、命名、変形を定義。関節限界の姿勢、モデル・重み確認、エンジン制限を示し、文章を完成リグとしない。"},"examples":{"zh":"请根据我提供的材料完成：骨骼绑定需求与检查. 按动作范围定义骨骼、控制器、命名和变形重点，列关节极限姿势测试","en":"Using my supplied material, deliver: Rigging brief and checks. Define bones, controls, names and deformation priorities from motion needs. Test extreme joint poses and list mesh/weight preparation, noting engine limits. A written brief is not a completed rig.","ja":"提供資料に基づき作成してください：リグ仕様・確認. 動作範囲から骨、操作子、命名、変形を定義"},"questions":{"zh":"请提供与“骨骼绑定需求与检查”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For rigging brief and checks, provide source material, target software/use case and fixed constraints.","ja":"「リグ仕様・確認」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('production-focused-vertical','published','{"id":"production-focused-vertical","group":"production","labels":{"zh":"竖屏动画分镜","en":"Vertical animation storyboard","ja":"縦型アニメ絵コンテ"},"terms":["竖屏动画分镜","Vertical animation storyboard","縦型アニメ絵コンテ","vertical"],"guidance":{"zh":"在竖屏安全区设计人物层级、字幕空间和远中近景，逐镜给时长、动作与运镜。保持纵向构图和角色ID，避免把横屏分镜直接裁切。","en":"Design hierarchy, caption space and shot scales for portrait framing. Specify duration, action and camera per shot with stable IDs, rather than cropping a landscape storyboard.","ja":"縦画面で人物階層、字幕域、画角を設計。各尺、動作、カメラと固定IDを示し、横画面の切抜きで済ませない。"},"examples":{"zh":"请根据我提供的材料完成：竖屏动画分镜. 在竖屏安全区设计人物层级、字幕空间和远中近景，逐镜给时长、动作与运镜","en":"Using my supplied material, deliver: Vertical animation storyboard. Design hierarchy, caption space and shot scales for portrait framing. Specify duration, action and camera per shot with stable IDs, rather than cropping a landscape storyboard.","ja":"提供資料に基づき作成してください：縦型アニメ絵コンテ. 縦画面で人物階層、字幕域、画角を設計"},"questions":{"zh":"请提供与“竖屏动画分镜”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For vertical animation storyboard, provide source material, target software/use case and fixed constraints.","ja":"「縦型アニメ絵コンテ」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('production-focused-loop','published','{"id":"production-focused-loop","group":"production","labels":{"zh":"无缝循环动画","en":"Seamless animation loop","ja":"シームレスループ"},"terms":["无缝循环动画","Seamless animation loop","シームレスループ","loop"],"guidance":{"zh":"明确首尾人物位置、光线、运动相位与镜头状态，给单一循环动作时间轴。分开生成提示词和剪辑衔接方案，检查首尾帧，不保证工具一定输出完美循环。","en":"Match start/end position, light, motion phase and camera. Provide one cyclic action timeline, separating generation prompts from edit solutions. Check endpoint frames without guaranteeing perfect model output.","ja":"始終点の位置、光、運動位相、カメラを合わせ一循環の時系列を出す。生成文と編集を分け、完全生成を保証しない。"},"examples":{"zh":"请根据我提供的材料完成：无缝循环动画. 明确首尾人物位置、光线、运动相位与镜头状态，给单一循环动作时间轴","en":"Using my supplied material, deliver: Seamless animation loop. Match start/end position, light, motion phase and camera. Provide one cyclic action timeline, separating generation prompts from edit solutions. Check endpoint frames without guaranteeing perfect model output.","ja":"提供資料に基づき作成してください：シームレスループ. 始終点の位置、光、運動位相、カメラを合わせ一循環の時系列を出す"},"questions":{"zh":"请提供与“无缝循环动画”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For seamless animation loop, provide source material, target software/use case and fixed constraints.","ja":"「シームレスループ」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('production-focused-repair','published','{"id":"production-focused-repair","group":"production","labels":{"zh":"动画穿帮修正提示词","en":"Animation defect repair prompts","ja":"アニメ不整合の修正文"},"terms":["动画穿帮修正提示词","Animation defect repair prompts","アニメ不整合の修正文","repair"],"guidance":{"zh":"按提供帧图定位人物、道具、背景和运动异常，给只改问题区域的最小提示词。锁定正确部分，区分可重生成与需后期修复；未看到帧图先索要证据。","en":"Locate character, prop, background and motion defects from supplied frames. Write minimal repair prompts locking correct areas, distinguishing regeneration from postproduction. Request evidence when frames are absent.","ja":"提供フレームから人物、小物、背景、動作の異常を特定。正しい部分を固定した最小修正文を出し、再生成と後処理を分ける。"},"examples":{"zh":"请根据我提供的材料完成：动画穿帮修正提示词. 按提供帧图定位人物、道具、背景和运动异常，给只改问题区域的最小提示词","en":"Using my supplied material, deliver: Animation defect repair prompts. Locate character, prop, background and motion defects from supplied frames. Write minimal repair prompts locking correct areas, distinguishing regeneration from postproduction. Request evidence when frames are absent.","ja":"提供資料に基づき作成してください：アニメ不整合の修正文. 提供フレームから人物、小物、背景、動作の異常を特定"},"questions":{"zh":"请提供与“动画穿帮修正提示词”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For animation defect repair prompts, provide source material, target software/use case and fixed constraints.","ja":"「アニメ不整合の修正文」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('office-focused-formula-error','published','{"id":"office-focused-formula-error","group":"office","labels":{"zh":"WPS 公式报错定位","en":"WPS formula error diagnosis","ja":"WPS数式エラー調査"},"terms":["WPS 公式报错定位","WPS formula error diagnosis","WPS数式エラー調査","formula error"],"guidance":{"zh":"根据实际公式、单元格值和报错定位引用、类型、分隔符或函数兼容问题。给可粘贴修正式、期望结果与空值测试；核对版本，不把Excel独有能力默认套用。","en":"Use the formula, cell values and error to isolate reference, type, separator or compatibility issues. Give a paste-ready fix, expected results and blank tests, verifying the WPS version.","ja":"式、セル値、エラーから参照、型、区切り、対応を調べる。貼付式、期待値、空欄テストを出しWPS版を確認する。"},"examples":{"zh":"请根据我提供的材料完成：WPS 公式报错定位. 根据实际公式、单元格值和报错定位引用、类型、分隔符或函数兼容问题","en":"Using my supplied material, deliver: WPS formula error diagnosis. Use the formula, cell values and error to isolate reference, type, separator or compatibility issues. Give a paste-ready fix, expected results and blank tests, verifying the WPS version.","ja":"提供資料に基づき作成してください：WPS数式エラー調査. 式、セル値、エラーから参照、型、区切り、対応を調べる"},"questions":{"zh":"请提供与“WPS 公式报错定位”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For wps formula error diagnosis, provide source material, target software/use case and fixed constraints.","ja":"「WPS数式エラー調査」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('office-focused-merge-docs','published','{"id":"office-focused-merge-docs","group":"office","labels":{"zh":"WPS 长文目录与编号","en":"WPS headings and numbering","ja":"WPS見出し・番号"},"terms":["WPS 长文目录与编号","WPS headings and numbering","WPS見出し・番号","merge docs"],"guidance":{"zh":"按文档层级设计标题样式、自动目录、图表编号和交叉引用，给逐步操作与更新检查。保留正文内容，区分手打编号与字段，菜单随版本核实。","en":"Map document hierarchy to heading styles, automatic contents, figure numbering and cross-references. Give steps and update checks while preserving text; distinguish manual numbers from fields and verify menus.","ja":"階層から見出し、目次、図表番号、相互参照を設計。本文を保つ操作と更新確認を出し、手入力とフィールドを分けメニューを確認する。"},"examples":{"zh":"请根据我提供的材料完成：WPS 长文目录与编号. 按文档层级设计标题样式、自动目录、图表编号和交叉引用，给逐步操作与更新检查","en":"Using my supplied material, deliver: WPS headings and numbering. Map document hierarchy to heading styles, automatic contents, figure numbering and cross-references. Give steps and update checks while preserving text; distinguish manual numbers from fields and verify menus.","ja":"提供資料に基づき作成してください：WPS見出し・番号. 階層から見出し、目次、図表番号、相互参照を設計"},"questions":{"zh":"请提供与“WPS 长文目录与编号”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For wps headings and numbering, provide source material, target software/use case and fixed constraints.","ja":"「WPS見出し・番号」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('office-focused-pivot','published','{"id":"office-focused-pivot","group":"office","labels":{"zh":"WPS 数据透视表","en":"WPS pivot tables","ja":"WPSピボットテーブル"},"terms":["WPS 数据透视表","WPS pivot tables","WPSピボットテーブル","pivot"],"guidance":{"zh":"从列名和业务问题指定行列、值、聚合与筛选，给创建、刷新和源数据核对步骤。处理重复、空值与日期分组，检查实际WPS支持，不虚构数据结果。","en":"Map columns and questions to rows, columns, values, aggregation and filters. Provide setup, refresh and source checks for duplicates, blanks and dates, verifying WPS support without invented results.","ja":"列と課題から行列、値、集計、絞込を決め、作成・更新・照合を示す。重複、空欄、日付、WPS対応を確認する。"},"examples":{"zh":"请根据我提供的材料完成：WPS 数据透视表. 从列名和业务问题指定行列、值、聚合与筛选，给创建、刷新和源数据核对步骤","en":"Using my supplied material, deliver: WPS pivot tables. Map columns and questions to rows, columns, values, aggregation and filters. Provide setup, refresh and source checks for duplicates, blanks and dates, verifying WPS support without invented results.","ja":"提供資料に基づき作成してください：WPSピボットテーブル. 列と課題から行列、値、集計、絞込を決め、作成・更新・照合を示す"},"questions":{"zh":"请提供与“WPS 数据透视表”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For wps pivot tables, provide source material, target software/use case and fixed constraints.","ja":"「WPSピボットテーブル」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('paper-focused-limitations','published','{"id":"paper-focused-limitations","group":"paper","labels":{"zh":"论文局限与讨论","en":"Paper limitations and discussion","ja":"論文の限界・考察"},"terms":["论文局限与讨论","Paper limitations and discussion","論文の限界・考察","limitations"],"guidance":{"zh":"从实际设计和结果识别偏差、测量局限及外推边界，写讨论段落并关联证据。区分解释、推测和未来研究，不能用空泛套话遮掩真实问题。","en":"Use actual design/results to discuss bias, measurement limits and generalization. Link paragraphs to evidence, separating interpretation, speculation and future work rather than generic disclaimers.","ja":"実設計・結果から偏り、測定限界、一般化を考察し根拠を結ぶ。解釈、推測、今後を分け定型文で問題を隠さない。"},"examples":{"zh":"请根据我提供的材料完成：论文局限与讨论. 从实际设计和结果识别偏差、测量局限及外推边界，写讨论段落并关联证据","en":"Using my supplied material, deliver: Paper limitations and discussion. Use actual design/results to discuss bias, measurement limits and generalization. Link paragraphs to evidence, separating interpretation, speculation and future work rather than generic disclaimers.","ja":"提供資料に基づき作成してください：論文の限界・考察. 実設計・結果から偏り、測定限界、一般化を考察し根拠を結ぶ"},"questions":{"zh":"请提供与“论文局限与讨论”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For paper limitations and discussion, provide source material, target software/use case and fixed constraints.","ja":"「論文の限界・考察」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('paper-focused-figures','published','{"id":"paper-focused-figures","group":"paper","labels":{"zh":"论文图表说明与交叉核对","en":"Paper figure captions and checks","ja":"論文図表の説明・照合"},"terms":["论文图表说明与交叉核对","Paper figure captions and checks","論文図表の説明・照合","figures"],"guidance":{"zh":"依据已提供图表写标题、变量、单位、样本与误差说明，逐项核对正文数字和编号。缺少统计定义明确待补，不猜误差条含义或补造显著性。","en":"Write captions from supplied figures: variables, units, sample and error definitions. Cross-check text values and numbering. Flag missing statistics instead of guessing error bars or significance.","ja":"提供図表から題、変数、単位、標本、誤差を記し本文値と番号を照合。不明統計を補作せず誤差棒や有意差を推測しない。"},"examples":{"zh":"请根据我提供的材料完成：论文图表说明与交叉核对. 依据已提供图表写标题、变量、单位、样本与误差说明，逐项核对正文数字和编号","en":"Using my supplied material, deliver: Paper figure captions and checks. Write captions from supplied figures: variables, units, sample and error definitions. Cross-check text values and numbering. Flag missing statistics instead of guessing error bars or significance.","ja":"提供資料に基づき作成してください：論文図表の説明・照合. 提供図表から題、変数、単位、標本、誤差を記し本文値と番号を照合"},"questions":{"zh":"请提供与“论文图表说明与交叉核对”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For paper figure captions and checks, provide source material, target software/use case and fixed constraints.","ja":"「論文図表の説明・照合」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('paper-focused-response','published','{"id":"paper-focused-response","group":"paper","labels":{"zh":"逐条审稿意见回复","en":"Point-by-point reviewer response","ja":"査読への逐条回答"},"terms":["逐条审稿意见回复","Point-by-point reviewer response","査読への逐条回答","response"],"guidance":{"zh":"按意见原文列回应、修改内容和真实位置，未采纳时说明有证据的理由。分开已改与计划实验，不捏造页码或新结果；给回复信与修改追踪表。","en":"Map each comment to response, change and actual location, with evidence for disagreements. Separate completed revisions from planned experiments. Provide a response letter and tracker without fabricated pages or results.","ja":"指摘ごとに回答、変更、実位置を示し不同意には根拠を付ける。完了と実験計画を分け、架空頁・結果なしで回答書と追跡表を出す。"},"examples":{"zh":"请根据我提供的材料完成：逐条审稿意见回复. 按意见原文列回应、修改内容和真实位置，未采纳时说明有证据的理由","en":"Using my supplied material, deliver: Point-by-point reviewer response. Map each comment to response, change and actual location, with evidence for disagreements. Separate completed revisions from planned experiments. Provide a response letter and tracker without fabricated pages or results.","ja":"提供資料に基づき作成してください：査読への逐条回答. 指摘ごとに回答、変更、実位置を示し不同意には根拠を付ける"},"questions":{"zh":"请提供与“逐条审稿意见回复”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For point-by-point reviewer response, provide source material, target software/use case and fixed constraints.","ja":"「査読への逐条回答」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('copy-focused-headlines','published','{"id":"copy-focused-headlines","group":"copy","labels":{"zh":"标题多角度改写","en":"Headline variations","ja":"見出しの切口別改稿"},"terms":["标题多角度改写","Headline variations","見出しの切口別改稿","headlines"],"guidance":{"zh":"围绕真实利益点写信息型、问题型和场景型标题，说明适合读者和区别。遵守字数，保留事实，不制造恐慌、虚假稀缺或不实效果；给一条选择理由。","en":"Create informative, question-led and situational headlines from real benefits, explaining audience and differences. Respect length without fearmongering, fake scarcity or false effects, and recommend one with reasons.","ja":"実利点から情報、質問、場面の見出しを作り読者と差を説明。字数を守り恐怖・偽希少性・虚偽効果を避け選択理由を付ける。"},"examples":{"zh":"请根据我提供的材料完成：标题多角度改写. 围绕真实利益点写信息型、问题型和场景型标题，说明适合读者和区别","en":"Using my supplied material, deliver: Headline variations. Create informative, question-led and situational headlines from real benefits, explaining audience and differences. Respect length without fearmongering, fake scarcity or false effects, and recommend one with reasons.","ja":"提供資料に基づき作成してください：見出しの切口別改稿. 実利点から情報、質問、場面の見出しを作り読者と差を説明"},"questions":{"zh":"请提供与“标题多角度改写”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For headline variations, provide source material, target software/use case and fixed constraints.","ja":"「見出しの切口別改稿」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('copy-focused-tone','published','{"id":"copy-focused-tone","group":"copy","labels":{"zh":"文案语气与品牌一致","en":"Brand voice consistency","ja":"語調・ブランド一貫性"},"terms":["文案语气与品牌一致","Brand voice consistency","語調・ブランド一貫性","tone"],"guidance":{"zh":"提炼提供样例的用词、句长和表达边界，重写目标文案并列主要变化。保留事实、价格和条件，区分品牌规则与个人偏好，不套统一营销腔。","en":"Extract vocabulary, sentence rhythm and boundaries from samples, then rewrite with a change summary. Preserve facts, prices and conditions; distinguish brand rules from preferences rather than imposing generic sales tone.","ja":"例文から語彙、長さ、境界を抽出し対象文を改稿。事実、価格、条件を保ち規則と好みを分け、一律の販売口調を避ける。"},"examples":{"zh":"请根据我提供的材料完成：文案语气与品牌一致. 提炼提供样例的用词、句长和表达边界，重写目标文案并列主要变化","en":"Using my supplied material, deliver: Brand voice consistency. Extract vocabulary, sentence rhythm and boundaries from samples, then rewrite with a change summary. Preserve facts, prices and conditions; distinguish brand rules from preferences rather than imposing generic sales tone.","ja":"提供資料に基づき作成してください：語調・ブランド一貫性. 例文から語彙、長さ、境界を抽出し対象文を改稿"},"questions":{"zh":"请提供与“文案语气与品牌一致”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For brand voice consistency, provide source material, target software/use case and fixed constraints.","ja":"「語調・ブランド一貫性」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('copy-focused-offer','published','{"id":"copy-focused-offer","group":"copy","labels":{"zh":"活动规则清晰表达","en":"Clear campaign terms","ja":"キャンペーン条件の明確化"},"terms":["活动规则清晰表达","Clear campaign terms","キャンペーン条件の明確化","offer"],"guidance":{"zh":"按真实时间、对象、门槛、优惠和排除项写完整活动文案，给短版与FAQ。核对数字和条件一致，不能隐藏限制或擅自承诺退款与名额。","en":"Write campaign copy from actual dates, eligibility, thresholds, benefits and exclusions, plus a short version and FAQ. Reconcile numbers and conditions without hiding limits or inventing refunds/availability.","ja":"実日時、対象、条件、特典、除外から全文・短文・FAQを作る。数字と条件を合わせ制限を隠さず返金や枠を約束しない。"},"examples":{"zh":"请根据我提供的材料完成：活动规则清晰表达. 按真实时间、对象、门槛、优惠和排除项写完整活动文案，给短版与FAQ","en":"Using my supplied material, deliver: Clear campaign terms. Write campaign copy from actual dates, eligibility, thresholds, benefits and exclusions, plus a short version and FAQ. Reconcile numbers and conditions without hiding limits or inventing refunds/availability.","ja":"提供資料に基づき作成してください：キャンペーン条件の明確化. 実日時、対象、条件、特典、除外から全文・短文・FAQを作る"},"questions":{"zh":"请提供与“活动规则清晰表达”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For clear campaign terms, provide source material, target software/use case and fixed constraints.","ja":"「キャンペーン条件の明確化」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('analytics-focused-cohort','published','{"id":"analytics-focused-cohort","group":"analytics","labels":{"zh":"留存与分群口径","en":"Retention and cohort definitions","ja":"継続率・コホート定義"},"terms":["留存与分群口径","Retention and cohort definitions","継続率・コホート定義","cohort"],"guidance":{"zh":"明确入组事件、活跃定义、时间窗和分母，给分群SQL与小样例手算。处理时区、未满观察期和重复用户，区分滚动留存与固定日留存。","en":"Define cohort event, activity, window and denominator. Provide SQL and a hand-worked sample, handling timezones, incomplete observation and duplicates. Distinguish rolling from fixed-day retention.","ja":"起点、活動、窓、分母を定めSQLと手計算例を出す。時差、観察不足、重複を扱い、累積と特定日継続を分ける。"},"examples":{"zh":"请根据我提供的材料完成：留存与分群口径. 明确入组事件、活跃定义、时间窗和分母，给分群SQL与小样例手算","en":"Using my supplied material, deliver: Retention and cohort definitions. Define cohort event, activity, window and denominator. Provide SQL and a hand-worked sample, handling timezones, incomplete observation and duplicates. Distinguish rolling from fixed-day retention.","ja":"提供資料に基づき作成してください：継続率・コホート定義. 起点、活動、窓、分母を定めSQLと手計算例を出す"},"questions":{"zh":"请提供与“留存与分群口径”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For retention and cohort definitions, provide source material, target software/use case and fixed constraints.","ja":"「継続率・コホート定義」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('analytics-focused-experiment','published','{"id":"analytics-focused-experiment","group":"analytics","labels":{"zh":"A/B 实验结果解读","en":"A/B experiment interpretation","ja":"A/B実験の解釈"},"terms":["A/B 实验结果解读","A/B experiment interpretation","A/B実験の解釈","experiment"],"guidance":{"zh":"根据分组、样本、指标和停止规则核对实验有效性，给效应与不确定性解释。检查多重比较、分流异常和实际意义，数据不足不强下胜负结论。","en":"Check assignment, sample, metrics and stopping rules. Explain effects and uncertainty, including multiple comparisons, allocation anomalies and practical significance. Do not force a winner from insufficient data.","ja":"割付、標本、指標、停止規則を確認し効果と不確実性を説明。多重比較、分流異常、実用意味を見て不足時は勝敗を断定しない。"},"examples":{"zh":"请根据我提供的材料完成：A/B 实验结果解读. 根据分组、样本、指标和停止规则核对实验有效性，给效应与不确定性解释","en":"Using my supplied material, deliver: A/B experiment interpretation. Check assignment, sample, metrics and stopping rules. Explain effects and uncertainty, including multiple comparisons, allocation anomalies and practical significance. Do not force a winner from insufficient data.","ja":"提供資料に基づき作成してください：A/B実験の解釈. 割付、標本、指標、停止規則を確認し効果と不確実性を説明"},"questions":{"zh":"请提供与“A/B 实验结果解读”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For a/b experiment interpretation, provide source material, target software/use case and fixed constraints.","ja":"「A/B実験の解釈」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('analytics-focused-reconcile','published','{"id":"analytics-focused-reconcile","group":"analytics","labels":{"zh":"报表数字对不上","en":"Report reconciliation","ja":"集計値の不一致調査"},"terms":["报表数字对不上","Report reconciliation","集計値の不一致調査","reconcile"],"guidance":{"zh":"逐层核对时间范围、过滤、去重、连接和舍入，给差异拆解表与定位查询。用相同口径复算并保留证据，不以手改汇总值掩盖根因。","en":"Compare dates, filters, deduplication, joins and rounding. Provide a discrepancy breakdown and diagnostic queries, recalculating on equal definitions without manually patching totals.","ja":"期間、絞込、重複除去、結合、丸めを段階比較。差異表と調査クエリで同条件再計算し、合計手修正で原因を隠さない。"},"examples":{"zh":"请根据我提供的材料完成：报表数字对不上. 逐层核对时间范围、过滤、去重、连接和舍入，给差异拆解表与定位查询","en":"Using my supplied material, deliver: Report reconciliation. Compare dates, filters, deduplication, joins and rounding. Provide a discrepancy breakdown and diagnostic queries, recalculating on equal definitions without manually patching totals.","ja":"提供資料に基づき作成してください：集計値の不一致調査. 期間、絞込、重複除去、結合、丸めを段階比較"},"questions":{"zh":"请提供与“报表数字对不上”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For report reconciliation, provide source material, target software/use case and fixed constraints.","ja":"「集計値の不一致調査」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('learning-focused-analogies','published','{"id":"learning-focused-analogies","group":"learning","labels":{"zh":"用生活例子讲概念","en":"Explain with everyday analogies","ja":"身近なたとえで説明"},"terms":["用生活例子讲概念","Explain with everyday analogies","身近なたとえで説明","analogies"],"guidance":{"zh":"先给概念准确含义，再选贴近学习者的类比，并说明类比哪里不成立。给一个反例和小练习，避免为了通俗改变概念本质或按年龄低估理解力。","en":"Define the concept accurately, then use a familiar analogy with explicit limits. Add a counterexample and practice without distorting the concept or assuming ability from age.","ja":"正確な定義から身近な比喩と成立しない範囲を示す。反例と練習を付け、本質変更や年齢による過小評価を避ける。"},"examples":{"zh":"请根据我提供的材料完成：用生活例子讲概念. 先给概念准确含义，再选贴近学习者的类比，并说明类比哪里不成立","en":"Using my supplied material, deliver: Explain with everyday analogies. Define the concept accurately, then use a familiar analogy with explicit limits. Add a counterexample and practice without distorting the concept or assuming ability from age.","ja":"提供資料に基づき作成してください：身近なたとえで説明. 正確な定義から身近な比喩と成立しない範囲を示す"},"questions":{"zh":"请提供与“用生活例子讲概念”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For explain with everyday analogies, provide source material, target software/use case and fixed constraints.","ja":"「身近なたとえで説明」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('learning-focused-recall','published','{"id":"learning-focused-recall","group":"learning","labels":{"zh":"主动回忆与复习卡","en":"Active recall cards","ja":"能動想起・復習カード"},"terms":["主动回忆与复习卡","Active recall cards","能動想起・復習カード","recall"],"guidance":{"zh":"从提供材料提取单一知识点，制作问题、答案、出处和易错提醒。安排间隔复习建议，答案可独立核对，不把长段摘抄伪装成记忆卡。","en":"Create single-concept cards from supplied material with question, answer, source and pitfall. Suggest spaced review and independently checkable answers rather than long copied paragraphs.","ja":"提供資料から一概念の問い、答え、出典、誤解注意をカード化。間隔復習と照合可能な答えを出し、長文引用で代用しない。"},"examples":{"zh":"请根据我提供的材料完成：主动回忆与复习卡. 从提供材料提取单一知识点，制作问题、答案、出处和易错提醒","en":"Using my supplied material, deliver: Active recall cards. Create single-concept cards from supplied material with question, answer, source and pitfall. Suggest spaced review and independently checkable answers rather than long copied paragraphs.","ja":"提供資料に基づき作成してください：能動想起・復習カード. 提供資料から一概念の問い、答え、出典、誤解注意をカード化"},"questions":{"zh":"请提供与“主动回忆与复习卡”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For active recall cards, provide source material, target software/use case and fixed constraints.","ja":"「能動想起・復習カード」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('learning-focused-project','published','{"id":"learning-focused-project","group":"learning","labels":{"zh":"用小项目学技能","en":"Learn through a small project","ja":"小プロジェクトで学ぶ"},"terms":["用小项目学技能","Learn through a small project","小プロジェクトで学ぶ","project"],"guidance":{"zh":"按基础和可用时间定义一个最小项目，拆成可演示成果与检查点。每步给提示、示例和验收方式，卡住时先缩小问题；不以完成教程等同独立掌握。","en":"Scope a minimal project around prior knowledge and time, with demonstrable milestones. Supply hints, examples and acceptance checks; narrow blockers and distinguish tutorial completion from independent mastery.","ja":"基礎と時間に合う最小課題を成果・確認点に分ける。ヒント、例、受入を示し障害を絞る。教材完了を自立習得としない。"},"examples":{"zh":"请根据我提供的材料完成：用小项目学技能. 按基础和可用时间定义一个最小项目，拆成可演示成果与检查点","en":"Using my supplied material, deliver: Learn through a small project. Scope a minimal project around prior knowledge and time, with demonstrable milestones. Supply hints, examples and acceptance checks; narrow blockers and distinguish tutorial completion from independent mastery.","ja":"提供資料に基づき作成してください：小プロジェクトで学ぶ. 基礎と時間に合う最小課題を成果・確認点に分ける"},"questions":{"zh":"请提供与“用小项目学技能”有关的原始资料、目标软件或使用场景，以及不能改变的要求。","en":"For learn through a small project, provide source material, target software/use case and fixed constraints.","ja":"「小プロジェクトで学ぶ」に関する原資料、対象ソフト・用途、変更不可の条件を補足してください。"},"sourceReferences":[],"editorialStatus":"original-task-brief","status":"published"}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('language','draft','{"id":"language","status":"draft","labels":{"zh":"语言与翻译","en":"Language and translation","ja":"言語・翻訳"},"terms":["翻译","术语表","translation","glossary","翻訳","用語集"],"requirements":{"zh":"保留原意、术语和受众语气；标注无法判断的歧义。","en":"Preserve meaning, terminology and audience tone; flag unresolved ambiguity.","ja":"意味・用語・対象に合う文体を保ち、曖昧な点を示す。"}}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('education','draft','{"id":"education","status":"draft","labels":{"zh":"教学与学习","en":"Teaching and learning","ja":"教育・学習"},"terms":["教案","练习","lesson","exercise","授業","練習"],"requirements":{"zh":"按基础、目标和时间安排例题、练习与反馈。","en":"Adapt examples, exercises and feedback to prior knowledge, goals and available time.","ja":"前提知識・目標・時間に合わせ例題・練習・フィードバックを構成。"}}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('business','draft','{"id":"business","status":"draft","labels":{"zh":"商业分析","en":"Business analysis","ja":"事業分析"},"terms":["商业计划","竞品","business plan","competitor","事業計画","競合"],"requirements":{"zh":"区分事实、假设和待验证问题，注明数据日期与来源。","en":"Separate facts, assumptions and open questions; identify data dates and sources.","ja":"事実・仮定・未確認事項を区別し、データの日付と出典を示す。"}}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('life','draft','{"id":"life","status":"draft","labels":{"zh":"日常规划","en":"Daily planning","ja":"日常の計画"},"terms":["日程","计划","schedule","planning","予定","計画"],"requirements":{"zh":"围绕时间、资源和优先级制定可调整步骤。","en":"Build adjustable steps around time, resources and priorities.","ja":"時間・資源・優先順位に合わせ変更可能な手順を作る。"}}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
INSERT INTO task_resources (id,status,metadata_json) VALUES ('thinking','draft','{"id":"thinking","status":"draft","labels":{"zh":"思考与决策","en":"Thinking and decisions","ja":"思考・意思決定"},"terms":["决策","利弊","decision","tradeoff","意思決定","比較"],"requirements":{"zh":"比较可行选项的依据、代价与不确定性，列出决策条件。","en":"Compare feasible options, evidence, costs and uncertainty; state decision criteria.","ja":"選択肢の根拠・費用・不確実性を比較し判断条件を示す。"}}') ON CONFLICT(id) DO UPDATE SET status=excluded.status,metadata_json=excluded.metadata_json;
